import { Module } from '@nestjs/common';
import { MongooseModule } from '@nestjs/mongoose';
import { ConfigModule, ConfigService } from '@nestjs/config';
import * as path from 'path';

@Module({
  imports: [
    MongooseModule.forRootAsync({
      imports: [ConfigModule],
      useFactory: (configService: ConfigService) => {
        const uri =
          configService.get<string>('app.database.uri') ??
          process.env.MONGODB_URI ??
          '';
        const username = configService.get<string>('app.database.username');
        const password = configService.get<string>('app.database.password');

        if (typeof uri !== 'string' || !uri.trim()) {
          throw new Error(
            'MongoDB URI no configurada. Defina MONGODB_URI en el entorno o en .env antes de iniciar Nest o ejecutar scripts.',
          );
        }

        // Preservar esta heurística: en local no se fuerza TLS para no alterar
        // el comportamiento de desarrollo ya validado.
        const isLocal = configService.get<string>('app.nodeEnv') === 'development';
        const caPath = isLocal
          ? undefined
          : path.resolve(__dirname, '../../global-bundle.pem'); // Solo para no-local

        return {
          uri: uri.trim(),
          // authSource: username ? 'admin' : undefined, // Solo si hay username
          auth: username && password ? { username, password } : undefined,
          retryWrites: false,
          w: 'majority',
          maxPoolSize: 10,
          tls: !isLocal,
          tlsCAFile: caPath,
          tlsAllowInvalidHostnames: !isLocal,
          directConnection: true,
          serverSelectionTimeoutMS: 30000,
        };
      },
      inject: [ConfigService],
    }),
  ],
  exports: [MongooseModule],
})
export class DatabaseModule {}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ConfigService } from '@nestjs/config';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { ValidationPipe } from '@nestjs/common';
import { json, urlencoded, text } from 'express';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  const config = app.get(ConfigService);
  const port = config.get<number>('app.port') ?? 3000;

  // Mantener esta configuración HTTP exactamente como está hasta validar
  // compatibilidad con frontend, integraciones y despliegues existentes.
  app.enableCors({
    origin: true,
    credentials: true,
    methods: ['GET', 'HEAD', 'PUT', 'PATCH', 'POST', 'DELETE', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'X-Requested-With',
      'x-kiosk-token',
      'Cache-Control',
      'cache-control',
      'Pragma',
      'Last-Event-ID',
    ],
    exposedHeaders: ['Content-Disposition'],
    maxAge: 86400,
  });

  app.use(json({ limit: '5mb' }));
  app.use(urlencoded({ extended: true, limit: '5mb' }));
  app.use(text({ type: 'text/plain', limit: '5mb' }));

  // Este pipe global ya forma parte del comportamiento observable actual.
  // Cualquier ajuste aquí requiere validación funcional previa.
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
      transformOptions: { enableImplicitConversion: true },
    }),
  );

  // Swagger refleja el comportamiento actual; no introduce cambios funcionales.
  const swaggerCfg = new DocumentBuilder()
    .setTitle('Resultados API')
    .setDescription('API de resultados electorales')
    .setVersion('1.0')
    .addBearerAuth(
      {
        type: 'http',
        scheme: 'bearer',
        bearerFormat: 'JWT',
      },
      'bearer',
    )
    .addSecurityRequirements('bearer')
    .build();

  const document = SwaggerModule.createDocument(app, swaggerCfg);
  SwaggerModule.setup('api/docs', app, document, {
    swaggerOptions: { persistAuthorization: true },
    customSiteTitle: 'Resultados – API Docs',
  });

  await app.listen(port, '0.0.0.0');
}
bootstrap();

