    } else if (contractIdParam) {
      contractId = contractIdParam;
    } else {
      throw new BadRequestException(
        'contractId es requerido para usuarios SUPERADMIN',
      );
    }

    return this.clientReportsService.getAuditMatchReport({
      contractId,
      electionId,
      department,
      province,
      municipality,
      electoralSeat,
      electoralLocation,
      tableCode,
    });
