  async getClientContract(
    @Param('clientId') clientId: string,
    @Query('electionId') electionId: string,
  ) {
    if (!electionId) {
      throw new Error('electionId es obligatorio');
    }

    const contract = await this.contractsService.getClientContract(
      clientId,
      electionId,
    );

    if (!contract) {
