  /**
   * Obtener historial de contratos
   */
  @Get('my-history')
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({
    summary: 'Obtener historial completo de contratos del usuario',
    description: `
      Retorna todos los contratos del usuario (activos e inactivos).
      Permite filtrar por estado (active) y por elección específica (electionId).
    `,
  })
  @ApiQuery({
    name: 'active',
    required: false,
    type: Boolean,
    description: 'Filtrar por estado activo/inactivo',
  })
  @ApiQuery({
    name: 'electionId',
    required: false,
    type: String,
    description: 'Filtrar por elección específica',
  })
  @ApiResponse({
    status: 200,
    description: 'Historial de contratos del usuario',
  })
  async getMyContractHistory(
    @Request() req: any,
    @Query('active') active?: string,
    @Query('electionId') electionId?: string,
  ) {
    const userId = req.user?.sub;
    if (!userId) {
      throw new BadRequestException('Usuario no identificado');
    }

    const filters: any = {};

    if (active !== undefined) {
      filters.active = active === 'true';
    }

    if (electionId) {
      filters.electionId = electionId;
    }

    return this.contractsService.getContractHistory(userId, filters);
  }

  @Get('check-attestation-availability')
  @Public()
  @ApiOperation({
    summary: 'Verificar disponibilidad de atestiguamiento por ubicación',
    description: `
      Verifica qué elecciones están disponibles para atestiguar basándose en:
      - Ubicación del usuario (recinto electoral cercano)
      - Contratos activos en ese territorio
      - Configuraciones electorales activas

      Retorna las elecciones disponibles con información del territorio.
    `,
  })
  @ApiQuery({
    name: 'latitude',
    required: true,
    type: Number,
    example: -16.5,
    description: 'Latitud del usuario',
  })
  @ApiQuery({
    name: 'longitude',
    required: true,
    type: Number,
    example: -68.15,
    description: 'Longitud del usuario',
  })
  @ApiQuery({
    name: 'maxDistance',
    required: false,
    type: Number,
    example: 10000,
    description: 'Distancia máxima en metros (por defecto: 10000)',
  })
  @ApiResponse({
    status: 200,
    description: 'Disponibilidad verificada',
  })
  async checkAttestationAvailability(
    @Query('latitude') latitude: string,
    @Query('longitude') longitude: string,
    @Query('maxDistance') maxDistance?: string,
  ) {
    // Convertir a números
    const lat = parseFloat(latitude);
    const lng = parseFloat(longitude);
    const maxDist = maxDistance ? parseFloat(maxDistance) : 10000;

    // Validar que sean números válidos
    if (isNaN(lat) || isNaN(lng)) {
      throw new BadRequestException(
        'latitude y longitude deben ser números válidos',
      );
    }

    if (maxDistance && isNaN(maxDist)) {
      throw new BadRequestException('maxDistance debe ser un número válido');
    }

    return this.contractsService.checkAttestationAvailability(
      lat,
      lng,
      maxDist,
    );
  }

  private async getTerritorialUserOrThrow(
    userId: string,
    requester?: any,
  ): Promise<RoledUserDocument> {
    if (!Types.ObjectId.isValid(userId)) {
      throw new BadRequestException('userId inválido');
    }

    const user = await this.roledUserModel.findById(userId);
    if (
      requester?.role === 'ACCESS_APPROVER' &&
      user &&
      !['MAYOR', 'GOVERNOR'].includes(user.role)
    ) {
      throw new NotFoundException('Solicitud territorial no encontrada');
    }
    if (!user || !['MAYOR', 'GOVERNOR'].includes(user.role)) {
      throw new NotFoundException('Solicitud territorial no encontrada');
    }

    return user;
  }

  private async approveTerritorialAccess(userId: string, requester: any) {
    const user = await this.getTerritorialUserOrThrow(userId, requester);
    const status = this.resolveTerritorialStatus(user);

    if (status !== 'PENDING_APPROVAL') {
      throw new BadRequestException(
        'Solo se puede aprobar una solicitud territorial pendiente de aprobación',
      );
    }

    user.territorialAccessStatus = 'APPROVED';
    user.territorialApprovedAt = new Date();
    user.territorialRejectedAt = null;
    user.territorialRevokedAt = null;
    user.territorialReason = null;
    user.territorialApprovedBy = requester?.sub ? new Types.ObjectId(requester.sub) : null;
    await user.save();
    await this.authService.syncUserActiveState(user._id);

    return {
      message: 'Usuario aprobado exitosamente',
      user: this.toTerritorialAccessResponse(user),
    };
  }

  private async rejectTerritorialAccess(
    userId: string,
    reason: string | undefined,
    requester: any,
  ) {
    const user = await this.getTerritorialUserOrThrow(userId, requester);
    const status = this.resolveTerritorialStatus(user);

    if (status !== 'PENDING_APPROVAL') {
      throw new BadRequestException(
        'Solo se puede rechazar una solicitud territorial pendiente de aprobación',
      );
    }

    user.territorialAccessStatus = 'REJECTED';
    user.territorialRejectedAt = new Date();
    user.territorialApprovedAt = null;
    user.territorialRevokedAt = null;
    user.territorialReason = reason ?? null;
    user.territorialApprovedBy = requester?.sub ? new Types.ObjectId(requester.sub) : null;
    await user.save();
    await this.authService.syncUserActiveState(user._id);

    return {
      message: 'Usuario rechazado',
      user: this.toTerritorialAccessResponse(user),
    };
  }

  private resolveTerritorialStatus(user: any) {
    if (user.territorialAccessStatus && user.territorialAccessStatus !== 'NONE') {
      return user.territorialAccessStatus;
    }

    if ((user.role === 'MAYOR' || user.role === 'GOVERNOR') && user.active) {
      return 'APPROVED';
    }

    return 'NONE';
  }

  private toTerritorialAccessResponse(user: any) {
    return {
      id: user._id.toString(),
      dni: user.dni,
      email: user.email,
      name: user.name,
      role: user.role,
      active: user.active,
      territorialAccessStatus: this.resolveTerritorialStatus(user),
      emailVerified: !user.verificationToken,
      territory: {
        departmentId: user.votingDepartmentId?.toString() ?? null,
        municipalityId: user.votingMunicipalityId?.toString() ?? null,
      },
      approvedAt: user.territorialApprovedAt ?? null,
      rejectedAt: user.territorialRejectedAt ?? null,
      revokedAt: user.territorialRevokedAt ?? null,
      reason: user.territorialReason ?? null,
      createdAt: user.createdAt ?? null,
      updatedAt: user.updatedAt ?? null,
    };
  }
}

// src/modules/contracts/controllers/delegates.controller.ts
import {
  Controller,
  Get,
  Post,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  Request,
  UseInterceptors,
  UploadedFile,
  BadRequestException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBearerAuth,
  ApiConsumes,
  ApiBody,
} from '@nestjs/swagger';
import { DelegatesService } from '../services/delegates.service';
import { AddDelegateDto, RemoveDelegateDto } from '../dto/delegates.dto';
import { JwtAuthGuard } from '../../../core/guards/jwt-auth.guard';
import { AdminOnlyGuard } from '@/core/guards/admin-only.guard';
import { Multer } from 'multer';

@ApiTags('Delegates')
@Controller('api/v1/delegates')
export class DelegatesController {
  constructor(private readonly delegatesService: DelegatesService) {}

  @Post('upload-csv')
  @ApiBearerAuth()
  @UseGuards(AdminOnlyGuard)
  @UseInterceptors(FileInterceptor('file'))
  @ApiConsumes('multipart/form-data')
  @ApiOperation({
    summary: 'Cargar lista oficial de delegados desde archivo CSV (Superadmin)',
    description:
      'Permite al Superadmin cargar masivamente la lista de delegados autorizados para un contrato. Formato CSV: dni,name,phone,email',
  })
  @ApiBody({
    schema: {
      type: 'object',
      required: ['file', 'contractId'],
      properties: {
        file: {
          type: 'string',
          format: 'binary',
          description: 'Archivo CSV con formato: dni,name,phone,email',
        },
        contractId: {
          type: 'string',
          description: 'ID del contrato',
        },
      },
    },
  })
  @ApiResponse({
    status: 201,
    description: 'Delegados cargados exitosamente',
    schema: {
      properties: {
        added: { type: 'number' },
        updated: { type: 'number' },
        errors: { type: 'array' },
      },
    },
  })
  async uploadCsv(
    @UploadedFile() file: Multer.File,
    @Body('contractId') contractId: string,
    @Request() req: any,
  ) {
    if (!file) {
      throw new BadRequestException('Debe proporcionar un archivo CSV');
    }

    if (!contractId) {
      throw new BadRequestException('Debe proporcionar el contractId');
    }

    // Convertir el buffer del archivo a string
    const csvContent = file.buffer.toString('utf-8');

    const superadminId = req.user.sub;

    const result = await this.delegatesService.uploadDelegatesCsv({
      csvContent,
      contractId,
      superadminId,
    });

    return {
      message: 'Carga completada',
      fileName: file.originalname,
      summary: {
        added: result.added,
        updated: result.updated,
        totalErrors: result.errors.length,
      },
      errors: result.errors,
    };
  }

  /**
   * Agregar un delegado manualmente
   */
  @Post()
  @ApiBearerAuth()
  @UseGuards(AdminOnlyGuard)
  @ApiOperation({
    summary: 'Agregar un delegado manualmente (Superadmin)',
  })
  @ApiResponse({ status: 201, description: 'Delegado agregado exitosamente' })
  async add(@Body() dto: AddDelegateDto, @Request() req: any) {
    const delegate = await this.delegatesService.addDelegate({
      dni: dto.dni,
      contractId: dto.contractId,
      superadminId: req.user.sub,
      name: dto.name,
      phone: dto.phone,
      email: dto.email,
    });

    return {
      id: delegate._id.toString(),
      dni: delegate.dni,
      name: delegate.name,
      authorizedContracts: delegate.authorizedContracts.map((ac) => ({
        contractId: ac.contractId.toString(),
        clientRole: ac.clientRole,
        addedAt: ac.addedAt,
      })),
    };
  }

  /**
   * Listar delegados de un contrato
   */
  @Get('contract/:contractId')
  @UseGuards(JwtAuthGuard, AdminOnlyGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Listar delegados de un contrato' })
  @ApiResponse({
    status: 200,
    description: 'Lista de delegados',
  })
  async listByContract(@Param('contractId') contractId: string) {
    const delegates = await this.delegatesService.listByContract(contractId);

    return {
      data: delegates.map((d) => {
        // Después del populate, userId es un objeto, no ObjectId
        const user = d.userId as any;

        return {
          id: d._id.toString(),
          dni: d.dni,
          userId: user?._id?.toString() || user?.toString(),
          user: user?._id
            ? {
                dni: user.dni,
                votingLocationId: user.votingLocationId?.toString() || null,
                votingTableId: user.votingTableId?.toString() || null,
              }
            : undefined,
          name: d.name,
          phone: d.phone,
          email: d.email,
          active: d.active,
          contracts: d.authorizedContracts
            .filter((ac) => ac.contractId.toString() === contractId)
            .map((ac) => ({
              clientRole: ac.clientRole,
              addedAt: ac.addedAt,
            })),
        };
      }),
      total: delegates.length,
    };
  }

  /**
   * Verificar autorización de un DNI
   */
  @Get('check-authorization')
  @ApiOperation({
    summary: 'Verificar si un DNI está autorizado para un contrato',
    description:
      'Usado para validar que un atestiguamiento proviene de un delegado oficial',
  })
  @ApiResponse({
    status: 200,
    schema: {
      properties: {
        isAuthorized: { type: 'boolean' },
        contracts: { type: 'array' },
      },
    },
  })
  async checkAuthorization(
    @Query('dni') dni: string,
    @Query('contractId') contractId?: string,
  ) {
    if (contractId) {
      const isAuthorized = await this.delegatesService.isAuthorizedForContract(
        dni,
        contractId,
      );
      return { isAuthorized, contractId };
    }

    // Sin contractId, devolver todos los contratos del delegado
    const contracts = await this.delegatesService.getAuthorizedContracts(dni);
    return {
      isAuthorized: contracts.length > 0,
      contracts,
    };
  }

  /**
   * Remover un delegado de un contrato
   */
  @Delete()
  @ApiBearerAuth()
  @UseGuards(AdminOnlyGuard)
  @ApiOperation({
    summary: 'Remover un delegado de un contrato (Superadmin)',
  })
  @ApiResponse({
    status: 200,
    description: 'Delegado removido del contrato',
  })
  async remove(@Body() dto: RemoveDelegateDto) {
    await this.delegatesService.removeFromContract(dto.dni, dto.contractId);
    return {
      message: 'Delegado removido del contrato exitosamente',
    };
  }

  /**
   * Obtener contratos autorizados para un DNI
   * Útil para el caso 3.1 (delegado multi-contrato)
   */
  @Get('authorized-contracts/:dni')
  @ApiOperation({
    summary: 'Obtener contratos autorizados para un delegado',
    description:
      'Devuelve la lista de contratos para los que un delegado está autorizado (multi-contrato)',
  })
  @ApiResponse({
    status: 200,
    description: 'Lista de contratos autorizados',
  })
  async getAuthorizedContracts(@Param('dni') dni: string) {
    const contracts = await this.delegatesService.getAuthorizedContracts(dni);

    return {
      dni,
      contracts,
      count: contracts.length,
    };
  }
}

// src/modules/contracts/guards/territorial-restriction.guard.ts
import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import { Contract } from '../schemas/contract.schema';

/**
 * UC5: Restringir consultas y filtros por rol y territorio
 * 
 * Este guard valida que un Alcalde/Gobernador solo acceda a datos
 * dentro de su territorio contratado
 */
@Injectable()
export class TerritorialRestrictionGuard implements CanActivate {
  constructor(
    @InjectModel(Contract.name) private contractModel: Model<Contract>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const user = request.user; // Del JWT

    if (!user) {
      throw new ForbiddenException('No autenticado');
    }

    const url: string = request.originalUrl || request.url || '';
    if (url.includes('/client-reports/my-active-contract')) {
      return true;
    }

    // Si no es Alcalde ni Gobernador, permitir acceso (ej: Superadmin)
    if (!user.role || !['MAYOR', 'GOVERNOR'].includes(user.role)) {
      return true;
    }

    // Obtener el contrato activo del usuario
    const electionId = request.query.electionId || request.body?.electionId;
    if (!electionId) {
      throw new ForbiddenException(
        'electionId es requerido para usuarios con rol',
      );
    }

    const contract = await this.contractModel
      .findOne({
        clientId: new Types.ObjectId(user.sub as string),
        electionId: new Types.ObjectId(electionId as string),
        active: true,
      })
      .lean();

    if (!contract) {
      throw new ForbiddenException(
        'No tiene un contrato activo para esta elección',
      );
    }

    // Aplicar restricciones según el territorio del contrato
    this.applyTerritorialRestrictions(request, contract);

    // Guardar contrato en request para uso posterior
    request.contract = contract;

    return true;
  }

  /**
   * Aplicar restricciones territoriales a los parámetros de la request
   */
  private applyTerritorialRestrictions(request: any, contract: any) {
    const params = { ...request.query, ...request.body };

    if (contract.municipalityId) {
      // Alcalde: solo puede ver su municipio
      if (
        params.municipality &&
        params.municipality !== contract.municipalityName
      ) {
        throw new ForbiddenException(
          'No tiene acceso a datos fuera de su municipio',
        );
      }
      // Forzar filtro por municipio
      request.query.municipality = contract.municipalityName;
      if (request.body) {
        request.body.municipality = contract.municipalityName;
      }
    } else if (contract.departmentId) {
      // Gobernador: solo puede ver su departamento
      if (
        params.department &&
        params.department !== contract.departmentName
      ) {
        throw new ForbiddenException(
          'No tiene acceso a datos fuera de su departamento',
        );
      }
      // Forzar filtro por departamento
      request.query.department = contract.departmentName;
      if (request.body) {
        request.body.department = contract.departmentName;
      }
    }
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import { Contract } from '../schemas/contract.schema';
import { Delegate } from '../schemas/delegate.schema';
import { Attestation } from '../../attestation/schemas/attestation.schema';
import { Ballot } from '../../ballot/schemas/ballot.schema';
import { BallotComparison } from '../../attestation/schemas/ballot-comparison.schema';

/**
 * UC4: Reporte del Alcalde/Gobernador
 * Actividad de delegados por mesas/recintos
 */
@Injectable()
export class ClientReportsService {
  private readonly logger = new Logger(ClientReportsService.name);

  constructor(
    @InjectModel(Contract.name) private contractModel: Model<Contract>,
    @InjectModel(Delegate.name) private delegateModel: Model<Delegate>,
    @InjectModel(Attestation.name) private attestationModel: Model<Attestation>,
    @InjectModel(Ballot.name) private ballotModel: Model<Ballot>,
    @InjectModel(BallotComparison.name)
    private ballotComparisonModel: Model<BallotComparison>,
  ) {}

  /**
   * UC4: Reporte de actividad de delegados
   */
  async getDelegateActivityReport(params: {
    contractId: string;
    electionId: string;
    groupBy?: 'delegate' | 'location' | 'table';
  }) {
    const contract = await this.contractModel.findById(params.contractId).lean();
    if (!contract) {
      throw new NotFoundException('Contrato no encontrado');
    }

    // Obtener delegados autorizados
    const delegates = await this.delegateModel
      .find({
        'authorizedContracts.contractId': new Types.ObjectId(params.contractId),
        active: true,
      })
      .lean();

    const delegateUserIds = delegates.map((d) => d.userId);
    this.logger.debug(
      `[delegate-activity] electionId=${params.electionId} contractId=${params.contractId} delegates=${delegates.length} department=${contract.departmentName ?? 'null'} municipality=${contract.municipalityName ?? 'null'}`,
    );

    const attestations = await this.getContractAttestations({
      contract,
      contractId: params.contractId,
      electionId: params.electionId,
      delegateUserIds,
      includeUser: true,
    });

    // Agrupar según el parámetro
    switch (params.groupBy) {
      case 'delegate':
        return this.groupByDelegate(attestations, delegates);
      case 'location':
        return this.groupByLocation(attestations, delegates);
      case 'table':
        return this.groupByTable(attestations, delegates);
      default:
        return this.groupByDelegate(attestations, delegates);
    }
  }

  /**
   * Agrupar por delegado
   */
  private groupByDelegate(attestations: any[], delegates: any[]) {
    const delegateMap = new Map();

    // Inicializar todos los delegados (incluso sin actividad)
    delegates.forEach((d) => {
      delegateMap.set(d.dni, {
        dni: d.dni,
        name: d.name || 'Sin nombre',
        totalAttestations: 0,
        tablesAttested: new Set(),
        locations: new Set(),
        support: 0,
        against: 0,
        lastActivity: null,
      });
    });

    // Agregar actividad
    attestations.forEach((att) => {
      const delegate = delegateMap.get(att.dni);
      if (delegate) {
        delegate.totalAttestations++;
        delegate.tablesAttested.add(att.tableCode);
        if (att.location?.electoralLocationName) {
          delegate.locations.add(att.location.electoralLocationName);
        }
        if (att.support) {
          delegate.support++;
        } else {
          delegate.against++;
        }
        if (!delegate.lastActivity || att.createdAt > delegate.lastActivity) {
          delegate.lastActivity = att.createdAt;
        }
      }
    });

    // Convertir Sets a arrays y contar
    const result = Array.from(delegateMap.values()).map((d) => ({
      ...d,
      tablesCount: d.tablesAttested.size,
      locationsCount: d.locations.size,
      tablesAttested: Array.from(d.tablesAttested),
      locations: Array.from(d.locations),
    }));

    return {
      groupBy: 'delegate',
      totalDelegates: delegates.length,
      activeDelegates: result.filter((d) => d.totalAttestations > 0).length,
      data: result.sort((a, b) => b.totalAttestations - a.totalAttestations),
    };
  }

  /**
   * Agrupar por ubicación (recinto)
   */
  private groupByLocation(attestations: any[], delegates?: any[]) {
    // Crear mapa de delegados para obtener nombres
    const delegateInfoMap = new Map<string, any>();
    if (delegates) {
      delegates.forEach((d) => {
        delegateInfoMap.set(d.dni, {
          dni: d.dni,
          name: d.name || 'Sin nombre',
          phone: d.phone,
          email: d.email,
        });
      });
    }

    const locationMap = new Map();

    attestations.forEach((att) => {
      const locName = att.location?.electoralLocationName || 'Sin ubicación';
      if (!locationMap.has(locName)) {
        locationMap.set(locName, {
          location: locName,
          department: att.location?.department,
          municipality: att.location?.municipality,
          delegateDetails: new Map<string, any>(),
          tables: new Set(),
          totalAttestations: 0,
          support: 0,
          against: 0,
        });
      }
      const loc = locationMap.get(locName);

      // Agregar o actualizar delegado
      if (!loc.delegateDetails.has(att.dni)) {
        const info = delegateInfoMap.get(att.dni) || { dni: att.dni };
        loc.delegateDetails.set(att.dni, {
          dni: att.dni,
          name: info.name || 'Sin nombre',
          phone: info.phone || null,
          email: info.email || null,
          attestationsCount: 0,
        });
      }
      loc.delegateDetails.get(att.dni).attestationsCount++;

      loc.tables.add(att.tableCode);
      loc.totalAttestations++;
      if (att.support) {
        loc.support++;
      } else {
        loc.against++;
      }
    });

    const result = Array.from(locationMap.values()).map((loc) => ({
      location: loc.location,
      department: loc.department,
      municipality: loc.municipality,
      totalAttestations: loc.totalAttestations,
      support: loc.support,
      against: loc.against,
      delegatesCount: loc.delegateDetails.size,
      tablesCount: loc.tables.size,
      delegates: Array.from(loc.delegateDetails.values()),
      tables: Array.from(loc.tables),
    }));

    return {
      groupBy: 'location',
      totalLocations: result.length,
      data: result.sort((a, b) => b.totalAttestations - a.totalAttestations),
    };
  }

  /**
   * Agrupar por mesa
   */
  private groupByTable(attestations: any[], delegates?: any[]) {
    // Crear mapa de delegados para obtener nombres
    const delegateInfoMap = new Map<string, any>();
    if (delegates) {
      delegates.forEach((d) => {
        delegateInfoMap.set(d.dni, {
          dni: d.dni,
          name: d.name || 'Sin nombre',
          phone: d.phone,
          email: d.email,
        });
      });
    }

    const tableMap = new Map();

    attestations.forEach((att) => {
      const tableCode = att.tableCode;
      if (!tableMap.has(tableCode)) {
        tableMap.set(tableCode, {
          tableCode,
          tableNumber: att.tableNumber || null,
          location: att.location?.electoralLocationName,
          municipality: att.location?.municipality,
          department: att.location?.department,
          ballotId: att.ballotId?.toString() || null,
          attestationDetails: [],
          totalAttestations: 0,
          support: 0,
          against: 0,
          firstAttestation: att.createdAt,
          lastAttestation: att.createdAt,
        });
      }
      const table = tableMap.get(tableCode);

      // Agregar detalle del atestiguamiento
      const delegateInfo = delegateInfoMap.get(att.dni) || { dni: att.dni };
      table.attestationDetails.push({
        dni: att.dni,
        delegateName: delegateInfo.name || 'Sin nombre',
        delegatePhone: delegateInfo.phone || null,
        delegateEmail: delegateInfo.email || null,
        support: att.support,
        attestedAt: att.createdAt,
        ballotId: att.ballotId?.toString() || null,
      });

      table.totalAttestations++;
      if (att.support) {
        table.support++;
      } else {
        table.against++;
      }
      if (att.createdAt < table.firstAttestation) {
        table.firstAttestation = att.createdAt;
      }
      if (att.createdAt > table.lastAttestation) {
        table.lastAttestation = att.createdAt;
      }
    });

    const result = Array.from(tableMap.values()).map((table) => {
      // Extraer DNIs únicos de delegados
      const uniqueDelegates = [
        ...new Map(
          table.attestationDetails.map((a: any) => [a.dni, a]),
        ).values(),
      ].map((a: any) => ({
        dni: a.dni,
        name: a.delegateName,
        phone: a.delegatePhone,
        email: a.delegateEmail,
      }));

      return {
        tableCode: table.tableCode,
        tableNumber: table.tableNumber,
        location: table.location,
        municipality: table.municipality,
        department: table.department,
        ballotId: table.ballotId,
        totalAttestations: table.totalAttestations,
        support: table.support,
        against: table.against,
        firstAttestation: table.firstAttestation,
        lastAttestation: table.lastAttestation,
        delegatesCount: uniqueDelegates.length,
        delegates: uniqueDelegates,
        attestationDetails: table.attestationDetails,
      };
    });

    return {
      groupBy: 'table',
      totalTables: result.length,
      data: result.sort((a, b) => b.totalAttestations - a.totalAttestations),
    };
  }

  /**
   * Resumen ejecutivo para el cliente
   */
  async getExecutiveSummary(params: {
    contractId: string;
    electionId: string;
  }) {
    const contract = await this.contractModel.findById(params.contractId).lean();
    if (!contract) {
      throw new NotFoundException('Contrato no encontrado');
    }

    // Total de delegados autorizados
    const totalDelegates = await this.delegateModel.countDocuments({
      'authorizedContracts.contractId': new Types.ObjectId(params.contractId),
      active: true,
    });

    const delegates = await this.delegateModel
      .find({
        'authorizedContracts.contractId': new Types.ObjectId(params.contractId),
        active: true,
      })
      .lean();

    const delegateUserIds = delegates.map((d) => d.userId);
    this.logger.debug(
      `[executive-summary] electionId=${params.electionId} contractId=${params.contractId} delegates=${delegates.length} department=${contract.departmentName ?? 'null'} municipality=${contract.municipalityName ?? 'null'}`,
    );
    const attestations = await this.getContractAttestations({
      contract,
      contractId: params.contractId,
      electionId: params.electionId,
      delegateUserIds,
      includeUser: true,
    });

    const activeDelegates = new Set(
      attestations.map((att: any) => String(att.userId)),
    );
    const uniqueTables = new Set(
      attestations.map((att: any) => att.tableCode).filter(Boolean),
    );
    const uniqueLocations = new Set(
      attestations
        .map((att: any) => att.location?.electoralLocationName)
        .filter(Boolean),
    );
    const totalAttestations = attestations.length;

    return {
      contract: {
        id: contract._id.toString(),
        clientRole: contract.clientRole,
        territory: {
          departmentName: contract.departmentName,
          municipalityName: contract.municipalityName,
        },
      },
      summary: {
        totalDelegatesAuthorized: totalDelegates,
        activeDelegates: activeDelegates.size,
        participationRate:
          totalDelegates > 0
            ? ((activeDelegates.size / totalDelegates) * 100).toFixed(2) + '%'
            : '0%',
        totalAttestations,
        uniqueTablesAttested: uniqueTables.size,
        uniqueLocationsAttested: uniqueLocations.size,
        avgAttestationsPerDelegate:
          activeDelegates.size > 0
            ? (totalAttestations / activeDelegates.size).toFixed(2)
            : '0',
      },
    };
  }

  async getAuditMatchReport(params: {
    contractId: string;
    electionId: string;
    department?: string;
    province?: string;
    municipality?: string;
    electoralSeat?: string;
    electoralLocation?: string;
    tableCode?: string;
  }) {
    const contract = await this.contractModel.findById(params.contractId).lean();
    if (!contract) {
      throw new NotFoundException('Contrato no encontrado');
    }

    const delegates = await this.delegateModel
      .find({
        'authorizedContracts.contractId': new Types.ObjectId(params.contractId),
        active: true,
      })
      .lean();

    const delegateUserIds = delegates.map((d) => d.userId);
    this.logger.debug(
      `[audit-match] electionId=${params.electionId} contractId=${params.contractId} delegates=${delegates.length} department=${contract.departmentName ?? 'null'} municipality=${contract.municipalityName ?? 'null'}`,
    );
    const rows = await this.getContractAttestations({
      contract,
      contractId: params.contractId,
      electionId: params.electionId,
      delegateUserIds,
      includeUser: true,
      extraProjection: {
        version: '$ballot.version',
        delegateName: '$user.name',
        delegateDni: '$user.dni',
      },
    });

    const filteredRows = rows.filter((row: any) => {
      if (params.department && row.location?.department !== params.department)
        return false;
      if (params.province && row.location?.province !== params.province)
        return false;
      if (
        params.municipality &&
        row.location?.municipality !== params.municipality
      )
        return false;
      if (
        params.electoralSeat &&
        row.location?.electoralSeat !== params.electoralSeat
      )
        return false;
      if (
        params.electoralLocation &&
        row.location?.electoralLocationName !== params.electoralLocation
      )
        return false;
      if (params.tableCode && row.tableCode !== params.tableCode) return false;
      return true;
    });

    const byBallot = new Map<string, any>();
    for (const row of filteredRows) {
      const key = String(row.ballotId);
      if (!byBallot.has(key)) {
        byBallot.set(key, {
          ballotId: key,
          tableCode: row.tableCode,
          mesa: row.tableNumber || row.tableCode,
          recinto: row.location?.electoralLocationName || 'Sin ubicación',
          version: row.version ?? null,
          delegates: new Map<string, string>(),
        });
      }
      const item = byBallot.get(key);
      item.delegates.set(
        String(row.delegateDni || row.delegateName || key),
        row.delegateName || row.delegateDni || 'Sin nombre',
      );
    }

    const ballotIds = Array.from(byBallot.keys())
      .filter((id) => Types.ObjectId.isValid(id))
      .map((id) => new Types.ObjectId(id));

    const comparisons = ballotIds.length
      ? await this.ballotComparisonModel
          .find({ ballotId: { $in: ballotIds } })
          .lean()
          .exec()
      : [];

    const comparisonMap = new Map(
      comparisons.map((comparison: any) => [
        String(comparison.ballotId),
        comparison,
      ]),
    );

    const details = Array.from(byBallot.values())
      .map((item) => {
        const comparison = comparisonMap.get(item.ballotId);
        const status = String(comparison?.status || 'PENDING');
        return {
          _id: item.ballotId,
          ballotId: item.ballotId,
          recinto: item.recinto,
          mesa: item.mesa,
          tableCode: item.tableCode,
          version: item.version,
          testigo: Array.from(item.delegates.values()).join(', '),
          auditoria: this.mapAuditStatusLabel(status),
          comparisonStatus: status,
          comparedAt: comparison?.comparedAt ?? null,
          mismatches: comparison?.mismatches ?? [],
        };
      })
      .sort((a, b) => a.recinto.localeCompare(b.recinto) || a.mesa.localeCompare(b.mesa));

    const observados = details.filter(
      (item) => item.comparisonStatus === 'MISMATCH',
    ).length;

    return {
      observados,
      sinObservaciones: details.filter(
        (item) => item.comparisonStatus === 'MATCH',
      ).length,
      pendientes: details.filter(
        (item) => item.comparisonStatus !== 'MATCH' && item.comparisonStatus !== 'MISMATCH',
      ).length,
      total: details.length,
      details,
    };
  }

  private mapAuditStatusLabel(
    status: string,
  ): 'Sin Obs' | 'No coincide' | 'Pendiente' {
    if (status === 'MATCH') return 'Sin Obs';
    if (status === 'MISMATCH') return 'No coincide';
    return 'Pendiente';
  }

  private buildTerritoryFallbackMatch(contract: any) {
    if (contract.municipalityName) {
      return {
        'ballot.location.municipality': contract.municipalityName,
      };
    }

    if (contract.departmentName) {
      return {
        'ballot.location.department': contract.departmentName,
      };
    }

    return null;
  }

  private async getContractAttestations(params: {
    contract: any;
    contractId: string;
    electionId: string;
    delegateUserIds: Types.ObjectId[];
    includeUser?: boolean;
    extraProjection?: Record<string, any>;
  }) {
    if (params.delegateUserIds.length === 0) {
      this.logger.debug(
        `[client-report-debug] electionId=${params.electionId} contractId=${params.contractId} delegateUserIds=0`,
      );
      return [];
    }

    const contractId = new Types.ObjectId(params.contractId);
    const fallbackMatch = this.buildTerritoryFallbackMatch(params.contract);
    const territoryField = params.contract.municipalityName
      ? 'municipality'
      : params.contract.departmentName
        ? 'department'
        : 'none';
    const territoryValue =
      params.contract.municipalityName || params.contract.departmentName || null;
    const contractScopeMatch = fallbackMatch
      ? {
          $or: [
            {
              isValidForClientReport: true,
              validForContractId: contractId,
            },
            fallbackMatch,
          ],
        }
      : {
          isValidForClientReport: true,
          validForContractId: contractId,
        };

    const pipeline: any[] = [
      {
        $match: {
          userId: { $in: params.delegateUserIds },
          electionId: new Types.ObjectId(params.electionId),
        },
      },
      {
        $lookup: {
          from: 'ballots',
          localField: 'ballotId',
          foreignField: '_id',
          as: 'ballot',
        },
      },
      { $unwind: '$ballot' },
      {
        $addFields: {
          _matchedByFlags: {
            $and: [
              { $eq: ['$isValidForClientReport', true] },
              { $eq: ['$validForContractId', contractId] },
            ],
          },
          _matchedByTerritory:
            territoryField === 'municipality'
              ? {
                  $eq: [
                    '$ballot.location.municipality',
                    params.contract.municipalityName,
                  ],
                }
              : territoryField === 'department'
                ? {
                    $eq: [
                      '$ballot.location.department',
                      params.contract.departmentName,
                    ],
                  }
                : false,
        },
      },
      { $match: contractScopeMatch },
    ];

    if (params.includeUser) {
      pipeline.push(
        {
          $lookup: {
            from: 'users',
            localField: 'userId',
            foreignField: '_id',
            as: 'user',
          },
        },
        { $unwind: '$user' },
      );
    }

    pipeline.push({
      $project: {
        userId: 1,
        dni: '$user.dni',
        ballotId: '$ballot._id',
        tableCode: '$ballot.tableCode',
        tableNumber: '$ballot.tableNumber',
        location: '$ballot.location',
        createdAt: 1,
        support: 1,
        _matchedByFlags: 1,
        _matchedByTerritory: 1,
        ...(params.extraProjection || {}),
      },
    });

    const rows = await this.attestationModel.aggregate(pipeline).exec();

    const byFlags = rows.filter((row: any) => row._matchedByFlags).length;
    const byTerritory = rows.filter(
      (row: any) => row._matchedByTerritory,
    ).length;
    const fallbackOnly = rows.filter(
      (row: any) => !row._matchedByFlags && row._matchedByTerritory,
    ).length;

    this.logger.debug(
      `[client-report-debug] electionId=${params.electionId} contractId=${params.contractId} territoryField=${territoryField} territoryValue=${territoryValue ?? 'null'} delegateUserIds=${params.delegateUserIds.length} rows=${rows.length} byFlags=${byFlags} byTerritory=${byTerritory} fallbackOnly=${fallbackOnly}`,
    );

    return rows;
  }
}

import {
  Injectable,
  ForbiddenException,
  UnauthorizedException,
} from '@nestjs/common';
import { InjectConnection } from '@nestjs/mongoose';
import { Connection } from 'mongoose';
import { ResultsService } from '@/modules/results/services/results.service';
import { ElectionTypeFilterDto } from '@/modules/results/dto/results.dto';
import { ContractsService } from './contracts.service';

@Injectable()
export class ClientResultsService {
  constructor(
    private readonly contractsService: ContractsService,
    private readonly resultsService: ResultsService,
    @InjectConnection() private readonly connection: Connection,
  ) {}

  async getResultsRestrictedToMyContract(
    params: Pick<ElectionTypeFilterDto, 'electionType' | 'electionId'> & {
      mode?: 'final' | 'live';
      // Sub-filtros opcionales
      province?: string;
      municipality?: string;
      electoralSeat?: string;
      electoralLocation?: string;
      tableCode?: string;
    },
    userId: string,
  ) {
    if (!userId) {
      throw new UnauthorizedException('Usuario no autenticado');
    }

    if (!params?.electionType) {
      throw new ForbiddenException('Debe enviar electionType');
    }
    if (!params?.electionId) {
      throw new ForbiddenException('Debe enviar electionId');
    }

    const my = await this.contractsService.getMyContract({
      userId,
      electionId: params.electionId,
    });

    if (!my?.hasContract || !my.contract?.active) {
      throw new ForbiddenException(
        'No tiene contrato activo para esta elección',
      );
    }

    const c = my.contract;

    // Forzar territorio según el contrato
    const forcedFilters: any = {
      electionType: params.electionType,
      electionId: params.electionId,
      mode: params.mode || 'final',
    };

    if (c.municipalityId) {
      // MAYOR: territorio forzado a municipio, sub-filtros permitidos: electoralSeat, electoralLocation, tableCode
      if (!c.municipalityName) {
        throw new ForbiddenException('Contrato sin municipalityName');
      }
      forcedFilters.municipality = c.municipalityName;

      // Bloquear province/municipality como sub-filtro para Mayor (ya tiene municipio forzado)
      if (params.province) {
        throw new ForbiddenException(
          'Alcaldes no pueden filtrar por provincia',
        );
      }
      if (params.municipality && params.municipality !== c.municipalityName) {
        throw new ForbiddenException(
          'No puede filtrar por un municipio diferente al de su contrato',
        );
      }

      // Validar que electoralSeat esté dentro del municipio del contrato
      if (params.electoralSeat) {
        const seatInMunicipality = await this.connection
          .collection('ballots')
          .findOne({
            'location.municipality': c.municipalityName,
            'location.electoralSeat': params.electoralSeat,
          });
        if (!seatInMunicipality) {
          throw new ForbiddenException(
            `El recinto electoral '${params.electoralSeat}' no pertenece a su municipio`,
          );
        }
        forcedFilters.electoralSeat = params.electoralSeat;
      }

      if (params.electoralLocation) forcedFilters.electoralLocation = params.electoralLocation;
      if (params.tableCode) forcedFilters.tableCode = params.tableCode;
    } else if (c.departmentId) {
      // GOVERNOR: territorio forzado a departamento, sub-filtros permitidos: province, municipality, electoralSeat, etc.
      if (!c.departmentName) {
        throw new ForbiddenException('Contrato sin departmentName');
      }
      forcedFilters.department = c.departmentName;

      // Validar que province esté dentro del departamento del contrato
      if (params.province) {
        const provinceInDept = await this.connection
          .collection('ballots')
          .findOne({
            'location.department': c.departmentName,
            'location.province': params.province,
          });
        if (!provinceInDept) {
          throw new ForbiddenException(
            `La provincia '${params.province}' no pertenece a su departamento`,
          );
        }
        forcedFilters.province = params.province;
      }

      // Validar que municipality esté dentro del departamento del contrato
      if (params.municipality) {
        const municipalityInDept = await this.connection
          .collection('ballots')
          .findOne({
            'location.department': c.departmentName,
            'location.municipality': params.municipality,
          });
        if (!municipalityInDept) {
          throw new ForbiddenException(
            `El municipio '${params.municipality}' no pertenece a su departamento`,
          );
        }
        forcedFilters.municipality = params.municipality;
      }

      if (params.electoralSeat) forcedFilters.electoralSeat = params.electoralSeat;
      if (params.electoralLocation) forcedFilters.electoralLocation = params.electoralLocation;
      if (params.tableCode) forcedFilters.tableCode = params.tableCode;
    } else {
      throw new ForbiddenException('Territorio de contrato inválido');
    }

    return this.resultsService.getResultsByLocation(forcedFilters);
  }
}

import {
  Injectable,
  BadRequestException,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import { Contract, ContractDocument } from '../schemas/contract.schema';
import {
  RoledUser,
  RoledUserDocument,
} from '../../auth/schemas/roledUser.schema';
import { Department } from '../../geographic/schemas/department.schema';
import { Municipality } from '../../geographic/schemas/municipality.schema';
import { ElectionConfigService } from '@/modules/elections/services/election-config.service';
import { ElectoralLocationService } from '@/modules/geographic/services/electoral-location.service';

@Injectable()
export class ContractsService {
  constructor(
    @InjectModel(Contract.name) private contractModel: Model<ContractDocument>,
    @InjectModel(RoledUser.name)
    private roledUserModel: Model<RoledUserDocument>,
    @InjectModel(Department.name) private departmentModel: Model<Department>,
    @InjectModel(Municipality.name)
    private municipalityModel: Model<Municipality>,
    private electoralLocationService: ElectoralLocationService,
    private electionConfigService: ElectionConfigService,
  ) {}

  /**
   * Crear un contrato para un cliente aprobado
   */
  async create(dto: {
    clientId: string;
    electionId: string;
    departmentId?: string;
    municipalityId?: string;
    startDate: Date;
    endDate?: Date;
  }): Promise<ContractDocument> {
    // Validar que el cliente existe y está activo
    const client = await this.roledUserModel.findById(dto.clientId);
    if (!client) {
      throw new NotFoundException('Cliente no encontrado');
    }
    if (!client.active) {
      throw new BadRequestException('El cliente no está activo/aprobado');
    }

    // Validar que solo haya un territorio
    if (
      (!dto.departmentId && !dto.municipalityId) ||
      (dto.departmentId && dto.municipalityId)
    ) {
      throw new BadRequestException(
        'Debe proporcionar exactamente un territorio (departamento O municipio)',
      );
    }

    // Validar coherencia entre rol y territorio
    if (client.role === 'GOVERNOR' && !dto.departmentId) {
      throw new BadRequestException('Un Gobernador requiere un departamento');
    }
    if (client.role === 'MAYOR' && !dto.municipalityId) {
      throw new BadRequestException('Un Alcalde requiere un municipio');
    }

    let departmentId: Types.ObjectId | null = null;
    let municipalityId: Types.ObjectId | null = null;
    let departmentName: string | undefined;
    let municipalityName: string | undefined;

    if (dto.departmentId) {
      const dept = await this.departmentModel.findById(dto.departmentId);
      if (!dept) throw new NotFoundException('Departamento no encontrado');
      departmentId = new Types.ObjectId(dto.departmentId);
      departmentName = dept.name;
    }

    if (dto.municipalityId) {
      const muni = await this.municipalityModel.findById(dto.municipalityId);
      if (!muni) throw new NotFoundException('Municipio no encontrado');
      municipalityId = new Types.ObjectId(dto.municipalityId);
      municipalityName = muni.name;
    }

    // Verificar que no exista un contrato activo para este cliente/elección
    const existing = await this.contractModel.findOne({
      clientId: new Types.ObjectId(dto.clientId),
      electionId: new Types.ObjectId(dto.electionId),
      active: true,
    });

    if (existing) {
      throw new ConflictException(
        'Ya existe un contrato activo para este cliente en esta elección',
      );
    }

    const contract = await this.contractModel.create({
      active: true,
      clientId: new Types.ObjectId(dto.clientId),
      clientRole: client.role,
      departmentId,
      municipalityId,
      departmentName,
      municipalityName,
      electionId: new Types.ObjectId(dto.electionId),
      startDate: dto.startDate,
      endDate: dto.endDate,
    });

    return contract;
  }

  /**
   * Obtener contratos activos
   */
  async findActiveContracts(filters?: {
    clientId?: string;
    electionId?: string;
    departmentId?: string;
    municipalityId?: string;
  }): Promise<ContractDocument[]> {
    const query: any = { active: true };

    if (filters?.clientId) {
      query.clientId = new Types.ObjectId(filters.clientId);
    }
    if (filters?.electionId) {
      query.electionId = new Types.ObjectId(filters.electionId);
    }
    if (filters?.departmentId) {
      query.departmentId = new Types.ObjectId(filters.departmentId);
    }
    if (filters?.municipalityId) {
      query.municipalityId = new Types.ObjectId(filters.municipalityId);
    }

    return this.contractModel
      .find(query)
      .populate('clientId', 'name email role')
      .populate('departmentId', 'name')
      .populate('municipalityId', 'name')
      .sort({ createdAt: -1 })
      .exec();
  }

  async findPublicActiveContracts(filters?: {
    electionId?: string;
    electionType?: string;
  }): Promise<
    Array<{
      contractId: string;
      clientRole: 'MAYOR' | 'GOVERNOR';
      election: {
        electionId: string;
        electionName: string;
        electionType?: string;
        round?: number;
      };
      territory: {
        type: 'municipality' | 'department';
        departmentId?: string;
        departmentName?: string;
        municipalityId?: string;
        municipalityName?: string;
      };
      active: boolean;
    }>
  > {
    const activeElections = await this.electionConfigService.getActiveConfigs();
    if (!activeElections.length) return [];

    let filteredElections = activeElections;
    if (filters?.electionType) {
      filteredElections = activeElections.filter(
        (e) => e.type === filters.electionType,
      );
    }
    if (filters?.electionId) {
      filteredElections = filteredElections.filter(
        (e) => e.id === filters.electionId,
      );
    }
    if (!filteredElections.length) return [];

    const electionIdSet = new Set(filteredElections.map((e) => e.id));

    const contracts = await this.contractModel
      .find({
        active: true,
        electionId: {
          $in: filteredElections.map((e) => new Types.ObjectId(e.id)),
        },
      })
      .populate('electionId', 'name type round')
      .populate('departmentId', 'name')
      .populate('municipalityId', 'name')
      .sort({
        electionId: 1,
        clientRole: 1,
        departmentName: 1,
        municipalityName: 1,
        createdAt: -1,
      })
      .exec();

    return contracts
      .map((c) => {
        const election = c.electionId as any;
        if (!election?._id) return null;
        const eid = election._id.toString();
        if (!electionIdSet.has(eid)) return null;

        const dept = c.departmentId as any;
        const muni = c.municipalityId as any;
        const isMunicipal = Boolean(muni || c.municipalityName);

        return {
          contractId: c._id.toString(),
          clientRole: c.clientRole,
          election: {
            electionId: eid,
            electionName: election.name,
            electionType: election.type,
            round: election.round,
          },
          territory: {
            type: isMunicipal ? 'municipality' : 'department',
            departmentId: dept?._id?.toString() || c.departmentId?.toString(),
            departmentName: dept?.name || c.departmentName,
            municipalityId:
              muni?._id?.toString() || c.municipalityId?.toString(),
            municipalityName: muni?.name || c.municipalityName,
          },
          active: c.active,
        };
      })
      .filter(Boolean) as Array<{
      contractId: string;
      clientRole: 'MAYOR' | 'GOVERNOR';
      election: {
        electionId: string;
        electionName: string;
        electionType?: string;
        round?: number;
      };
      territory: {
        type: 'municipality' | 'department';
        departmentId?: string;
        departmentName?: string;
        municipalityId?: string;
        municipalityName?: string;
      };
      active: boolean;
    }>;
  }

  /**
   * Verificar si existe cobertura activa para un territorio
   */
  async hasCoverage(params: {
    electionId: string;
    departmentId?: string;
    municipalityId?: string;
  }): Promise<boolean> {
    const query: any = {
      active: true,
      electionId: new Types.ObjectId(params.electionId),
    };

    if (params.municipalityId) {
      query.municipalityId = new Types.ObjectId(params.municipalityId);
    } else if (params.departmentId) {
      query.departmentId = new Types.ObjectId(params.departmentId);
    }

    const count = await this.contractModel.countDocuments(query);
    return count > 0;
  }

  /**
   * Obtener el contrato activo para un cliente específico
   */
  async getClientContract(
    clientId: string,
    electionId: string,
  ): Promise<ContractDocument | null> {
    return this.contractModel
      .findOne({
        clientId: new Types.ObjectId(clientId),
        electionId: new Types.ObjectId(electionId),
        active: true,
      })
      .populate('departmentId', 'name')
      .populate('municipalityId', 'name')
      .exec();
  }

  /**
   * Desactivar un contrato
   */
  async deactivate(contractId: string): Promise<void> {
    const result = await this.contractModel.updateOne(
      { _id: new Types.ObjectId(contractId) },
      { $set: { active: false, endDate: new Date() } },
    );

    if (result.matchedCount === 0) {
      throw new NotFoundException('Contrato no encontrado');
    }
  }

  async getMyContract(params: { userId: string; electionId: string }): Promise<{
    hasContract: boolean;
    contract: ContractDocument | null;
  }> {
    const contract = await this.contractModel
      .findOne({
        clientId: new Types.ObjectId(params.userId),
        electionId: new Types.ObjectId(params.electionId),
        active: true,
      })
      .populate('departmentId', 'name')
      .populate('municipalityId', 'name')
      .exec();

    if (!contract) {
      return { hasContract: false, contract: null };
    }

    return { hasContract: true, contract };
  }
  /**
   * Obtener todas las elecciones donde el usuario tiene contratos (activos o inactivos)
   */
  async getMyElections(userId: string): Promise<
    Array<{
      electionId: string;
      electionName: string;
      electionType?: string;
      round?: number;
      isActive: boolean;
      contracts: Array<{
        contractId: string;
        active: boolean;
        clientRole: string;
        territory: {
          departmentId?: string;
          departmentName?: string;
          municipalityId?: string;
          municipalityName?: string;
        };
        startDate: Date;
        endDate?: Date;
      }>;
    }>
  > {
    // Buscar TODOS los contratos del usuario (activos e inactivos)
    const contracts = await this.contractModel
      .find({
        clientId: new Types.ObjectId(userId),
      })
      .populate('electionId')
      .populate('departmentId', 'name')
      .populate('municipalityId', 'name')
      .sort({ createdAt: -1 })
      .exec();

    if (!contracts || contracts.length === 0) {
      return [];
    }

    // Agrupar contratos por elección
    const electionMap = new Map<
      string,
      {
        electionId: string;
        electionName: string;
        electionType?: string;
        round?: number;
        isActive: boolean;
        contracts: Array<any>;
      }
    >();

    for (const contract of contracts) {
      const election = contract.electionId as any;
      const electionId = election._id.toString();

      if (!electionMap.has(electionId)) {
        electionMap.set(electionId, {
          electionId,
          electionName: election.name,
          electionType: election.type,
          round: election.round,
          isActive: election.isActive,
          contracts: [],
        });
      }

      electionMap.get(electionId)!.contracts.push({
        contractId: contract._id.toString(),
        active: contract.active,
        clientRole: contract.clientRole,
        territory: {
          departmentId:
            (contract.departmentId as any)?._id?.toString() ||
            contract.departmentId?.toString(),
          departmentName:
            (contract.departmentId as any)?.name || contract.departmentName,
          municipalityId:
            (contract.municipalityId as any)?._id?.toString() ||
            contract.municipalityId?.toString(),
          municipalityName:
            (contract.municipalityId as any)?.name || contract.municipalityName,
        },
        startDate: contract.startDate,
        endDate: contract.endDate,
      });
    }

    return Array.from(electionMap.values());
  }

  /**
   * Obtener el historial completo de contratos de un usuario
   */
  async getContractHistory(
    userId: string,
    filters?: {
      active?: boolean;
      electionId?: string;
    },
  ): Promise<
    Array<{
      contractId: string;
      active: boolean;
      clientRole: string;
      territory: {
        departmentId?: string;
        departmentName?: string;
        municipalityId?: string;
        municipalityName?: string;
      };
      election: {
        electionId: string;
        electionName: string;
        electionType?: string;
        round?: number;
        isActive: boolean;
      };
      startDate: Date;
      endDate?: Date;
      createdAt: Date;
    }>
  > {
    const query: any = {
      clientId: new Types.ObjectId(userId),
    };

    if (filters?.active !== undefined) {
      query.active = filters.active;
    }

    if (filters?.electionId) {
      query.electionId = new Types.ObjectId(filters.electionId);
    }

    const contracts = await this.contractModel
      .find(query)
      .populate('electionId')
      .populate('departmentId', 'name')
      .populate('municipalityId', 'name')
      .sort({ createdAt: -1 })
      .exec();

    return contracts.map((contract) => {
      const election = contract.electionId as any;
      return {
        contractId: contract._id.toString(),
        active: contract.active,
        clientRole: contract.clientRole,
        territory: {
          departmentId: contract.departmentId?.toString(),
          departmentName:
            (contract.departmentId as any)?.name || contract.departmentName,
          municipalityId: contract.municipalityId?.toString(),
          municipalityName:
            (contract.municipalityId as any)?.name || contract.municipalityName,
        },
        election: {
          electionId: election._id.toString(),
          electionName: election.name,
          electionType: election.type,
          round: election.round,
          isActive: election.isActive,
        },
        startDate: contract.startDate,
        endDate: contract.endDate,
        createdAt: contract.createdAt,
      };
    });
  }

  async checkAttestationAvailability(
    latitude: number,
    longitude: number,
    maxDistance: number = 10000,
  ): Promise<{
    nearestLocation: any;
    availableElections: Array<{
      electionId: string;
      electionName: string;
      electionType: string;
      round?: number;
      canAttest: boolean;
      reason: string;
      contract?: {
        id: string;
        clientRole: string;
        territory: string;
      };
    }>;
  }> {
    const nearestLocation =
      await this.electoralLocationService.findNearestLocation(
        latitude,
        longitude,
        maxDistance,
      );

    if (!nearestLocation) {
      throw new NotFoundException(
        `No se encontró ningún recinto electoral en un radio de ${maxDistance} metros`,
      );
    }

    const locationWithHierarchy =
      await this.electoralLocationService.findOneWithHierarchy(
        nearestLocation._id.toString(),
      );

    const norm = (s: any) =>
      String(s ?? '')
        .trim()
        .replace(/\s+/g, ' ');

    const departmentName = norm(locationWithHierarchy.department?.name);
    const municipalityName = norm(locationWithHierarchy.municipality?.name);

    const activeElections = await this.electionConfigService.getActiveConfigs();

    if (!activeElections || activeElections.length === 0) {
      return {
        nearestLocation: {
          _id: nearestLocation._id.toString(),
          name: nearestLocation.name,
          address: nearestLocation.address,
          distance: nearestLocation.distance,
          department: departmentName,
          municipality: municipalityName,
        },
        availableElections: [],
      };
    }

    const availableElections = await Promise.all(
      activeElections.map(async (election) => {
        const or: any[] = [];
        if (departmentName) or.push({ departmentName });
        if (municipalityName) or.push({ municipalityName });

        const contracts = await this.contractModel
          .find({
            electionId: new Types.ObjectId(election.id),
            active: true,
            ...(or.length ? { $or: or } : {}),
          })
          .select('_id clientRole departmentName municipalityName')
          .lean()
          .exec();

        let canAttest = false;
        let reason = '';
        let contractInfo:
          | {
              id: string;
              clientRole: string;
              territory: string;
            }
          | undefined = undefined;

        if (contracts.length === 0) {
          reason = `No hay contratos activos para ${election.type} en ${municipalityName}, ${departmentName}`;
        } else {
          // Priorizar contrato más específico (municipio sobre departamento)
          const municipalContract = contracts.find(
            (c: any) => norm(c.municipalityName) === municipalityName,
          );
          const departmentContract = contracts.find(
            (c: any) => norm(c.departmentName) === departmentName,
          );

          const activeContract = municipalContract || departmentContract;

          if (activeContract) {
            canAttest = true;
            reason = `Contrato activo de ${activeContract.clientRole === 'MAYOR' ? 'Alcalde' : 'Gobernador'}`;
            contractInfo = {
              id: activeContract._id.toString(),
              clientRole: activeContract.clientRole,
              territory:
                activeContract.municipalityName ||
                activeContract.departmentName ||
                '',
            };
          }
        }

        const result: {
          electionId: string;
          electionName: string;
          electionType: string;
          round?: number;
          canAttest: boolean;
          reason: string;
          contract?: {
            id: string;
            clientRole: string;
            territory: string;
          };
        } = {
          electionId: election.id,
          electionName: election.name,
          electionType: election.type || 'general',
          round: election.round,
          canAttest,
          reason,
        };


        if (contractInfo) {
          result.contract = contractInfo;
        }

        return result;
      }),
    );

    return {
      nearestLocation: {
        _id: nearestLocation._id.toString(),
        name: nearestLocation.name,
        address: nearestLocation.address,
        distance: nearestLocation.distance,
        department: departmentName,
        municipality: municipalityName,
        coordinates: {
          latitude: nearestLocation.coordinates.latitude,
          longitude: nearestLocation.coordinates.longitude,
        },
      },
      availableElections,
    };
  }
}

