  haversineMeters(
    lat1: number,
    lon1: number,
    lat2: number,
    lon2: number,
  ): number {
    const toRad = (d: number) => (d * Math.PI) / 180;
    const R = 6371000; // radio tierra en metros
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a =
      Math.sin(dLat / 2) ** 2 +
      Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  async findNearby(
    lat: number,
    lng: number,
    maxDistance = 1000,
    electionId?: string,
  ) {
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
      throw new BadRequestException('lat/lng inválidos');
    }

    // 1) Búsqueda geoespacial ([lng, lat]) → limit 10 para replicar el pipeline anterior
    const base = await this.locationModel
      .find({
        active: true,
        geo: {
          $near: {
            $geometry: { type: 'Point', coordinates: [lng, lat] },
            $maxDistance: maxDistance,
          },
        },
      })
      .select(
        // incluye TODO lo que el $project original dejaba pasar
        '_id fid code name address district zone coordinates circunscripcion active electoralSeatId geo',
      )
      .limit(100)
      .lean()
      .exec();

    // Si no hay resultados, responde en el mismo formato
    if (base.length === 0) {
      return {
        data: [],
        query: { latitude: lat, longitude: lng, maxDistance, unit: 'meters' },
        count: 0,
      };
    }

    const ids = base.map((d) => d._id as Types.ObjectId);

    // 2) Enriquecimiento jerárquico vía populate (seat → municipality → province → department)
    const populated = await this.locationModel.populate(base, {
      path: 'electoralSeatId',
      select: 'name municipalityId',
      populate: {
        path: 'municipalityId',
        select: 'name provinceId',
        populate: {
          path: 'provinceId',
          select: 'name departmentId',
          populate: {
            path: 'departmentId',
            select: 'name',
          },
        },
      },
    });

    // 3) Traer tables/ballots por lote (mismo orden/proyección que en tu pipeline)
    const tablesRaw = await this.electoralTableModel
      .find({ electoralLocationId: { $in: ids } })
      .select('_id tableNumber tableCode electoralLocationId')
      .sort({ tableNumber: 1 })
      .lean()
      .exec();

    const ballotFilter: any = { electoralLocationId: { $in: ids } };
    if (electionId) ballotFilter.electionId = new Types.ObjectId(electionId);

    const ballotsRaw = await this.ballotModel
      .find(ballotFilter)
      .select('_id tableNumber tableCode electoralLocationId')
      .sort({ tableNumber: 1 })
      .lean()
      .exec();

    // 4) Agrupar tablas/boletas por location
    const tablesByLoc = new Map<string, any[]>();
    for (const t of tablesRaw) {
      const k = String(t.electoralLocationId);
      const arr = tablesByLoc.get(k) ?? [];
      // proyecta como en el $project del pipeline
      arr.push({
        _id: t._id,
        tableNumber: t.tableNumber,
        tableCode: t.tableCode,
      });
      tablesByLoc.set(k, arr);
    }

    const ballotsByLoc = new Map<string, any[]>();
    for (const b of ballotsRaw) {
      const k = String(b.electoralLocationId);
      const arr = ballotsByLoc.get(k) ?? [];
      arr.push({
        _id: b._id,
        tableNumber: b.tableNumber,
        tableCode: b.tableCode,
      });
      ballotsByLoc.set(k, arr);
    }

    const data = populated.map((loc: any) => {
      const [locLng, locLat] = loc.geo?.coordinates ?? [undefined, undefined];
      const distance =
        Number.isFinite(locLat) && Number.isFinite(locLng)
          ? Math.round(this.haversineMeters(lat, lng, locLat, locLng))
          : undefined;

      const seat = loc.electoralSeatId || {};
      const mun = seat.municipalityId || {};
      const prov = mun.provinceId || {};
      const dept = prov.departmentId || {};

      const tables = tablesByLoc.get(String(loc._id)) ?? [];
      const ballots = ballotsByLoc.get(String(loc._id)) ?? [];

      return {
        _id: loc._id,
        fid: loc.fid,
        code: loc.code,
        name: loc.name,
        address: loc.address,
        district: loc.district,
        zone: loc.zone,
        coordinates: loc.coordinates,
        circunscripcion: loc.circunscripcion,
        active: loc.active,
        distance, // metros
        electoralSeat: {
          _id: seat._id,
          name: seat.name,
          municipality: {
            _id: mun._id,
            name: mun.name,
            province: {
              _id: prov._id,
              name: prov.name,
              department: {
                _id: dept._id,
                name: dept.name,
              },
            },
          },
        },
        tables,
        ballots,
        tableCount: tables.length,
      };
    });

    return {
      data,
      query: { latitude: lat, longitude: lng, maxDistance, unit: 'meters' },
      count: data.length,
    };
  }

  async findByCircunscripcion(
    type: string,
    number?: number,
  ): Promise<ElectoralLocation[]> {
    const filters: any = { 'circunscripcion.type': type, active: true };
    if (number) {
      filters['circunscripcion.number'] = number;
    }

    return this.locationModel
      .find(filters)
      .populate('electoralSeatId', 'name')
      .sort({ 'circunscripcion.number': 1, name: 1 })
      .exec();
  }

  async findByElectoralSeat(
    electoralSeatId: string | Types.ObjectId,
  ): Promise<ElectoralLocation[]> {
    const response = await this.electoralSeatService.findOne(electoralSeatId);

    return this.locationModel
      .find({
        electoralSeatId: response._id,
        active: true,
      })
      .sort({ name: 1 })
      .exec();
  }

  async update(id: string, dto: UpdateElectoralLocationDto) {
    const updateDoc: any = { ...dto };

    if (dto.coordinates) {
      const { longitude, latitude } = dto.coordinates;
      if (!Number.isFinite(longitude) || !Number.isFinite(latitude)) {
        throw new BadRequestException(
          'coordinates.longitude/latitude inválidos',
        );
      }
      updateDoc.geo = { type: 'Point', coordinates: [longitude, latitude] };
    }

    const updated = await this.locationModel
      .findByIdAndUpdate(
        id,
        { $set: updateDoc },
        {
          new: true,
          runValidators: true,
          context: 'query',
          validateModifiedOnly: true,
          setDefaultsOnInsert: false,
        },
      )
      .exec();

    if (!updated) throw new NotFoundException('Recinto no encontrado');
    return updated.toObject();
  }

  async remove(id: string | Types.ObjectId): Promise<void> {
    const result = await this.locationModel.findByIdAndDelete(id).exec();
    if (!result) {
      throw new NotFoundException(
        `Recinto electoral con ID ${id.toString()} no encontrado`,
      );
    }

    this.logger.log(
      `Recinto electoral eliminado: ${result.name}`,
      'ElectoralLocationService',
    );
  }

  async getStatistics() {
    const stats = await this.locationModel.aggregate([
      { $match: { active: true } },
      {
        $group: {
          _id: '$circunscripcion.type',
          count: { $sum: 1 },
          districts: { $addToSet: '$district' },
          zones: { $addToSet: '$zone' },
        },
      },
      {
        $project: {
          type: '$_id',
          count: 1,
          distinctDistricts: { $size: '$districts' },
          distinctZones: { $size: '$zones' },
          _id: 0,
        },
      },
    ]);

    const total = await this.locationModel.countDocuments({ active: true });

    return {
      total,
      byType: stats,
      timestamp: new Date().toISOString(),
    };
  }

  async findOneWithHierarchy(id: string): Promise<any> {
    const result = await this.locationModel
      .aggregate([
        { $match: { _id: new Types.ObjectId(id) } },
        {
          $lookup: {
            from: 'electoral_seats',
            localField: 'electoralSeatId',
            foreignField: '_id',
            as: 'electoralSeat',
          },
        },
        { $unwind: '$electoralSeat' },
        {
          $lookup: {
            from: 'municipalities',
            localField: 'electoralSeat.municipalityId',
            foreignField: '_id',
            as: 'municipality',
          },
        },
        { $unwind: '$municipality' },
        {
          $lookup: {
            from: 'provinces',
            localField: 'municipality.provinceId',
            foreignField: '_id',
            as: 'province',
          },
        },
        { $unwind: '$province' },
        {
          $lookup: {
            from: 'departments',
            localField: 'province.departmentId',
            foreignField: '_id',
            as: 'department',
          },
        },
        { $unwind: '$department' },
      ])
      .exec();

    if (!result || result.length === 0) {
      throw new NotFoundException('Recinto electoral no encontrado');
    }

    return result[0];
  }

  async findNearestLocation(
    latitude: number,
    longitude: number,
    maxDistance: number = 5000,
  ): Promise<any> {
    const result = await this.locationModel
      .aggregate([
        {
          $geoNear: {
            near: {
              type: 'Point',
              coordinates: [latitude, longitude], // MongoDB usa [lng, lat]
            },
            distanceField: 'distance',
            maxDistance: maxDistance,
            spherical: true,
            query: { active: true },
          },
        },
        { $limit: 1 },
      ])
      .exec();

    if (!result || result.length === 0) {
      return null;
    }

    return result[0];
  }

  private normalizeName(s?: string): string {
    return (s ?? '').trim().replace(/\s+/g, ' ');
  }
  private normalizeCode(s?: string): string {
    return (s ?? '').trim();
  }
  private parseCoord(s?: string | number): number | undefined {
    if (s === null || s === undefined) return undefined;
    const n = typeof s === 'number' ? s : parseFloat(String(s).trim());
    return Number.isFinite(n) ? n : undefined;
  }
  private buildUpdateFromPayload(payload: RecintoUpdate) {
    const update: Record<string, any> = {
      name: this.normalizeName(payload.name),
      district: payload.district
        ? this.normalizeName(payload.district)
        : undefined,
      zone: payload.zone ? this.normalizeName(payload.zone) : undefined,
      address: payload.address
        ? this.normalizeName(payload.address)
        : undefined,
      circNumber: payload.circNumber
        ? this.normalizeCode(payload.circNumber)
        : undefined,
      circType: payload.circType
        ? this.normalizeName(payload.circType)
        : undefined,
      circName: payload.circName
        ? this.normalizeName(payload.circName)
        : undefined,
    };

    const lat = this.parseCoord(payload.latitude as any);
    const lng = this.parseCoord(payload.longitude as any);
    if (lat !== undefined) update.latitude = lat;
    if (lng !== undefined) update.longitude = lng;

    Object.keys(update).forEach(
      (k) => update[k] === undefined && delete update[k],
    );
    return update;
  }

  async ensureBySeatAndCode(
    seatId: Types.ObjectId,
    payload: RecintoUpsert,
  ): Promise<any> {
    const code = this.normalizeCode(payload.code);
    const name = this.normalizeName(payload.name);
    if (!code || !name) {
      throw new Error('code y name son requeridos para ensureBySeatAndCode');
    }

    const $set = this.buildUpdateFromPayload({ ...payload, code, name });
    const filter = { electoralSeatId: seatId, code };

    const doc = await this.locationModel
      .findOneAndUpdate(
        filter,
        {
          $set,
          $setOnInsert: { electoralSeatId: seatId, code, name, active: true },
        },
        { upsert: true, returnDocument: 'after' },
      )
      .lean();

    return doc;
  }

  async resolveByIdOrCode(args: {
    locationId?: string;
    locationCode?: string;
  }): Promise<ElectoralLocationDocument> {
    const { locationId, locationCode } = args || {};
    if (locationId) return this.findOne(locationId);
    if (locationCode) return this.findByCode(locationCode);
    throw new BadRequestException('locationId o locationCode requerido');
  }

  async bulkUpsertBySeat(
    seatId: Types.ObjectId,
    recintos: RecintoUpsert[],
  ): Promise<Map<string, any>> {
    if (!recintos?.length) return new Map();

    // 1) normalizar + deduplicar por code
    const byCode = new Map<string, RecintoUpsert>();
    for (const r of recintos) {
      const code = this.normalizeCode(r.code);
      const name = this.normalizeName(r.name);
      if (!code || !name) {
        this.logger.warn(
          `Recinto omitido por datos insuficientes (code/name vacío). Payload: ${JSON.stringify(r)}`,
        );
        continue;
      }
      byCode.set(code, { ...r, code, name });
    }

    // 2) construir bulk ops
    const ops = Array.from(byCode.values()).map((r) => {
      const filter = { electoralSeatId: seatId, code: r.code };
      const $set = this.buildUpdateFromPayload(r);
      return {
        updateOne: {
          filter,
          update: {
            $set,
            $setOnInsert: {
              electoralSeatId: seatId,
              code: r.code,
              name: r.name,
              active: true,
            },
          },
          upsert: true,
        },
      };
    });

    if (ops.length) {
      await this.locationModel.bulkWrite(ops, { ordered: false });
    }

    const codes = [...byCode.keys()];
    const docs = await this.locationModel
      .find({ electoralSeatId: seatId, code: { $in: codes } })
      .lean();
    const map = new Map<string, any>();
    for (const d of docs) map.set(d.code, d);
    return map;
  }

  async ensureBySeatAndName(
    seatId: Types.ObjectId,
    payload: Omit<RecintoUpsert, 'code'> & { code?: string },
  ): Promise<any> {
    const name = this.normalizeName(payload.name);
    if (!name) throw new Error('name es requerido para ensureBySeatAndName');

    const $set = this.buildUpdateFromPayload({ ...payload, name });
    const filter = { electoralSeatId: seatId, name };
    const setOnInsert: Record<string, any> = {
      electoralSeatId: seatId,
      name,
      active: true,
    };
    if (payload.code) setOnInsert.code = this.normalizeCode(payload.code);

    const doc = await this.locationModel
      .findOneAndUpdate(
        filter,
        { $set, $setOnInsert: setOnInsert },
        { upsert: true, returnDocument: 'after' },
      )
      .lean();

    return doc;
  }

  /**
   * Utilidad opcional para obtener un mapa por codes existentes (optimiza consultas posteriores).
   */
  async mapByCodes(
    seatId: Types.ObjectId,
    codes: string[],
  ): Promise<Map<string, any>> {
    const norm = codes.map((c) => this.normalizeCode(c)).filter(Boolean);
    if (!norm.length) return new Map();
    const docs = await this.locationModel
      .find({ electoralSeatId: seatId, code: { $in: norm } })
      .select('_id code')
      .lean();
    const map = new Map<string, any>();
    for (const d of docs) map.set(d.code, d);
    return map;
  }
}

