import {
  Injectable,
  NotFoundException,
  ConflictException,
  BadRequestException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import {
  ElectoralTable,
  ElectoralTableDocument,
} from '../schemas/electoral-table.schema';
import {
  CreateElectoralTableDto,
  UpdateElectoralTableDto,
  ElectoralTableQueryDto,
} from '../dto/electoral-table.dto';
import { ElectoralLocationService } from './electoral-location.service';
import { LoggerService } from '../../../core/services/logger.service';

export type MesaUpsert = {
  code?: string; // codigo_mesa (si existe, se usa como clave primaria)
  number: number; // num_mesa
  habilitados: number; // habilitados
  inhabilitados: number; // inhabilitados
};

@Injectable()
export class ElectoralTableService {
  constructor(
    @InjectModel(ElectoralTable.name)
    private electoralTableModel: Model<ElectoralTableDocument>,
    private electoralLocationService: ElectoralLocationService,
    private logger: LoggerService,
  ) {}

  async create(createDto: CreateElectoralTableDto): Promise<ElectoralTable> {
    // Verificar que el recinto electoral existe
    await this.electoralLocationService.findOne(createDto.electoralLocationId);

    try {
      const table = new this.electoralTableModel({
        ...createDto,
        electoralLocationId: new Types.ObjectId(createDto.electoralLocationId),
      });

      const saved = await table.save();

      this.logger.log(
        `Mesa electoral creada: ${saved.tableNumber} en recinto ${createDto.electoralLocationId.toString()}`,
        'ElectoralTableService',
      );
      return saved;
    } catch (error: any) {
      if (error.code === 11000) {
        if (error.message.includes('tableCode')) {
          throw new ConflictException(
            `El código de mesa '${createDto.tableCode}' ya existe`,
          );
        }
        if (error.message.includes('electoralLocationId_1_tableNumber_1')) {
          throw new ConflictException(
            `Ya existe una mesa con número '${createDto.tableNumber}' en este recinto`,
          );
        }
      }
      throw error;
    }
  }

  async findAll(query: ElectoralTableQueryDto) {
    const {
      page = 1,
      limit = 100,
      sort = 'tableNumber',
      order = 'asc',
      search,
      active,
      electoralLocationId,
    } = query;
    const skip = (page - 1) * limit;

    const filters: any = {};
    if (search) {
      filters.$or = [
        { tableNumber: { $regex: search, $options: 'i' } },
        { tableCode: { $regex: search, $options: 'i' } },
      ];
    }
    if (active !== undefined) {
      filters.active = active === 'true';
    }
    if (electoralLocationId) {
      filters.electoralLocationId = new Types.ObjectId(electoralLocationId);
    }

    const [tables, total] = await Promise.all([
      this.electoralTableModel
        .find(filters)
        .populate({
          path: 'electoralLocationId',
          select: 'name code address',
          populate: {
            path: 'electoralSeatId',
            select: 'name',
            populate: {
              path: 'municipalityId',
              select: 'name',
              populate: {
                path: 'provinceId',
                select: 'name',
                populate: {
                  path: 'departmentId',
                  select: 'name',
                },
              },
            },
          },
        })
        .sort({ [sort]: order === 'asc' ? 1 : -1 })
        .skip(skip)
        .limit(limit)
        .exec(),
      this.electoralTableModel.countDocuments(filters),
    ]);

    return {
      data: tables,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
    };
  }
  async resolveByIdOrCode(args: { tableId?: string; tableCode?: string }) {
    const { tableId, tableCode } = args || {};
    if (tableId) return this.findOne(tableId);
    if (tableCode) return this.findByTableCode(tableCode);
    throw new BadRequestException('tableId o tableCode requerido');
  }

  async findWithRecords(electionId?: string) {
    const eid = electionId ? new Types.ObjectId(electionId) : null;

    const pipeline: any[] = [
      {
        $lookup: {
          from: 'ballots',
          localField: 'tableCode',
          foreignField: 'tableCode',
          as: 'ballots',
        },
      },
    ];

    if (eid) {
      pipeline.push({
        $addFields: {
          ballots: {
            $filter: {
              input: '$ballots',
              as: 'b',
              cond: { $eq: ['$$b.electionId', eid] },
            },
          },
        },
      });
    }

    pipeline.push(
      { $match: { $expr: { $gt: [{ $size: '$ballots' }, 0] } } },
      {
        $project: {
          tableNumber: 1,
          tableCode: 1,
          electoralLocationId: 1,
          ballots: { $size: '$ballots' },
        },
      },
    );

    const tables = await this.electoralTableModel.aggregate(pipeline);
    return { data: tables, count: tables.length };
  }
  async findOne(id: string | Types.ObjectId): Promise<ElectoralTable> {
    const table = await this.electoralTableModel
      .findById(id)
      .populate({
        path: 'electoralLocationId',
        select: 'name code address',
        populate: {
          path: 'electoralSeatId',
          select: 'name',
          populate: {
            path: 'municipalityId',
            select: 'name',
            populate: {
              path: 'provinceId',
              select: 'name',
              populate: {
                path: 'departmentId',
                select: 'name',
              },
            },
          },
        },
      })
      .exec();

    if (!table) {
      throw new NotFoundException(
        `Mesa electoral con ID ${id.toString()} no encontrada`,
      );
    }
    return table;
  }

  async findByElectoralLocation(
    electoralLocationId: string | Types.ObjectId,
  ): Promise<ElectoralTable[]> {
    // Verificar que el recinto existe
    await this.electoralLocationService.findOne(electoralLocationId);

    // Convertir a ObjectId para asegurar que funcione tanto con strings como con ObjectIds almacenados en la BD
    const objectId = new Types.ObjectId(electoralLocationId);

    const tables = await this.electoralTableModel
      .find({
        electoralLocationId: objectId,
        active: true,
      })
      .sort({ tableNumber: 1 })
      .exec();

    return tables;
  }

  private transformElectoralTable(table: any): any {
    const tableObj = table.toObject ? table.toObject() : table;
    const location = tableObj.electoralLocationId;
    const seat = location?.electoralSeatId;
    const municipality = seat?.municipalityId;
    const province = municipality?.provinceId;
    const department = province?.departmentId;

    return {
      _id: tableObj._id,
      tableNumber: tableObj.tableNumber,
      tableCode: tableObj.tableCode,
      legacyTableCode: tableObj.legacyTableCode,
      active: tableObj.active,
      createdAt: tableObj.createdAt,
      updatedAt: tableObj.updatedAt,
      __v: tableObj.__v,
      electoralLocationId: location?._id,
      electoralLocation: location
        ? {
            _id: location._id,
            name: location.name,
            code: location.code,
            address: location.address,
          }
        : null,
      electoralSeat: seat
        ? {
            _id: seat._id,
            name: seat.name,
          }
        : null,
      municipality: municipality
        ? {
            _id: municipality._id,
            name: municipality.name,
          }
        : null,
      province: province
        ? {
            _id: province._id,
            name: province.name,
          }
        : null,
      department: department
        ? {
            _id: department._id,
            name: department.name,
          }
        : null,
    };
  }

  async findByTableCode(tableCode: string): Promise<ElectoralTable> {
    // Buscar por tableCode (ingresado por usuario desde el acta física)
    const table = await this.electoralTableModel
      .findOne({ tableCode })
      .populate({
        path: 'electoralLocationId',
        select: 'name code address',
        populate: {
          path: 'electoralSeatId',
          select: 'name',
          populate: {
            path: 'municipalityId',
            select: 'name',
            populate: {
              path: 'provinceId',
              select: 'name',
              populate: {
                path: 'departmentId',
                select: 'name',
              },
            },
          },
        },
      })
      .exec();

    if (!table) {
      throw new NotFoundException(
        `Mesa electoral con código '${tableCode}' no encontrada`,
      );
    }
    return this.transformElectoralTable(table);
  }

  async update(
    id: string | Types.ObjectId,
    updateDto: UpdateElectoralTableDto,
  ): Promise<ElectoralTable> {
    if (updateDto.electoralLocationId) {
      await this.electoralLocationService.findOne(
        updateDto.electoralLocationId,
      );
    }

    try {
      const table = await this.electoralTableModel
        .findByIdAndUpdate(id, updateDto, { new: true })
        .populate('electoralLocationId', 'name code')
        .exec();

      if (!table) {
        throw new NotFoundException(
          `Mesa electoral con ID ${id.toString()} no encontrada`,
        );
      }

      this.logger.log(
        `Mesa electoral actualizada: ${table.tableNumber}`,
        'ElectoralTableService',
      );
      return table;
    } catch (error: any) {
      if (error.code === 11000) {
        if (error.message.includes('tableCode')) {
          throw new ConflictException(
            `El código de mesa '${updateDto.tableCode}' ya existe`,
          );
        }
        if (error.message.includes('electoralLocationId_1_tableNumber_1')) {
          throw new ConflictException(
            `Ya existe una mesa con número '${updateDto.tableNumber}' en este recinto`,
          );
        }
      }
      throw error;
    }
  }

  async remove(id: string | Types.ObjectId): Promise<void> {
    const result = await this.electoralTableModel.findByIdAndDelete(id).exec();
    if (!result) {
      throw new NotFoundException(
        `Mesa electoral con ID ${id.toString()} no encontrada`,
      );
    }

    this.logger.log(
      `Mesa electoral eliminada: ${result.tableNumber}`,
      'ElectoralTableService',
    );
  }

  async activate(id: string): Promise<ElectoralTable> {
    const table = await this.electoralTableModel
      .findByIdAndUpdate(id, { active: true }, { new: true })
      .exec();

    if (!table) {
      throw new NotFoundException(`Mesa electoral con ID ${id} no encontrada`);
    }

    this.logger.log(
      `Mesa electoral activada: ${table.tableNumber}`,
      'ElectoralTableService',
    );
    return table;
  }

  async deactivate(id: string): Promise<ElectoralTable> {
    const table = await this.electoralTableModel
      .findByIdAndUpdate(id, { active: false }, { new: true })
      .exec();

    if (!table) {
      throw new NotFoundException(`Mesa electoral con ID ${id} no encontrada`);
    }

    this.logger.log(
      `Mesa electoral desactivada: ${table.tableNumber}`,
      'ElectoralTableService',
    );
    return table;
  }

  async getStatistics() {
    const stats = await this.electoralTableModel.aggregate([
      { $match: { active: true } },
      {
        $group: {
          _id: '$electoralLocationId',
          tableCount: { $sum: 1 },
          tableNumbers: { $push: '$tableNumber' },
        },
      },
      {
        $lookup: {
          from: 'electoral_locations',
          localField: '_id',
          foreignField: '_id',
          as: 'location',
        },
      },
      {
        $unwind: '$location',
      },
      {
        $group: {
          _id: null,
          totalTables: { $sum: '$tableCount' },
          totalLocations: { $sum: 1 },
          avgTablesPerLocation: { $avg: '$tableCount' },
          maxTablesPerLocation: { $max: '$tableCount' },
          minTablesPerLocation: { $min: '$tableCount' },
        },
      },
    ]);

    const total = await this.electoralTableModel.countDocuments({
      active: true,
    });
    const totalLocationsWithTables = await this.electoralTableModel
      .distinct('electoralLocationId')
      .then((arr) => arr.length);

    return {
      total,
      totalLocationsWithTables,
      summary: stats[0] || {
        totalTables: 0,
        totalLocations: 0,
        avgTablesPerLocation: 0,
        maxTablesPerLocation: 0,
        minTablesPerLocation: 0,
      },
      timestamp: new Date().toISOString(),
    };
  }

  async countTotal(): Promise<number> {
    return this.electoralTableModel.countDocuments({ active: true }).exec();
  }

  async countByLocation(electoralLocationId: string): Promise<number> {
    return this.electoralTableModel
      .countDocuments({
        electoralLocationId: new Types.ObjectId(electoralLocationId),
        active: true,
      })
      .exec();
  }

  private normalizeCode(s?: string): string {
    return (s ?? '').trim();
  }

  validateMesaPayload(m: MesaUpsert): { ok: boolean; reason?: string } {
    if (m.number === null || m.number === undefined || Number(m.number) < 1) {
      return { ok: false, reason: `num_mesa inválido: ${m.number}` };
    }
    if (m.habilitados !== undefined && Number(m.habilitados) < 0) {
      return { ok: false, reason: `habilitados inválido: ${m.habilitados}` };
    }
    if (m.inhabilitados !== undefined && Number(m.inhabilitados) < 0) {
      return {
        ok: false,
        reason: `inhabilitados inválido: ${m.inhabilitados}`,
      };
    }
    return { ok: true };
  }

  private buildUpdateFromPayload(payload: MesaUpsert) {
    const update: Record<string, any> = {
      tableNumber: String(payload.number),
    };
    // Elimina undefined por si acaso
    Object.keys(update).forEach(
      (k) => update[k] === undefined && delete update[k],
    );
    return update;
  }

  // ---------- API pública sugerida ----------

  /**
   * Upsert idempotente.
   * Regla:
   *  - Si hay code -> upsert por { code }
   *  - Si NO hay code -> upsert por { precinctId, number }
   */
  async ensureByCodeOrPrecinctAndNumber(
    precinctId: Types.ObjectId,
    payload: MesaUpsert,
  ): Promise<any> {
    const v = this.validateMesaPayload(payload);
    if (!v.ok) {
      this.logger.warn(`Mesa omitida: ${v.reason}`);
      return null;
    }

    const code = payload.code ? this.normalizeCode(payload.code) : undefined;
    const $set = this.buildUpdateFromPayload(payload);

    if (code) {
      // Clave primaria por code (y seteamos precinctId/number en insert)
      const doc = await this.electoralTableModel
        .findOneAndUpdate(
          { tableCode: code },
          {
            $set,
            $setOnInsert: {
              tableCode: code,
              electoralLocationId: precinctId,
              tableNumber: String(payload.number),
              active: true,
            },
          },
          { upsert: true, returnDocument: 'after' },
        )
        .lean();
      return doc;
    } else {
      // Sin code: clave por (precinctId, number)
      const doc = await this.electoralTableModel
        .findOneAndUpdate(
          {
            electoralLocationId: precinctId,
            tableNumber: String(payload.number),
          },
          {
            $set,
            $setOnInsert: {
              electoralLocationId: precinctId,
              tableNumber: String(payload.number),
              active: true,
            },
          },
          { upsert: true, returnDocument: 'after' },
        )
        .lean();
      return doc;
    }
  }

  /**
   * Upsert masivo por recinto (precinctId).
   * Devuelve un mapa:
   *  - clave = code si existe
   *  - clave = `${precinctId}:${number}` si no hay code
   */
  async bulkUpsertByPrecinct(
    precinctId: Types.ObjectId,
    mesas: MesaUpsert[],
  ): Promise<Map<string, any>> {
    if (!mesas?.length) return new Map();

    // 1) normalizar/deduplicar en el lote:
    //    - con code: deduplicar por code
    //    - sin code: deduplicar por number dentro del mismo precinctId
    const seenByCode = new Map<string, MesaUpsert>();
    const seenByNumber = new Map<number, MesaUpsert>();

    for (const m of mesas) {
      const v = this.validateMesaPayload(m);
      if (!v.ok) {
        this.logger.warn(`Mesa omitida: ${v.reason}`);
        continue;
      }
      const code = m.code ? this.normalizeCode(m.code) : undefined;
      if (code) {
        seenByCode.set(code, { ...m, code });
      } else {
        seenByNumber.set(Number(m.number), { ...m, code: undefined });
      }
    }

    // 2) construir bulk ops
    const ops: any[] = [];

    // con code
    for (const [code, m] of seenByCode.entries()) {
      const $set = this.buildUpdateFromPayload(m);
      ops.push({
        updateOne: {
          filter: { tableCode: code },
          update: {
            $set,
            $setOnInsert: {
              tableCode: code,
              electoralLocationId: precinctId,
              tableNumber: String(m.number),
              active: true,
            },
          },
          upsert: true,
        },
      });
    }

    // sin code
    for (const [num, m] of seenByNumber.entries()) {
      const $set = this.buildUpdateFromPayload(m);
      ops.push({
        updateOne: {
          filter: {
            electoralLocationId: precinctId,
            tableNumber: String(num),
          },
          update: {
            $set,
            $setOnInsert: {
              electoralLocationId: precinctId,
              tableNumber: String(num),
              active: true,
            },
          },
          upsert: true,
        },
      });
    }

    if (ops.length) {
      await this.electoralTableModel.bulkWrite(ops, { ordered: false });
    }

    // 3) recuperar todos y construir mapa de retorno
    const keysWithCode = [...seenByCode.keys()];
    const numbersNoCode = [...seenByNumber.keys()];

    const results: any[] = [];
    if (keysWithCode.length) {
      const docsByCode = await this.electoralTableModel
        .find({ tableCode: { $in: keysWithCode } })
        .lean();
      results.push(...docsByCode);
    }
    if (numbersNoCode.length) {
      const docsByNum = await this.electoralTableModel
        .find({
          electoralLocationId: precinctId,
          tableNumber: { $in: numbersNoCode.map(String) },
        })
        .lean();
      results.push(...docsByNum);
    }

    const map = new Map<string, any>();
    for (const d of results) {
      const key = d.tableCode
        ? String(d.tableCode)
        : `${String(d.electoralLocationId)}:${String(d.tableNumber)}`;
      map.set(key, d);
    }
    return map;
  }
}

