import {
  Body,
  Controller,
  Get,
  Headers,
  Param,
  Post,
  Query,
  Req,
  Res,
  Sse,
} from '@nestjs/common';
import {
  ApiBody,
  ApiHeader,
  ApiOperation,
  ApiParam,
  ApiQuery,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';
import { Response } from 'express';
import { Observable, from } from 'rxjs';
import { mergeMap } from 'rxjs/operators';
import { MessageEvent } from '@nestjs/common';
import { Public } from '@/core/decorators/public.decorator';
import { ScanPresentialSessionDto } from '../dto/presential-session.dto';
import { InstitutionalVotingService } from '../services/institutional-voting.service';

@ApiTags('Institutional Voting Presential QR')
@Controller('api/v1/voting')
export class InstitutionalVotingPresentialController {
  constructor(private readonly institutionalVotingService: InstitutionalVotingService) {}

  @Get('events/:eventId/presential-sessions/current')
  @Public()
  @ApiOperation({
    summary: 'Obtiene el estado actual del kiosco presencial y el QR vigente si existe',
  })
  @ApiParam({ name: 'eventId', description: 'ID del evento de votación.' })
  @ApiQuery({
    name: 'stationId',
    required: false,
    description:
      'Identificador lógico del kiosco/estación. Si no se envía, se usa "kiosco-principal".',
  })
  @ApiHeader({
    name: 'x-kiosk-token',
    required: false,
    description:
      'Token limitado del kiosco. En rutas públicas también se acepta Bearer válido del tenant/admin.',
  })
  @ApiResponse({ status: 200, description: 'Estado actual del kiosco.' })
  current(
    @Param('eventId') eventId: string,
    @Query('stationId') stationId: string | undefined,
    @Headers('x-kiosk-token') kioskToken: string | undefined,
    @Req() req: any,
  ) {
    return this.institutionalVotingService.getCurrentPresentialSessionState(
      eventId,
      stationId,
      kioskToken,
      req.user,
    );
  }

  @Sse('events/:eventId/presential-sessions/stream')
  @Public()
  @ApiOperation({
    summary: 'Stream SSE del kiosco presencial limitado a una elección/estación',
  })
  @ApiParam({ name: 'eventId', description: 'ID del evento de votación.' })
  @ApiQuery({
    name: 'stationId',
    required: false,
    description:
      'Identificador lógico del kiosco/estación. Si no se envía, se usa "kiosco-principal".',
  })
  @ApiHeader({
    name: 'x-kiosk-token',
    required: false,
    description:
      'Token limitado del kiosco. En rutas públicas también se acepta Bearer válido del tenant/admin.',
  })
  stream(
    @Param('eventId') eventId: string,
    @Query('stationId') stationId: string | undefined,
    @Headers('x-kiosk-token') kioskToken: string | undefined,
    @Req() req: any,
  ): Observable<MessageEvent> {
    return from(
      this.institutionalVotingService.createPresentialSessionStream(
        eventId,
        stationId,
        kioskToken,
        req.user,
      ),
    ).pipe(mergeMap((stream) => stream));
  }

  @Post('presential-sessions/scan')
  @Public()
  @ApiOperation({
    summary: 'Scan/claim desde app móvil del QR presencial del kiosco',
  })
  @ApiBody({ type: ScanPresentialSessionDto })
  @ApiResponse({
    status: 201,
    description: 'Sesión presencial reclamada correctamente para continuar el voto.',
  })
  @ApiResponse({
    status: 200,
    description: 'Respuesta idempotente: la misma persona ya había reclamado esta sesión.',
  })
  async scan(
    @Body() dto: ScanPresentialSessionDto,
    @Res() res: Response,
  ) {
    const out = await this.institutionalVotingService.scanPresentialSession(dto);
    return res.status(out.statusCode).json(out.body);
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import {
  InstitutionalTenant,
  InstitutionalTenantDocument,
} from '@/modules/institutional-tenants/schemas/institutional-tenant.schema';
import {
  TenantAdminAssignment,
  TenantAdminAssignmentDocument,
} from '@/modules/institutional-tenants/schemas/tenant-admin-assignment.schema';
import {
  VotingEvent,
  VotingEventDocument,
} from '../../schemas/voting-event.schema';

@Injectable()
export class InstitutionalVotingAccessService {
  private readonly createLeadHours = 12;
  private readonly officialPublicationLeadHours = 6;

  constructor(
    @InjectModel(VotingEvent.name)
    private readonly votingEventModel: Model<VotingEventDocument>,
    @InjectModel(InstitutionalTenant.name)
    private readonly tenantModel: Model<InstitutionalTenantDocument>,
    @InjectModel(TenantAdminAssignment.name)
    private readonly assignmentModel: Model<TenantAdminAssignmentDocument>,
  ) {}

  async getEventOrThrow(eventId: string) {
    if (!Types.ObjectId.isValid(eventId)) {
      throw new BadRequestException('eventId inválido');
    }

    const event = await this.votingEventModel.findById(eventId);
    if (!event) throw new NotFoundException('Evento no encontrado');
    return event;
  }

  async assertTenantWriteAccess(tenantId: Types.ObjectId, requester: any) {
    const isAdmin = requester?.role === 'ADMIN';
    if (isAdmin) return;

    const requesterId = requester?.sub ? String(requester.sub) : '';
    if (!requesterId) {
      throw new ForbiddenException('No autorizado para operar este tenant');
    }

    const assignment = await this.assignmentModel
      .findOne({
        tenantId,
        userId: new Types.ObjectId(requesterId),
        active: true,
        $or: [{ status: 'APPROVED' }, { status: { $exists: false } }],
      })
      .lean();

    if (!assignment) {
      throw new ForbiddenException('No autorizado para operar este tenant');
    }
  }

  assertGlobalAdminAccess(requester: any, action = 'realizar esta acción') {
    if (requester?.role !== 'ADMIN') {
      throw new ForbiddenException(`Solo un administrador global puede ${action}`);
    }
  }

  async resolveReadableTenantIds(requester: any, tenantIdFilter?: string): Promise<Types.ObjectId[]> {
    const isAdmin = requester?.role === 'ADMIN';
    const requesterId = requester?.sub ? String(requester.sub) : '';

    if (tenantIdFilter) {
      const tenant = await this.getTenantOrThrow(tenantIdFilter);
      const tenantId = tenant._id as Types.ObjectId;

      if (isAdmin) {
        return [tenantId];
      }

      if (!requesterId) {
        throw new ForbiddenException('No autorizado para consultar este tenant');
      }

      const assignment = await this.assignmentModel
        .findOne({
          tenantId,
          userId: new Types.ObjectId(requesterId),
          active: true,
          $or: [{ status: 'APPROVED' }, { status: { $exists: false } }],
        })
        .lean();

      if (!assignment) {
        throw new ForbiddenException('No autorizado para consultar este tenant');
      }

      return [tenantId];
    }

    if (isAdmin) {
      const tenants = await this.tenantModel.find({ active: true }, { _id: 1 }).lean();
      return tenants.map((t) => t._id as Types.ObjectId);
    }

    if (!requesterId) {
      throw new ForbiddenException('No autorizado para consultar eventos');
    }

    const assignments = await this.assignmentModel
      .find(
        {
          userId: new Types.ObjectId(requesterId),
          active: true,
          $or: [{ status: 'APPROVED' }, { status: { $exists: false } }],
        },
        { tenantId: 1 },
      )
      .lean();

    if (!assignments.length) {
      return [];
    }

    const assignedTenantIds = assignments.map((a) => a.tenantId as Types.ObjectId);
    const activeTenants = await this.tenantModel
      .find(
        {
          _id: { $in: assignedTenantIds },
          active: true,
        },
        { _id: 1 },
      )
      .lean();

    return activeTenants.map((t) => t._id as Types.ObjectId);
  }

  async getTenantOrThrow(tenantId: string) {
    if (!Types.ObjectId.isValid(tenantId)) {
      throw new BadRequestException('tenantId inválido');
    }

    const tenant = await this.tenantModel.findById(tenantId).lean();
    if (!tenant || !tenant.active) {
      throw new NotFoundException('Tenant no encontrado o inactivo');
    }

    return tenant;
  }

  parseAndValidateDates(
    votingStartRaw?: string,
    votingEndRaw?: string,
    resultsPublishRaw?: string,
    minimumLeadHours?: number,
  ): {
    votingStart?: Date;
    votingEnd?: Date;
    resultsPublishAt?: Date;
  } {
    if (!votingStartRaw && !votingEndRaw && !resultsPublishRaw) {
      return {};
    }

    if (!votingStartRaw || !votingEndRaw || !resultsPublishRaw) {
      throw new BadRequestException('Debe enviar votingStart, votingEnd y resultsPublishAt');
    }

    const votingStart = new Date(votingStartRaw);
    const votingEnd = new Date(votingEndRaw);
    const resultsPublishAt = new Date(resultsPublishRaw);

    if (
      Number.isNaN(votingStart.getTime()) ||
      Number.isNaN(votingEnd.getTime()) ||
      Number.isNaN(resultsPublishAt.getTime())
    ) {
      throw new BadRequestException('Fechas inválidas');
    }

    if (votingStart >= votingEnd) {
      throw new BadRequestException('votingStart debe ser anterior a votingEnd');
    }

    if (resultsPublishAt <= votingEnd) {
      throw new BadRequestException('resultsPublishAt debe ser mayor a votingEnd');
    }
    
    if (typeof minimumLeadHours === 'number') {
      const now = Date.now();
      const diff = votingStart.getTime() - now;
      if (diff < minimumLeadHours * 60 * 60 * 1000) {
        throw new BadRequestException(
          `La fecha de inicio debe tener al menos ${minimumLeadHours} horas de anticipación`,
        );
      }
    }

    return { votingStart, votingEnd, resultsPublishAt };
  }

  getCreateLeadHours() {
    return this.createLeadHours;
  }

  getOfficialPublicationLeadHours() {
    return this.officialPublicationLeadHours;
  }

  computePublishDeadline(votingStart?: Date | null) {
    if (!votingStart) return undefined;
    return new Date(votingStart.getTime() - this.officialPublicationLeadHours * 60 * 60 * 1000);
  }

  isOfficiallyPublishedState(state?: string | null) {
    return ['OFFICIALLY_PUBLISHED', 'PUBLISHED'].includes(String(state || ''));
  }

  isOfficialPublicationConfirmed(
    event: Pick<VotingEvent, 'state' | 'publicationConfirmed'>,
  ) {
    return (
      this.isOfficiallyPublishedState(event.state) ||
      event.publicationConfirmed === true
    );
  }

  isVotingActive(
    event: Pick<VotingEvent, 'state' | 'votingStart' | 'votingEnd'>,
    now = new Date(),
  ) {
    return (
      this.isOfficiallyPublishedState(event.state) &&
      Boolean(event.votingStart) &&
      Boolean(event.votingEnd) &&
      now >= new Date(event.votingStart as Date) &&
      now <= new Date(event.votingEnd as Date)
    );
  }

  canFullyEditEvent(
    event: Pick<
      VotingEvent,
      'state' | 'publishDeadline' | 'votingStart' | 'votingEnd' | 'publicationConfirmed'
    >,
    now = new Date(),
  ) {
    if (['PUBLICATION_EXPIRED', 'CLOSED', 'RESULTS_PUBLISHED'].includes(String(event.state || ''))) {
      return false;
    }

    if (this.isOfficialPublicationConfirmed(event)) {
      return false;
    }

    if (this.isVotingActive(event, now)) {
      return false;
    }

    if (!event.publishDeadline) {
      return true;
    }

    return now < new Date(event.publishDeadline as Date);
  }

  canModifyPadronDuringVoting(
    event: Pick<VotingEvent, 'state' | 'votingEnd' | 'publicationConfirmed'>,
    now = new Date(),
  ) {
    if (!this.isOfficialPublicationConfirmed(event)) {
      return false;
    }

    if (['PUBLICATION_EXPIRED', 'CLOSED', 'RESULTS_PUBLISHED'].includes(String(event.state || ''))) {
      return false;
    }

    if (!event.votingEnd) {
      return false;
    }

    return now <= new Date(event.votingEnd as Date);
  }

  canEnableExistingPadronEntriesPostPublication(
    event: Pick<
      VotingEvent,
      'state' | 'votingEnd' | 'publicationConfirmed' | 'allowPostPublicationPadronEnable'
    >,
    now = new Date(),
  ) {
    if (!this.canModifyPadronDuringVoting(event, now)) {
      return false;
    }

    return event.allowPostPublicationPadronEnable !== false;
  }

  hasPublicationWindowExpired(
    event: Pick<VotingEvent, 'publishDeadline'>,
    now = new Date(),
  ) {
    if (!event.publishDeadline) {
      return false;
    }
    return now >= new Date(event.publishDeadline as Date);
  }

  normalizeName(input: string): string {
    return input
      .trim()
      .replace(/\s+/g, ' ')
      .toLowerCase();
  }
}

import { Injectable, InternalServerErrorException } from "@nestjs/common";
import { HttpService } from "@nestjs/axios";
import { ConfigService } from "@nestjs/config";
import { randomUUID } from "crypto";
import { VotingEventDocument } from "../../schemas/voting-event.schema";
import { Types } from "mongoose";

export type VCclaimData = {
  id: string;
}

export type DidByDniResponse = {
  ok: boolean;
  records: {
    dni: string;
    did: string;
  }[];
}

@Injectable()
export class IssuerService {
  private readonly baseUrl: string;
  private readonly username: string;
  private readonly password: string;
  private readonly issuerDid: string;
  private readonly credSchema: string;
  private readonly credType: string;

  private readonly identityBaseUrl: string;
  private readonly identityApiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.baseUrl = this.configService.get<string>('app.issuer.baseUrl')!;
    this.username = this.configService.get<string>('app.issuer.username')!;
    this.password = this.configService.get<string>('app.issuer.password')!;
    this.issuerDid = this.configService.get<string>('app.issuer.did')!;
    this.credSchema = this.configService.get<string>('app.zkAuth.credSchema')!;
    this.credType = this.configService.get<string>('app.zkAuth.credType')!;
    this.identityBaseUrl = this.configService.get<string>('app.identity.baseUrl')!;
    this.identityApiKey = this.configService.get<string>('app.identity.apiKey')!;
  }

  async issueCredential(dids: {dni: string, did: string}[], eventId: string, nullifiers: string[]) {
    if(dids.length === 0 || dids.length !== nullifiers.length) {
      throw new InternalServerErrorException(`DIDs and nullifiers arrays must be of the same non-zero length`);
    }

    const url = `${this.baseUrl}/v2/identities/${this.issuerDid}/credentials`;

    const promises: Promise<void>[] = [];
    const credentialData: Record<string, { credentialData: string }> = {};
    for (const user of dids) {
      const body = {
        credentialSchema: this.credSchema,
        type: this.credType,
        credentialSubject: {
          id: user.did,
          eventId: eventId,
          nullifier: nullifiers.shift(),
        },
      };

      promises.push(
        this.httpService.axiosRef
          .post<VCclaimData>(url, body, {
            auth: {
              username: this.username,
              password: this.password,
            },
          })
          .then((response) => {
            credentialData[user.dni] = {
              credentialData: response.data.id,
            };
          }),
      );
    }

    try {
      await Promise.all(promises);
    } catch (error: any) {
      console.error(`Error issuing credential:`, error.response?.data || error.message);
      throw new InternalServerErrorException(`Error issuing credential for DNI`);
    }

    return credentialData;
  }

  async getDidsByDnis(dnis: string[]) {
    if (dnis.length === 0) {
      return [];
    }

    const url = `${this.identityBaseUrl}/registry/get-by-dni`;
    try {
      const response = await this.httpService.axiosRef.get<DidByDniResponse>(url, {
        params: {
          dnis: dnis.join(','),
        },
        headers: {
          'x-api-key': this.identityApiKey,
        }
      });

      if (!response.data.ok) {
        throw new Error(`Identity service responded with ok=false: ${JSON.stringify(response.data)}`);
      }

      return response.data.records;
    } catch (error: any) {
      console.error('Error fetching DIDs for DNIs:', error.response?.data || error.message);
      throw new InternalServerErrorException(`Error fetching DIDs for given DNIs`);
    }
  }
}

import {
  BadRequestException,
  Injectable,
  InternalServerErrorException,
  Logger,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { randomUUID } from 'crypto';
import { normalizeCarnet } from '../../utils/carnet-normalizer';
import type { PadronImportError } from '../../schemas/padron-import-job.schema';

export type GeminiPadronDraftRecord = {
  id: string;
  carnet: string;
  enabled: boolean;
  sourceKind: 'PARSED' | 'MANUAL';
  sourceRow: number | null;
  updatedAt: string | null;
};

export type GeminiPadronDraft = {
  fileName: string;
  uploadedAt: string;
  sourceType: 'PDF_GEMINI' | 'IMAGE_GEMINI';
  analysisProvider: 'GEMINI_CLIENT';
  model: string | null;
  records: GeminiPadronDraftRecord[];
  observations: PadronImportError[];
};

type GeminiGenerateContentResponse = {
  candidates?: Array<{
    content?: {
      parts?: Array<{
        text?: string;
      }>;
    };
    finishReason?: string;
  }>;
  promptFeedback?: {
    blockReason?: string;
  };
};

type GeminiRawResponse = {
  records?: unknown;
  observations?: unknown;
};

const DEFAULT_GEMINI_MODEL = 'gemini-2.5-flash';
const MAX_GEMINI_FILE_BYTES = 20 * 1024 * 1024;
const ENABLED_TRUE_VALUES = new Set(['1', 'true', 'si', 'sí', 'habilitado', 'activo']);
const ENABLED_FALSE_VALUES = new Set([
  '0',
  'false',
  'no',
  'inhabilitado',
  'deshabilitado',
  'inactivo',
]);

const PADRON_GEMINI_PROMPT = `
Analiza el documento adjunto del padrón electoral. El documento puede ser PDF o imagen.

Tu tarea es extraer SOLO una estructura JSON con esta forma exacta:
{
  "records": [
    { "carnet": "12345678", "habilitado": true }
  ],
  "observations": [
    { "message": "texto", "rowIndex": 3, "rawValue": "valor original" }
  ]
}

Reglas obligatorias:
1. Responde solo JSON válido. No agregues markdown, comentarios ni texto extra.
2. "records" debe contener solo filas entendibles con carnet y habilitación claros.
3. "observations" debe contener filas dudosas, incompletas, duplicadas, ruido, encabezados confusos o datos que no puedas interpretar con seguridad.
4. Interpreta la columna de habilitación así:
   - si, sí, habilitado, true, activo => true
   - no, inhabilitado, deshabilitado, false, inactivo => false
5. Ignora encabezados, numeración decorativa, títulos y texto que no sea una fila real del padrón.
6. Si el documento está en formato tabla o columnas, respeta el orden lógico de lectura.
7. No inventes carnets ni estados.
8. Si no estás seguro de una fila, envíala a "observations" en vez de asumir.
9. Mantén el carnet en formato legible; no agregues caracteres que no estén en el documento.
10. Si el documento no contiene filas útiles, devuelve "records": [] y explica el motivo en "observations".
`.trim();

@Injectable()
export class PadronGeminiImportService {
  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {}

  async analyzeDocument(file: {
    buffer: Buffer;
    originalname?: string;
    mimetype?: string;
    size?: number;
  }): Promise<GeminiPadronDraft> {
    const apiKey = this.configService.get<string>('app.ai.gemini.apiKey') ?? '';
    const model =
      this.configService.get<string>('app.ai.gemini.model') ?? DEFAULT_GEMINI_MODEL;

    if (!apiKey.trim()) {
      throw new InternalServerErrorException('No se pudo procesar el padrón. Intenta nuevamente.');
    }

    if (!file?.buffer?.length) {
      throw new BadRequestException('Archivo requerido');
    }

    if (file.buffer.length > MAX_GEMINI_FILE_BYTES) {
      throw new BadRequestException('El archivo supera el tamaño permitido.');
    }

    const mimeType = this.getMimeType(file);

    try {
      const response = await this.httpService.axiosRef.post<GeminiGenerateContentResponse>(
        `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(
          model,
        )}:generateContent`,
        {
          systemInstruction: {
            parts: [{ text: 'Responde solo con JSON válido y no inventes datos del padrón.' }],
          },
          contents: [
            {
              role: 'user',
              parts: [
                { text: PADRON_GEMINI_PROMPT },
                {
                  inline_data: {
                    mime_type: mimeType,
                    data: file.buffer.toString('base64'),
                  },
                },
              ],
            },
          ],
          generationConfig: {
            temperature: 0.1,
            responseMimeType: 'application/json',
            responseSchema: {
              type: 'OBJECT',
              properties: {
                records: {
                  type: 'ARRAY',
                  items: {
                    type: 'OBJECT',
                    properties: {
                      carnet: { type: 'STRING' },
                      habilitado: { type: 'BOOLEAN' },
                    },
                    required: ['carnet', 'habilitado'],
                  },
                },
                observations: {
                  type: 'ARRAY',
                  items: {
                    type: 'OBJECT',
                    properties: {
                      message: { type: 'STRING' },
                      rowIndex: { type: 'NUMBER' },
                      rawValue: { type: 'STRING' },
                    },
                    required: ['message'],
                  },
                },
              },
              required: ['records', 'observations'],
            },
          },
        },
        {
          headers: {
            'x-goog-api-key': apiKey,
            'Content-Type': 'application/json',
          },
          timeout: 60000,
        },
      );

      const rawText = this.extractJsonText(response.data);
      const parsed = this.parseGeminiJson(rawText);
      const normalized = this.normalizeGeminiResult(parsed);

      return {
        fileName: file.originalname || 'padron',
        uploadedAt: new Date().toISOString(),
        sourceType: mimeType === 'application/pdf' ? 'PDF_GEMINI' : 'IMAGE_GEMINI',
        analysisProvider: 'GEMINI_CLIENT',
        model,
        records: normalized.records,
        observations: normalized.observations,
      };
    } catch (error) {
      console.dir(error, { depth: null });
      if (error instanceof BadRequestException || error instanceof InternalServerErrorException) {
        throw error;
      }

      throw new BadRequestException('No se pudo procesar el padrón. Intenta nuevamente.');
    }
  }

  private getMimeType(file: { mimetype?: string; originalname?: string }) {
    const mimeType = String(file.mimetype ?? '').trim();
    if (mimeType) return mimeType;

    const lowerName = String(file.originalname ?? '').toLowerCase();
    if (lowerName.endsWith('.pdf')) return 'application/pdf';
    if (lowerName.endsWith('.png')) return 'image/png';
    if (lowerName.endsWith('.webp')) return 'image/webp';
    return 'image/jpeg';
  }

  private extractJsonText(response: GeminiGenerateContentResponse) {
    const text = response.candidates?.[0]?.content?.parts
      ?.map((part) => part.text ?? '')
      .join('')
      .trim();

    if (text) return text;

    if (response.promptFeedback?.blockReason) {
      throw new BadRequestException('No se pudo procesar el padrón. Intenta nuevamente.');
    }

    throw new BadRequestException('No se pudo obtener un resultado del documento.');
  }

  private parseGeminiJson(rawText: string): GeminiRawResponse {
    try {
      return JSON.parse(rawText) as GeminiRawResponse;
    } catch {
      const firstBrace = rawText.indexOf('{');
      const lastBrace = rawText.lastIndexOf('}');
      if (firstBrace >= 0 && lastBrace > firstBrace) {
        return JSON.parse(rawText.slice(firstBrace, lastBrace + 1)) as GeminiRawResponse;
      }
      throw new BadRequestException('No se pudo interpretar el resultado del documento.');
    }
  }

  private normalizeGeminiResult(parsed: GeminiRawResponse): {
    records: GeminiPadronDraftRecord[];
    observations: PadronImportError[];
  } {
    const rawRecords = Array.isArray(parsed.records) ? parsed.records : [];
    const rawObservations = Array.isArray(parsed.observations) ? parsed.observations : [];
    const observations: PadronImportError[] = [];
    const records: GeminiPadronDraftRecord[] = [];
    const seenCarnets = new Set<string>();

    rawObservations.forEach((entry, index) => {
      const normalized = this.parseObservation(entry, index + 1);
      if (normalized) observations.push(normalized);
    });

    rawRecords.forEach((entry, index) => {
      if (!entry || typeof entry !== 'object') {
        observations.push({
          code: 'INVALID_RECORD',
          message: 'Se detectó una fila con un formato que no se pudo interpretar.',
          rowIndex: index + 1,
          rawValue: String(entry ?? ''),
        });
        return;
      }

      const raw = entry as Record<string, unknown>;
      const carnet = normalizeCarnet(
        String(raw.carnet ?? raw.ci ?? raw.carnetIdentidad ?? ''),
      );
      if (!carnet) {
        observations.push({
          code: 'INVALID_CARNET',
          message: 'Se detectó una fila sin un carnet legible.',
          rowIndex: index + 1,
          rawValue: this.safeJson(raw),
        });
        return;
      }

      const enabled = this.parseEnabledValue(raw.habilitado ?? raw.enabled ?? raw.estado);
      if (enabled === null) {
        observations.push({
          code: 'INVALID_ENABLED_VALUE',
          message: 'No se pudo interpretar si el registro está habilitado o no.',
          rowIndex: index + 1,
          rawValue: this.safeJson(raw),
        });
        return;
      }

      if (seenCarnets.has(carnet)) {
        observations.push({
          code: 'DUPLICATE_CARNET',
          message: 'Se detectó un carnet duplicado.',
          rowIndex: index + 1,
          rawValue: carnet,
        });
        return;
      }

      seenCarnets.add(carnet);
      records.push({
        id: randomUUID(),
        carnet,
        enabled,
        sourceKind: 'PARSED',
        sourceRow: index + 1,
        updatedAt: null,
      });
    });

    if (!records.length && !observations.length) {
      observations.push({
        code: 'EMPTY_RESULT',
        message: 'No se pudieron extraer registros u observaciones del documento.',
        rowIndex: null,
        rawValue: null,
      });
    }

    return { records, observations };
  }

  private parseEnabledValue(value: unknown): boolean | null {
    if (typeof value === 'boolean') return value;

    const normalized = String(value ?? '').trim().toLowerCase();
    if (!normalized) return null;
    if (ENABLED_TRUE_VALUES.has(normalized)) return true;
    if (ENABLED_FALSE_VALUES.has(normalized)) return false;
    return null;
  }

  private parseObservation(value: unknown, fallbackIndex: number): PadronImportError | null {
    if (typeof value === 'string' && value.trim()) {
      return {
        code: 'GEMINI_OBSERVATION',
        message: value.trim(),
        rowIndex: fallbackIndex,
        rawValue: null,
      };
    }

    if (!value || typeof value !== 'object') return null;

    const raw = value as Record<string, unknown>;
    const message = String(raw.message ?? raw.reason ?? raw.error ?? '').trim();
    if (!message) return null;

    return {
      code: String(raw.code ?? 'GEMINI_OBSERVATION'),
      message,
      rowIndex:
        raw.rowIndex === null || raw.rowIndex === undefined || Number.isNaN(Number(raw.rowIndex))
          ? fallbackIndex
          : Number(raw.rowIndex),
      rawValue:
        raw.rawValue === null || raw.rawValue === undefined ? null : String(raw.rawValue),
    };
  }

  private safeJson(value: unknown) {
    try {
      return JSON.stringify(value);
    } catch {
      return null;
    }
  }
}

import { HttpService } from '@nestjs/axios';
import { BadRequestException, Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { normalizeCarnet } from '../../utils/carnet-normalizer';

export type SupportedPadronSourceType = 'PDF' | 'IMAGE';

export type ParsedPadronRow = {
  ci: string;
  enabled: boolean;
  sourceRow?: number | null;
};

export type PadronParserError = {
  code: string;
  message: string;
  rowIndex?: number | null;
  rawValue?: string | null;
};

export type PadronPdfParserResult = {
  rows: ParsedPadronRow[];
  errors: PadronParserError[];
  provider: string;
  model: string | null;
  usedFallback: boolean;
};

type DeterministicSignal = {
  confidence: number;
  shouldEscalate: boolean;
  headerDetected: boolean;
  candidateLines: number;
  extractedLines: number;
  rowsWithExplicitEnabled: number;
  readableRatio: number;
};

type DeterministicPadronPdfParserResult = PadronPdfParserResult & {
  signal: DeterministicSignal;
};

type PadronSourceFile = {
  buffer: Buffer;
  originalname: string;
  mimetype: string;
};

@Injectable()
export class PadronPdfParserService {
  private readonly geminiApiKey: string;
  private readonly geminiModel: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.geminiApiKey = this.configService.get<string>('app.ai.gemini.apiKey') ?? '';
    this.geminiModel =
      this.configService.get<string>('app.ai.gemini.model') ?? 'gemini-2.5-flash';
  }

  validateSourceFile(file: { buffer?: Buffer; mimetype?: string; originalname?: string }) {
    const buffer = file?.buffer;
    if (!buffer || !buffer.length) {
      throw new BadRequestException('Archivo de padrón requerido');
    }

    const mimeType = String(file?.mimetype ?? '').toLowerCase();
    const fileName = String(file?.originalname ?? '').toLowerCase();
    const isPdfMime = mimeType === 'application/pdf';
    const hasPdfExtension = fileName.endsWith('.pdf');
    const isImageMime = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'].includes(mimeType);
    const hasImageExtension = ['.jpg', '.jpeg', '.png', '.webp'].some((ext) =>
      fileName.endsWith(ext),
    );
    const hasPdfHeader = buffer.subarray(0, 4).toString('utf-8') === '%PDF';
    const hasPngHeader =
      buffer.length >= 8 &&
      buffer.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
    const hasJpegHeader =
      buffer.length >= 3 &&
      buffer[0] === 0xff &&
      buffer[1] === 0xd8 &&
      buffer[2] === 0xff;
    const hasWebpHeader =
      buffer.length >= 12 &&
      buffer.subarray(0, 4).toString('ascii') === 'RIFF' &&
      buffer.subarray(8, 12).toString('ascii') === 'WEBP';

    if (isPdfMime || hasPdfExtension) {
      if (!hasPdfHeader) {
        throw new BadRequestException('Archivo PDF inválido');
      }
      return;
    }

    if (isImageMime || hasImageExtension) {
      if (!hasPngHeader && !hasJpegHeader && !hasWebpHeader) {
        throw new BadRequestException('Archivo de imagen inválido');
      }
      return;
    }

    throw new BadRequestException(
      'Solo se admiten archivos PDF, JPG, JPEG, PNG o WEBP para el padrón',
    );
  }

  validatePdfFile(file: { buffer?: Buffer; mimetype?: string; originalname?: string }) {
    return this.validateSourceFile(file);
  }

  async parsePdf(
    file: PadronSourceFile,
  ): Promise<PadronPdfParserResult> {
    return this.parseDocument(file);
  }

  async parseDocument(file: PadronSourceFile): Promise<PadronPdfParserResult> {
    this.validateSourceFile(file);

    const deterministicResult = this.parseDeterministically(file.buffer);

    if (!deterministicResult.signal.shouldEscalate) {
      return this.stripDeterministicSignal(deterministicResult);
    }

    if (this.geminiApiKey) {
      try {
        return await this.parseWithGemini(file.buffer, file.mimetype);
      } catch {
        return {
          ...this.stripDeterministicSignal(deterministicResult),
          usedFallback: true,
        };
      }
    }

    return this.stripDeterministicSignal(deterministicResult);
  }

  getSourceType(file: { mimetype?: string; originalname?: string }): SupportedPadronSourceType {
    const mimeType = String(file?.mimetype ?? '').toLowerCase();
    const fileName = String(file?.originalname ?? '').toLowerCase();
    if (
      mimeType === 'application/pdf' ||
      fileName.endsWith('.pdf')
    ) {
      return 'PDF';
    }
    return 'IMAGE';
  }

  private async parseWithGemini(
    buffer: Buffer,
    mimeType: string,
  ): Promise<PadronPdfParserResult> {
    const prompt = [
      'Extrae un padrón tabular desde este documento o imagen.',
      'Devuelve SOLO JSON válido con la forma {"rows":[{"ci":"...","enabled":true}],"errors":[{"code":"...","message":"...","rowIndex":1,"rawValue":"..."}]}.',
      'Cada fila debe contener únicamente "ci" y "enabled".',
      'Reconoce columnas equivalentes a carnet, ci, dni, habilitado o estado.',
      'Si el valor de habilitación no existe, asume enabled=true.',
      'Usa Gemini solo para resolver PDFs escaneados, imágenes de tabla, contenido ambiguo o mal tabulado.',
      'No devuelvas markdown ni texto adicional.',
    ].join(' ');

    const response = await this.httpService.axiosRef.post(
      `https://generativelanguage.googleapis.com/v1beta/models/${this.geminiModel}:generateContent?key=${this.geminiApiKey}`,
      {
        contents: [
          {
            parts: [
              { text: prompt },
              {
                inline_data: {
                  mime_type: mimeType,
                  data: buffer.toString('base64'),
                },
              },
            ],
          },
        ],
        generationConfig: {
          temperature: 0,
          responseMimeType: 'application/json',
        },
      },
    );

    const rawText =
      response?.data?.candidates?.[0]?.content?.parts?.map((part: any) => part?.text ?? '').join('') ??
      '';

    const parsed = JSON.parse(this.extractJsonPayload(rawText));
    const rows = Array.isArray(parsed?.rows)
      ? parsed.rows.map((row: any, index: number) => ({
          ci: String(row?.ci ?? '').trim(),
          enabled: row?.enabled !== false,
          sourceRow: typeof row?.sourceRow === 'number' ? row.sourceRow : index + 1,
        }))
      : [];

    const errors = Array.isArray(parsed?.errors)
      ? parsed.errors.map((error: any) => ({
          code: String(error?.code ?? 'PARSER_WARNING'),
          message: String(error?.message ?? 'Advertencia de parseo'),
          rowIndex:
            typeof error?.rowIndex === 'number' ? error.rowIndex : null,
          rawValue: error?.rawValue ? String(error.rawValue) : null,
        }))
      : [];

    return {
      rows,
      errors,
      provider: 'gemini',
      model: this.geminiModel,
      usedFallback: false,
    };
  }

  private parseDeterministically(buffer: Buffer): DeterministicPadronPdfParserResult {
    const text = buffer
      .toString('latin1')
      .replace(/\0/g, ' ')
      .replace(/[^\x09\x0A\x0D\x20-\x7E\u00C0-\u017F]/g, ' ');

    const rawLines = text
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean);

    // sourceRow se calcula sobre líneas lógicas del documento ya limpiadas:
    // excluye headers de transporte/formato (%PDF, PNG, JFIF, etc.) y ruido binario.
    const lines = rawLines.filter((line) => !this.isIgnorableTransportLine(line));

    const rows: ParsedPadronRow[] = [];
    const errors: PadronParserError[] = [];
    let rowsWithExplicitEnabled = 0;

    const headerDetected = lines.some((line) => {
      const lowered = line.toLowerCase();
      return (
        (lowered.includes('carnet') || lowered.includes('ci') || lowered.includes('dni')) &&
        lowered.includes('habil')
      );
    });

    const candidateLines = lines.filter((line) =>
      line
        .replace(/[|;,]/g, ' ')
        .split(/\s+/)
        .some((chunk) => Boolean(normalizeCarnet(chunk))),
    ).length;

    lines.forEach((line, index) => {
      const chunks = line
        .replace(/[|;,]/g, ' ')
        .split(/\s+/)
        .map((chunk) => chunk.trim())
        .filter(Boolean);

      const ciToken = chunks.find((chunk) => Boolean(normalizeCarnet(chunk)));
      if (!ciToken) {
        return;
      }

      const enabledToken = chunks.find((chunk) =>
        [
          'si',
          'sí',
          'no',
          'true',
          'false',
          '1',
          '0',
          'habilitado',
          'inhabilitado',
          'deshabilitado',
          'activo',
          'inactivo',
        ].includes(chunk.toLowerCase()),
      );

      const enabled = this.parseEnabledToken(enabledToken);
      if (enabled === null) {
        errors.push({
          code: 'INVALID_ENABLED_VALUE',
          message: 'No se pudo interpretar la columna de habilitación',
          rowIndex: index + 1,
          rawValue: line,
        });
        return;
      }

      if (enabledToken) {
        rowsWithExplicitEnabled++;
      }

      rows.push({
        ci: ciToken,
        enabled,
        sourceRow: index + 1,
      });
    });

    if (!rows.length) {
      errors.push({
        code: 'EMPTY_RESULT',
        message: 'No se encontraron filas tabulares válidas en el PDF',
      });
    }

    const readableChars = text.replace(/\s/g, '').length;
    const binaryPenaltyChars = (buffer.toString('latin1').match(/[^\x09\x0A\x0D\x20-\x7E\u00C0-\u017F]/g) ?? [])
      .length;
    const readableRatio =
      readableChars + binaryPenaltyChars > 0
        ? readableChars / (readableChars + binaryPenaltyChars)
        : 0;

    const confidence = this.calculateDeterministicConfidence({
      rowsCount: rows.length,
      errorsCount: errors.length,
      headerDetected,
      candidateLines,
      rowsWithExplicitEnabled,
      readableRatio,
    });

    return {
      rows,
      errors,
      provider: 'deterministic-text',
      model: null,
      usedFallback: false,
      signal: {
        confidence,
        shouldEscalate: this.shouldEscalateToGemini({
          rowsCount: rows.length,
          errorsCount: errors.length,
          headerDetected,
          candidateLines,
          rowsWithExplicitEnabled,
          readableRatio,
          confidence,
        }),
        headerDetected,
        candidateLines,
        extractedLines: lines.length,
        rowsWithExplicitEnabled,
        readableRatio,
      },
    };
  }

  private parseEnabledToken(value?: string): boolean | null {
    if (!value) return true;

    const normalized = value.trim().toLowerCase();
    if (['1', 'true', 'si', 'sí', 'habilitado', 'activo'].includes(normalized)) {
      return true;
    }
    if (['0', 'false', 'no', 'inhabilitado', 'deshabilitado', 'inactivo'].includes(normalized)) {
      return false;
    }
    return null;
  }

  private extractJsonPayload(rawText: string) {
    const trimmed = String(rawText ?? '').trim();
    const jsonMatch = trimmed.match(/\{[\s\S]*\}/);
    if (!jsonMatch) {
      throw new BadRequestException('La respuesta del parser Gemini no contiene JSON válido');
    }
    return jsonMatch[0];
  }

  private isIgnorableTransportLine(line: string): boolean {
    const lowered = line.toLowerCase().trim();
    if (!lowered) return true;

    if (
      lowered.startsWith('%pdf') ||
      ['obj', 'endobj', 'stream', 'endstream', 'xref', 'trailer', 'startxref'].includes(lowered)
    ) {
      return true;
    }

    if (['png', 'jfif', 'exif', 'webp', 'riff'].includes(lowered)) {
      return true;
    }

    const hasCiToken = lowered
      .replace(/[|;,]/g, ' ')
      .split(/\s+/)
      .some((chunk) => Boolean(normalizeCarnet(chunk)));
    const hasEnabledHint = /habil|si|sí|no|true|false|activo|inactivo/.test(lowered);
    const hasTableHint = /carnet|ci|dni/.test(lowered);
    const hasWhitespaceOrDelimiter = /[\s|;,]/.test(line);

    if (!hasCiToken && !hasEnabledHint && !hasTableHint && !hasWhitespaceOrDelimiter) {
      return true;
    }

    return false;
  }

  private calculateDeterministicConfidence(params: {
    rowsCount: number;
    errorsCount: number;
    headerDetected: boolean;
    candidateLines: number;
    rowsWithExplicitEnabled: number;
    readableRatio: number;
  }) {
    const {
      rowsCount,
      errorsCount,
      headerDetected,
      candidateLines,
      rowsWithExplicitEnabled,
      readableRatio,
    } = params;

    if (rowsCount <= 0) return 0;

    let confidence = 0.2;

    confidence += Math.min(0.25, rowsCount * 0.08);
    confidence += headerDetected ? 0.2 : 0;
    confidence += candidateLines > 0 ? Math.min(0.15, rowsCount / candidateLines * 0.15) : 0;
    confidence += rowsCount > 0 ? Math.min(0.15, rowsWithExplicitEnabled / rowsCount * 0.15) : 0;
    confidence += Math.max(0, Math.min(0.15, (1 - errorsCount / Math.max(rowsCount, 1)) * 0.15));
    confidence += Math.max(0, Math.min(0.1, readableRatio * 0.1));

    return Math.max(0, Math.min(1, confidence));
  }

  private shouldEscalateToGemini(params: {
    rowsCount: number;
    errorsCount: number;
    headerDetected: boolean;
    candidateLines: number;
    rowsWithExplicitEnabled: number;
    readableRatio: number;
    confidence: number;
  }) {
    const {
      rowsCount,
      errorsCount,
      headerDetected,
      candidateLines,
      rowsWithExplicitEnabled,
      readableRatio,
      confidence,
    } = params;

    if (rowsCount <= 0) return true;
    if (readableRatio < 0.2) return true;
    if (candidateLines > 0 && rowsCount / candidateLines < 0.5) return true;
    if (errorsCount > rowsCount) return true;
    if (!headerDetected && rowsCount < 3 && rowsWithExplicitEnabled === 0) return true;
    return confidence < 0.65;
  }

  private stripDeterministicSignal(
    result: DeterministicPadronPdfParserResult,
  ): PadronPdfParserResult {
    return {
      rows: result.rows,
      errors: result.errors,
      provider: result.provider,
      model: result.model,
      usedFallback: result.usedFallback,
    };
  }
}

import { votingContractAbi } from "@/api/contracts/VoteContract";
import { availableNetworks } from "@/api/params";
import { Injectable } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";
import { ethers } from "ethers";

@Injectable()
export class VoteReaderService {
  private readonly chain: string;
  private readonly provider: ethers.JsonRpcProvider;
  private readonly vote: ethers.Contract;

  constructor(
    private readonly configService: ConfigService,
  ) {
    this.chain = this.configService.get<string>('app.blockchain.chain')!;
    const { voteContract, bundler } = availableNetworks[this.chain];

    this.provider = new ethers.JsonRpcProvider(bundler);
    this.vote = new ethers.Contract(
      voteContract,
      votingContractAbi,
      this.provider,
    );
  }

  async getResults(voteEventId: string) {
    const rawResults = await this.vote.getVoteResults(voteEventId);
    console.log('Raw results from contract:', rawResults);

    const [ options, votes ] = rawResults;

    const results = options.map((option: string, index: number) => ({
      option,
      votes: votes[index].toString(),
    }));

    return results;
  }
}

import { availableNetworks } from "@/api/params";
import { Injectable } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";
import { createSmartAccountClient, SmartAccountClient } from "permissionless";
import { createPimlicoClient } from "permissionless/clients/pimlico";
import { createPublicClient, http } from "viem";
import { entryPoint07Address, toCoinbaseSmartAccount } from "viem/account-abstraction";
import { privateKeyToAccount } from "viem/accounts";
import { VotingEventDocument } from "../../schemas/voting-event.schema";
import { VoteContractCalls } from "@/api/vote";

@Injectable()
export class VoteWritterService {
  private readonly chain: string;
  private readonly pk: string;
  private smartAccountClient?: SmartAccountClient = undefined;
  private publicClient: any = undefined;
  private readonly RECEIPT_WAIT_TIMEOUT_MS = 15 * 60 * 1000;
  private readonly RECEIPT_POLL_INTERVAL_MS = 2000;
  
  constructor(private readonly configService: ConfigService) {
    this.chain = this.configService.get<string>('app.blockchain.chain')!;
    this.pk = this.configService.get<string>('app.blockchain.privateKey')!;
    this.getAccount();
  }

  async getAccount() {
    const privateKey = this.pk;
    const {chain: chainConfig, bundler} = availableNetworks[this.chain];

    this.publicClient = createPublicClient({
      chain: chainConfig,
      transport: http(bundler),
    });

    const account = await toCoinbaseSmartAccount({
      client: this.publicClient,
      owners: [privateKeyToAccount(privateKey as `0x${string}`)],
      version: '1.1',
    });

    const pimlicoClient = createPimlicoClient({
      chain: chainConfig,
      transport: http(bundler),
      entryPoint: {
        address: entryPoint07Address,
        version: '0.7',
      },
    });

    this.smartAccountClient = createSmartAccountClient({
      account,
      chain: chainConfig,
      bundlerTransport: http(bundler),
      paymaster: pimlicoClient,
    });
  }

  async executeOperation(
    callData: any,
    waitEvent: ((chainId: string, eventName: string, fromBlock: number) => Promise<any>) | undefined,
    eventName: string | undefined,
  ) {
    if (!this.smartAccountClient) {
      throw new Error('SmartAccountClient not initialized, call getAccount() first.');
    }

    const txHash = await this.smartAccountClient.sendTransaction(callData);
    const receipt = await this.waitForReceiptWithFallback(txHash);

    let returnData: any;
    if (waitEvent && eventName) {
      returnData = await waitEvent(this.chain, eventName, receipt.blockNumber);
    }

    const block = await this.publicClient.getBlock({blockNumber: receipt.blockNumber});
    const date = new Date(Number(block.timestamp) * 1000);
    return {returnData, receipt, date: date.toLocaleString()};
  }

  async waitForReceiptWithFallback(txHash: `0x${string}`) {
    try {
      return await this.publicClient.waitForTransactionReceipt({
        hash: txHash,
        timeout: this.RECEIPT_WAIT_TIMEOUT_MS,
        pollingInterval: this.RECEIPT_POLL_INTERVAL_MS,
      });
    } catch (error) {
      if (!this.isReceiptTimeoutError(error)) {
        throw error;
      }

      try {
        return await this.publicClient.getTransactionReceipt({ hash: txHash });
      } catch {
        const timeoutError = new Error(
          `Timed out while waiting for transaction receipt for ${txHash}`,
        );
        timeoutError.name = 'WaitForTransactionReceiptTimeoutError';
        timeoutError.cause = error;
        throw timeoutError;
      }
    }
  };

  isReceiptTimeoutError(error: any) {
    const name = String(error?.name || '').toLowerCase();
    const message = String(error?.message || '').toLowerCase();
    return (
      name.includes('waitfortransactionreceipttimeouterror') ||
      message.includes('waitfortransactionreceipttimeouterror') ||
      message.includes('timed out while waiting for transaction')
    );
  };

  dateToUnixTimestamp(date: Date): number {
    return Math.floor(date.getTime() / 1000);
  }

  async createVote(event: VotingEventDocument, voters: string[], options: string[]) {
    const voteNullifiers = voters.map(() => {
      const uint32 = new Uint32Array(1);
      crypto.getRandomValues(uint32);
      return uint32[0].toString();
    });

    // Copy options and add 'BLANK' as an additional option
    const optionsWithBlank = [...options];
    optionsWithBlank.push('BLANK');

    const callData = VoteContractCalls.createVote(
      this.chain,
      event._id.toString(),
      event.name,
      this.dateToUnixTimestamp(event.votingStart!),
      this.dateToUnixTimestamp(event.votingEnd!),
      this.dateToUnixTimestamp(event.resultsPublishAt!),
      voteNullifiers,
      optionsWithBlank
    );

    await this.executeOperation(callData, undefined, undefined);
    return voteNullifiers;
  }

  async updateVoteSchedule(eventId: string, start: Date, end: Date, publishAt: Date) {
    const callData = VoteContractCalls.updateVoteSchedule(
      this.chain,
      eventId,
      this.dateToUnixTimestamp(start),
      this.dateToUnixTimestamp(end),
      this.dateToUnixTimestamp(publishAt)
    );

    await this.executeOperation(callData, undefined, undefined);
  }

  async castVote(eventId: string, optionId: string, nullifier: string) {
    const callData = VoteContractCalls.castVote(
      this.chain,
      eventId,
      optionId,
      nullifier
    );

    await this.executeOperation(callData, undefined, undefined);
  }

  async addNewVoters(eventId: string, count: number) {
    const newNullifiers = Array.from({ length: count }, () => {
      const uint32 = new Uint32Array(1);
      crypto.getRandomValues(uint32);
      return uint32[0].toString();
    });

    const callData = VoteContractCalls.addNewVoters(
      this.chain,
      eventId,
      newNullifiers
    );
    await this.executeOperation(callData, undefined, undefined);
    return newNullifiers;
  }

  async disableVote(eventId: string) {
    const callData = VoteContractCalls.disableVote(
      this.chain,
      eventId
    );
    await this.executeOperation(callData, undefined, undefined);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Cron } from '@nestjs/schedule';
import { Model } from 'mongoose';
import {
  VotingEvent,
  VotingEventDocument,
} from '../../schemas/voting-event.schema';
import { InstitutionalVotingNotificationsService } from '../notifications/institutional-voting-notifications.service';

@Injectable()
export class InstitutionalVotingLifecycleService {
  private readonly logger = new Logger(InstitutionalVotingLifecycleService.name);

  constructor(
    @InjectModel(VotingEvent.name)
    private readonly votingEventModel: Model<VotingEventDocument>,
    private readonly notificationsService: InstitutionalVotingNotificationsService,
  ) {}

  @Cron('*/1 * * * *')
  async processLifecycle() {
    const now = new Date();
    const reminderWindowEnd = new Date(now.getTime() + 30 * 60 * 1000);

    const remindable = await this.votingEventModel
      .find({
        state: { $in: ['DRAFT', 'READY_FOR_REVIEW'] },
        publishDeadline: { $gt: now, $lte: reminderWindowEnd },
        $or: [
          { officialPublicationReminderSentAt: { $exists: false } },
          { officialPublicationReminderSentAt: null },
        ],
      })
      .limit(50);

    for (const event of remindable) {
      try {
        await this.notificationsService.sendOfficialPublicationReminder(event);
      } catch (error: any) {
        this.logger.warn(
          `No se pudo enviar recordatorio de publicación oficial para eventId=${String(event._id)}: ${error?.message ?? error}`,
        );
      }
    }

    await this.votingEventModel.updateMany(
      {
        state: { $in: ['DRAFT', 'READY_FOR_REVIEW'] },
        publishDeadline: { $lte: now },
      },
      {
        $set: {
          state: 'PUBLICATION_EXPIRED',
          publicationExpiredAt: now,
          publicationConfirmed: false,
        },
      },
    );

    await this.votingEventModel.updateMany(
      {
        state: { $in: ['OFFICIALLY_PUBLISHED', 'PUBLISHED'] },
        votingEnd: { $lte: now },
      },
      {
        $set: { state: 'CLOSED' },
      },
    );

    const publishable = await this.votingEventModel
      .find({
        state: { $in: ['OFFICIALLY_PUBLISHED', 'PUBLISHED', 'CLOSED', 'RESULTS_PUBLISHED'] },
        resultsPublishAt: { $lte: now },
        resultsNotifiedAt: { $exists: false },
      })
      .limit(50);

    for (const event of publishable) {
      if (event.state !== 'RESULTS_PUBLISHED') {
        event.state = 'RESULTS_PUBLISHED';
      }

      try {
        await event.save();
        await this.notificationsService.notifyResultsAvailableIfEligible(event);
        event.resultsNotificationFailedAt = undefined;
        event.resultsNotificationError = undefined;
        await event.save();
      } catch (error: any) {
        event.resultsNotificationFailedAt = new Date();
        event.resultsNotificationError = String(error?.message ?? error ?? 'unknown_error');
        await event.save();
        this.logger.warn(
          `No se pudo notificar resultados para eventId=${String(event._id)}: ${error?.message ?? error}`,
        );
      }
    }
  }
}

