import { Inject, Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import * as admin from 'firebase-admin';
import { MailService } from '@/modules/mail/mail.service';
import { NotificationLog } from '@/modules/notifications/schemas/notification-log.schema';
import { UserNotification } from '@/modules/notifications/schemas/user-notification.schema';
import {
  TenantAdminAssignment,
  TenantAdminAssignmentDocument,
} from '@/modules/institutional-tenants/schemas/tenant-admin-assignment.schema';
import { RoledUser, RoledUserDocument } from '@/modules/auth/schemas/roledUser.schema';
import {
  VotingEvent,
  VotingEventDocument,
} from '../../schemas/voting-event.schema';
import { PadronUsersService } from '../core/padron-users.service';

const CONVOCATION_DATA_TYPE = 'INSTITUTIONAL_PADRON_REVIEW_OPEN';

type NotificationPayload = {
  type: string;
  title: string;
  body: string;
  data: Record<string, string>;
};

type NotificationRecipient = {
  _id: Types.ObjectId;
  dni: string;
  active: boolean;
  enabled: boolean;
};

@Injectable()
export class InstitutionalVotingNotificationsService {
  constructor(
    @Inject('FIREBASE_ADMIN')
    private readonly fb: typeof admin,
    @InjectModel(UserNotification.name)
    private readonly userNotificationModel: Model<UserNotification>,
    @InjectModel(NotificationLog.name)
    private readonly notificationLogModel: Model<NotificationLog>,
    @InjectModel(VotingEvent.name)
    private readonly votingEventModel: Model<VotingEventDocument>,
    @InjectModel(TenantAdminAssignment.name)
    private readonly tenantAdminAssignmentModel: Model<TenantAdminAssignmentDocument>,
    @InjectModel(RoledUser.name)
    private readonly roledUserModel: Model<RoledUserDocument>,
    private readonly padronUsersService: PadronUsersService,
    private readonly mailService: MailService,
  ) {}

  private buildPublicElectionPath(eventId: string) {
    return `/votacion/elecciones/${eventId}/publica`;
  }

  private buildPublicElectionUrl(eventId: string) {
    const base = String(process.env.PUBLIC_RESULTS_WEB_BASE_URL || '').trim();
    if (!base) {
      return '';
    }

    return `${base.replace(/\/+$/, '')}${this.buildPublicElectionPath(eventId)}`;
  }

  private formatHumanVotingStart(votingStart?: Date | null) {
    if (!votingStart) {
      return '';
    }

    return new Intl.DateTimeFormat('es', {
      day: 'numeric',
      month: 'long',
      timeZone: 'UTC',
    }).format(votingStart);
  }

  private formatReminderDeadline(deadline?: Date | null) {
    if (!deadline) {
      return '';
    }

    return new Intl.DateTimeFormat('es-BO', {
      timeZone: 'America/La_Paz',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).format(deadline);
  }

  async notifyConvocationIfEligible(event: VotingEventDocument, additionalPerUserDniData: Record<string, Record<string, string>> = {}) {
    const eventId = String(event._id);
    const publicUrl = this.buildPublicElectionUrl(eventId);
    const mode = event.convocationNotifiedAt ? 'incremental' : 'initial';
    const payload = {
      type: 'convocation',
      title: 'Revision de padron disponible',
      body: `Revisa tu habilitacion para ${event.name}`,
      data: {
        type: CONVOCATION_DATA_TYPE,
        eventId,
        electionId: eventId,
        eventName: event.name,
        state: String(event.state),
        publicPath: this.buildPublicElectionPath(eventId),
        publicUrl,
        link: this.buildPublicElectionPath(eventId),
        deepLink: `myapp://event/${eventId}`,
      },
    };

    const recipients = (
      await this.padronUsersService.getPadronUsersFromEvent(event, {
        includeDisabled: false,
      })
    ).filter((recipient) => recipient.enabled !== false);
    const totalEligible = recipients.length;

    if (!recipients.length) {
      return {
        status: 'no_pending_voters',
        mode,
        totalEligible,
        alreadyNotified: 0,
        newlyNotified: 0,
        skippedWithoutUser: 0,
        failed: 0,
      };
    }

    const notifiedStateByTopic = await this.getSentConvocationStateByTopic(eventId);
    const pendingRecipients = recipients.filter((recipient) => {
      const topic = this.buildUserTopic(recipient);
      const notifiedStates = notifiedStateByTopic.get(topic);
      return !notifiedStates?.has(this.toEligibleFlag(recipient));
    });

    if (!pendingRecipients.length) {
      return {
        status: 'no_pending_voters',
        mode,
        totalEligible,
        alreadyNotified: totalEligible,
        newlyNotified: 0,
        skippedWithoutUser: 0,
        failed: 0,
      };
    }

    const out = await this.notifyRecipients(
      payload,
      pendingRecipients,
      additionalPerUserDniData,
      eventId,
    );
    const sent = out.sent ?? 0;
    const failed = out.failed ?? 0;

    if (!event.convocationNotifiedAt && sent > 0) {
      await this.votingEventModel.updateOne(
        { _id: event._id },
        { $set: { convocationNotifiedAt: new Date() } },
      );
    }

    return {
      status: sent > 0 ? (failed > 0 ? 'partial_success' : 'success') : 'failed',
      mode,
      totalEligible,
      alreadyNotified: totalEligible - pendingRecipients.length,
      newlyNotified: sent,
      skippedWithoutUser: 0,
      failed,
    };
  }

  async notifyResultsAvailableIfEligible(event: VotingEventDocument) {
    if (event.resultsNotifiedAt) return { sent: 0, skipped: 'already_notified' };
    const eventId = String(event._id);
    const publicUrl = this.buildPublicElectionUrl(eventId);
    const out = await this.notifyToCurrentPadron(event, {
      type: 'results_available',
      title: 'Resultados disponibles',
      body: `Consulta los resultados de ${event.name}`,
      data: {
        type: 'INSTITUTIONAL_RESULTS_AVAILABLE',
        eventId,
        eventName: event.name,
        votingStart: event.votingStart?.toISOString?.() ?? '',
        votingEnd: event.votingEnd?.toISOString?.() ?? '',
        resultsPublishAt: event.resultsPublishAt?.toISOString?.() ?? '',
        bannerTitle: 'Resultados publicados',
        bannerSubtitle: 'Consulta el resumen y el detalle completo',
        publicPath: this.buildPublicElectionPath(eventId),
        publicUrl,
        link: this.buildPublicElectionPath(eventId),
      },
    });

    await this.votingEventModel.updateOne(
      { _id: event._id },
      { $set: { resultsNotifiedAt: new Date() } },
    );

    return out;
  }

  async notifyOfficialPublicationConfirmed(event: VotingEventDocument) {
    const eventId = String(event._id);
    const publicUrl = this.buildPublicElectionUrl(eventId);
    const humanVotingStart = this.formatHumanVotingStart(event.votingStart);
    const body = humanVotingStart
      ? `La elección ${event.name} iniciará el ${humanVotingStart}.`
      : `La elección ${event.name} fue publicada oficialmente.`;

    return this.notifyToCurrentPadron(event, {
      type: 'official_publication_confirmed',
      title: 'La elección fue publicada oficialmente',
      body,
      data: {
        type: 'INSTITUTIONAL_OFFICIAL_PUBLICATION_CONFIRMED',
        eventId,
        eventName: event.name,
        votingStart: event.votingStart?.toISOString?.() ?? '',
        votingEnd: event.votingEnd?.toISOString?.() ?? '',
        resultsPublishAt: event.resultsPublishAt?.toISOString?.() ?? '',
        bannerTitle: 'Elección publicada oficialmente',
        bannerSubtitle: body,
        publicPath: this.buildPublicElectionPath(eventId),
        publicUrl,
        link: this.buildPublicElectionPath(eventId),
        deepLink: `myapp://event/${eventId}`,
      },
    });
  }

  async notifyNewsToCurrentPadron(
    event: VotingEventDocument,
    payload: {
      title: string;
      body: string;
      imageUrl?: string;
      link?: string;
    },
  ) {
    return this.notifyToCurrentPadron(event, {
      type: 'news',
      title: payload.title,
      body: payload.body,
      data: {
        type: 'INSTITUTIONAL_NEWS',
        eventId: String(event._id),
        ...(payload.imageUrl ? { imageUrl: payload.imageUrl } : {}),
        ...(payload.link ? { link: payload.link } : {}),
      },
    });
  }

  async notifyScheduleUpdatedToCurrentPadron(event: VotingEventDocument) {
    const eventId = String(event._id);
    const publicUrl = this.buildPublicElectionUrl(eventId);

    return this.notifyToCurrentPadron(event, {
      type: 'schedule_updated',
      title: 'Horario actualizado',
      body: `Se actualizó el horario de ${event.name}`,
      data: {
        type: 'INSTITUTIONAL_SCHEDULE_UPDATED',
        eventId,
        eventName: event.name,
        votingStart: event.votingStart?.toISOString?.() ?? '',
        votingEnd: event.votingEnd?.toISOString?.() ?? '',
        resultsPublishAt: event.resultsPublishAt?.toISOString?.() ?? '',
        bannerTitle: 'Horario actualizado',
        bannerSubtitle: 'Revisa las nuevas fechas de la votación',
        publicPath: this.buildPublicElectionPath(eventId),
        publicUrl,
        deepLink: `myapp://event/${eventId}`,
      },
    });
  }

  async notifyPadronAvailabilityEnabledForUser(
    event: VotingEventDocument,
    carnet: string,
    reason: 'ADDED_ENABLED' | 'ENABLED_DURING_VOTING',
  ) {
    const eventId = String(event._id);
    const publicUrl = this.buildPublicElectionUrl(eventId);

    return this.notifyUsersByCarnet(event, [carnet], {
      type: 'padron_enabled_for_voting',
      title: 'Ya puedes votar',
      body: `Tu habilitación para ${event.name} ya está activa`,
      data: {
        type: 'INSTITUTIONAL_VOTING_ENABLED',
        eventId,
        eventName: event.name,
        reason,
        bannerTitle: 'Habilitación actualizada',
        bannerSubtitle: 'Tu registro fue actualizado y ya puedes emitir tu voto',
        publicPath: this.buildPublicElectionPath(eventId),
        publicUrl,
        link: this.buildPublicElectionPath(eventId),
        deepLink: `myapp://event/${eventId}`,
      },
    });
  }

  async sendOfficialPublicationReminder(event: VotingEventDocument) {
    if (event.officialPublicationReminderSentAt) {
      return { sent: 0, skipped: 'already_sent' };
    }

    const assignments = await this.tenantAdminAssignmentModel
      .find(
        {
          tenantId: event.tenantId,
          active: true,
          $or: [{ status: 'APPROVED' }, { status: { $exists: false } }],
        },
        { userId: 1 },
      )
      .lean();

    const userIds = Array.from(
      new Set(assignments.map((assignment) => String(assignment.userId)).filter(Boolean)),
    );
    if (!userIds.length) {
      return { sent: 0, skipped: 'no_recipients' };
    }

    const recipients = await this.roledUserModel
      .find(
        { _id: { $in: userIds.map((id) => new Types.ObjectId(id)) }, active: true },
        { email: 1, name: 1 },
      )
      .lean();

    const mails = Array.from(
      new Map(
        recipients
          .filter((recipient) => recipient.email)
          .map((recipient) => [String(recipient.email).trim().toLowerCase(), recipient]),
      ).values(),
    );

    if (!mails.length) {
      return { sent: 0, skipped: 'no_emails' };
    }

    const deadline = this.formatReminderDeadline(event.publishDeadline);
    await Promise.all(
      mails.map((recipient) =>
        this.mailService.sendEmail(
          recipient.email,
          `Recordatorio: Confirmar publicación oficial de ${event.name}`,
          'institutional-publication-reminder',
          {
            recipientName: recipient.name,
            eventName: event.name,
            eventId: String(event._id),
            deadline,
          },
        ),
      ),
    );

    await this.markOfficialPublicationReminderSent(event);
    return { sent: mails.length };
  }

  private async notifyToCurrentPadron(
    event: VotingEventDocument,
    payload: NotificationPayload,
    additionalPerUserDniData: Record<string, Record<string, string>> = {},
  ) {
    const recipients = await this.padronUsersService.getPadronUsersFromEvent(event, {
      includeDisabled: true,
    });

    return this.notifyRecipients(payload, recipients, additionalPerUserDniData, String(event._id));
  }

  private async notifyUsersByCarnet(
    event: VotingEventDocument,
    carnets: string[],
    payload: NotificationPayload,
  ) {
    const recipients = await this.padronUsersService.getUsersByCarnets(carnets);
    return this.notifyRecipients(payload, recipients, {}, String(event._id));
  }

  private async notifyRecipients(
    payload: NotificationPayload,
    recipients: NotificationRecipient[],
    additionalPerUserDniData: Record<string, Record<string, string>> = {},
    eventIdForLog?: string,
  ) {

    if (!recipients.length) {
      return { sent: 0, skipped: 'no_linked_users' };
    }

    const inboxBatch = recipients.map((u) => ({
      userId: u._id as Types.ObjectId,
      dni: u.dni,
      topic: this.buildUserTopic(u),
      title: payload.title,
      body: payload.body,
      data: {
        ...payload.data,
        eligible: this.toEligibleFlag(u),
        carnetNorm: u.dni,
        dni: u.dni,
        userId: String(u._id),
        ...(additionalPerUserDniData[u.dni] || {}),
      },
      status: 'NEW' as const,
    }));
    await this.userNotificationModel.insertMany(inboxBatch, { ordered: false });

    const deliveryResults = await Promise.all(
      recipients.map(async (u) => {
        const topic = this.buildUserTopic(u);
        const data = {
          ...payload.data,
          eligible: this.toEligibleFlag(u),
          carnetNorm: u.dni,
          dni: u.dni,
          userId: String(u._id),
          ...(additionalPerUserDniData[u.dni] || {}),
        };

        try {
          const messageId = await this.fb.messaging().send({
            topic,
            notification: {
              title: payload.title,
              body: payload.body,
            },
            data,
            android: { priority: 'high' },
            apns: { headers: { 'apns-priority': '10' } },
          });

          return {
            topic,
            data,
            dni: u.dni,
            userId: String(u._id),
            status: 'SENT' as const,
            messageId,
          };
        } catch (error: any) {
          console.error('[InstitutionalVotingNotifications] Push delivery failed', {
            eventId: eventIdForLog ?? null,
            userId: String(u._id),
            dni: u.dni,
            topic,
            error: error?.message || String(error),
          });

          return {
            topic,
            data,
            dni: u.dni,
            userId: String(u._id),
            status: 'FAILED' as const,
            error: error?.message || String(error),
          };
        }
      }),
    );

    await this.notificationLogModel.insertMany(
      deliveryResults.map((item) => ({
        type: 'generic',
        topic: item.topic,
        title: payload.title,
        body: payload.body,
        data: item.data,
        status: item.status,
        ...('messageId' in item && item.messageId ? { messageId: item.messageId } : {}),
        ...('error' in item && item.error ? { error: item.error } : {}),
      })),
      { ordered: false },
    );

    const sent = deliveryResults.filter((item) => item.status === 'SENT').length;
    const failed = deliveryResults.length - sent;

 
    return { sent, failed };
  }

  private buildUserTopic(recipient: Pick<NotificationRecipient, '_id'>) {
    return `user_${String(recipient._id)}`;
  }

  private toEligibleFlag(recipient: Pick<NotificationRecipient, 'enabled'>) {
    return recipient.enabled ? 'true' : 'false';
  }

  private async getSentConvocationStateByTopic(eventId: string) {
    const rows = await this.notificationLogModel
      .find(
        {
          type: 'generic',
          status: 'SENT',
          'data.eventId': eventId,
          'data.type': CONVOCATION_DATA_TYPE,
        },
        { topic: 1, data: 1 },
      )
      .lean();

    const out = new Map<string, Set<string>>();
    for (const row of rows) {
      const topic = String(row?.topic ?? '').trim();
      if (!topic) {
        continue;
      }

      const eligible = String(row?.data?.eligible ?? 'true');
      if (!out.has(topic)) {
        out.set(topic, new Set<string>());
      }
      out.get(topic)!.add(eligible);
    }

    return out;
  }

  private async markOfficialPublicationReminderSent(event: VotingEventDocument) {
    const sentAt = new Date();
    event.officialPublicationReminderSentAt = sentAt;
    await event.save();
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { createHash } from 'crypto';
import { Model, Types } from 'mongoose';
import { AddCurrentPadronVoterDto } from '../../dto/padron-current-voter.dto';
import {
  BulkDeletePadronStagingEntriesDto,
  CreatePadronStagingEntryDto,
  UpdatePadronStagingEntryDto,
} from '../../dto/padron-staging-entry.dto';
import { normalizeCarnet } from '../../utils/carnet-normalizer';
import {
  ComparisonReport,
  ComparisonReportDocument,
} from '../../schemas/comparison-report.schema';
import {
  PadronImportJob,
  PadronImportJobDocument,
  PadronImportError,
} from '../../schemas/padron-import-job.schema';
import {
  PadronStagingEntry,
  PadronStagingEntryDocument,
} from '../../schemas/padron-staging-entry.schema';
import {
  PadronCertificate,
  PadronCertificateDocument,
  PadronCertificateGenerationMode,
} from '../../schemas/padron-certificate.schema';
import { PadronEntry, PadronEntryDocument } from '../../schemas/padron-entry.schema';
import {
  PadronVersion,
  PadronVersionDocument,
} from '../../schemas/padron-version.schema';
import { PadronCertificatePdfService } from '../core/padron-certificate-pdf.service';
import { InstitutionalVotingAccessService } from '../core/institutional-voting-access.service';
import {
  PadronPdfParserService,
  ParsedPadronRow,
} from '../core/padron-pdf-parser.service';
import { PadronGeminiImportService } from '../core/padron-gemini-import.service';
import { InstitutionalVotingNotificationsService } from '../notifications/institutional-voting-notifications.service';
import { IssuerService } from '../core/issuer.service';
import { EnabledSession, EnabledSessionDocument } from '../../schemas/enabled-session.shcema';
import { VoteWritterService } from '../core/vote-writter.service';

const ENABLED_HEADER = 'habilitado';

type NormalizedImportEntry = {
  ciNorm: string;
  enabled: boolean;
  sourceRow?: number | null;
};

type PadronStagingMutationOptions = {
  deferMaterialization?: boolean;
};

@Injectable()
export class PadronService {
  private readonly materializationLocks = new Map<string, Promise<void>>();

  constructor(
    @InjectModel(PadronVersion.name)
    private readonly padronVersionModel: Model<PadronVersionDocument>,
    @InjectModel(PadronEntry.name)
    private readonly padronEntryModel: Model<PadronEntryDocument>,
    @InjectModel(ComparisonReport.name)
    private readonly comparisonReportModel: Model<ComparisonReportDocument>,
    @InjectModel(PadronImportJob.name)
    private readonly padronImportJobModel: Model<PadronImportJobDocument>,
    @InjectModel(PadronStagingEntry.name)
    private readonly padronStagingEntryModel: Model<PadronStagingEntryDocument>,
    @InjectModel(PadronCertificate.name)
    private readonly padronCertificateModel: Model<PadronCertificateDocument>,
    @InjectModel(EnabledSession.name)
    private readonly enabledSessionModel: Model<EnabledSessionDocument>,
    private readonly accessService: InstitutionalVotingAccessService,
    private readonly padronCertificatePdfService: PadronCertificatePdfService,
    private readonly padronPdfParserService: PadronPdfParserService,
    private readonly padronGeminiImportService: PadronGeminiImportService,
    private readonly notificationsService: InstitutionalVotingNotificationsService,
    private readonly issuerService: IssuerService,
    private readonly voteWritterService: VoteWritterService,
  ) {}

  private async withMaterializationLock<T>(
    eventId: string,
    task: () => Promise<T>,
  ): Promise<T> {
    const previous = this.materializationLocks.get(eventId) ?? Promise.resolve();
    let release: () => void = () => undefined;
    const current = new Promise<void>((resolve) => {
      release = resolve;
    });
    const chained = previous.catch(() => undefined).then(() => current);

    this.materializationLocks.set(eventId, chained);
    await previous.catch(() => undefined);

    try {
      return await task();
    } finally {
      release();
      if (this.materializationLocks.get(eventId) === chained) {
        this.materializationLocks.delete(eventId);
      }
    }
  }

  async uploadPadronFile(eventId: string, file: any, requester: any) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);
    await this.assertStructuralEditableState(event, 'subir el padrón');
    this.padronPdfParserService.validateSourceFile(file);

    if (!requester?.sub) {
      throw new ForbiddenException('Usuario no identificado');
    }

    const sourceType = this.padronPdfParserService.getSourceType(file);

    await this.padronImportJobModel.updateMany(
      { eventId: event._id, isActiveDraft: true },
      { $set: { isActiveDraft: false } },
    );

    const sha256 = createHash('sha256').update(file.buffer).digest('hex');
    const importJob = await this.padronImportJobModel.create({
      eventId: event._id,
      tenantId: event.tenantId,
      createdBy: new Types.ObjectId(requester.sub),
      sourceType,
      status: 'PROCESSING',
      isActiveDraft: true,
      originalFileName: file.originalname,
      originalFileMimeType: file.mimetype,
      originalFileSize: file.size,
      originalFileSha256: sha256,
      originalFileContentBase64: file.buffer.toString('base64'),
      summary: {
        parsedCount: 0,
        validCount: 0,
        duplicateCount: 0,
        invalidCount: 0,
        stagingCount: 0,
        enabledCount: 0,
        disabledCount: 0,
        missingIdentityCount: 0,
      },
    });

    try {
      const parserResult = await this.padronPdfParserService.parseDocument({
        buffer: file.buffer,
        originalname: file.originalname,
        mimetype: file.mimetype,
      });

      const normalized = this.normalizeImportedRows(parserResult.rows);
      const mergedErrors: PadronImportError[] = [
        ...parserResult.errors.map((error) => ({
          code: error.code,
          message: error.message,
          rowIndex: error.rowIndex ?? null,
          rawValue: error.rawValue ?? null,
        })),
        ...normalized.errors,
      ];

      if (normalized.entries.length) {
        const importJobId = this.toObjectId(importJob._id);
        const eventObjectId = this.toObjectId(event._id);
        const tenantObjectId = this.toObjectId(event.tenantId);
        await this.padronStagingEntryModel.insertMany(
          normalized.entries.map((entry) => ({
            importJobId,
            eventId: eventObjectId,
            tenantId: tenantObjectId,
            ciNorm: entry.ciNorm,
            enabled: entry.enabled,
            sourceKind: 'PARSED',
            sourceRow: entry.sourceRow ?? null,
            createdBy: new Types.ObjectId(requester.sub),
            lastEditedBy: new Types.ObjectId(requester.sub),
          })),
          { ordered: false },
        );
      }

      await this.padronImportJobModel.updateOne(
        { _id: importJob._id },
        {
          $set: {
            status: this.resolveImportJobStatus(normalized.entries.length, mergedErrors.length),
            parserProvider: parserResult.provider,
            parserModel: parserResult.model,
            parserUsedFallback: parserResult.usedFallback,
            processedAt: new Date(),
            importErrors: mergedErrors,
            summary: {
              parsedCount: parserResult.rows.length,
              validCount: normalized.entries.length,
              duplicateCount: normalized.duplicateCount,
              invalidCount: normalized.invalidCount,
              stagingCount: normalized.entries.length,
              enabledCount: normalized.entries.filter((entry) => entry.enabled).length,
              disabledCount: normalized.entries.filter((entry) => !entry.enabled).length,
              missingIdentityCount: 0,
            },
          },
        },
      );

      await this.refreshImportJobSummary(importJob._id);
    } catch (error: any) {
      await this.padronImportJobModel.updateOne(
        { _id: importJob._id },
        {
          $set: {
            status: 'FAILED',
            parserProvider: 'local-fallback',
            parserUsedFallback: true,
            processedAt: new Date(),
            importErrors: [
              {
                code: 'PARSER_ERROR',
                message: String(error?.message ?? error ?? 'Error procesando PDF'),
              },
            ],
          },
        },
      );
    }

    return this.getPadronImport(eventId, String(importJob._id), requester);
  }

  async uploadPadronPdf(eventId: string, file: any, requester: any) {
    return this.uploadPadronFile(eventId, file, requester);
  }

  async analyzePadronWithGemini(eventId: string, file: any, requester: any) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);
    await this.assertStructuralEditableState(event, 'analizar el padrón');
    this.padronPdfParserService.validateSourceFile(file);

    if (!requester?.sub) {
      throw new ForbiddenException('Usuario no identificado');
    }

    return this.padronGeminiImportService.analyzeDocument(file);
  }

  async getPadronImport(eventId: string, importJobId: string, requester: any) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    if (!Types.ObjectId.isValid(importJobId)) {
      throw new BadRequestException('importJobId invalido');
    }

    const importJob = await this.padronImportJobModel
      .findOne({
        _id: new Types.ObjectId(importJobId),
        eventId: event._id,
      })
      .lean();

    if (!importJob) {
      throw new NotFoundException('Importación de padrón no encontrada');
    }

    const stagingCount = await this.padronStagingEntryModel.countDocuments({
      importJobId: importJob._id,
    });

    return this.mapImportJob(importJob, stagingCount);
  }

  async listPadronStaging(eventId: string, requester: any, page = 1, limit = 50) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    const safePage = Math.max(1, Number(page) || 1);
    const safeLimit = Math.min(500, Math.max(1, Number(limit) || 50));
    const skip = (safePage - 1) * safeLimit;

    const importJob = await this.getOrCreateEditableDraftFromCurrentVersion(event, requester);
    if (!importJob) {
      return {
        importJob: null,
        data: [],
        page: safePage,
        limit: safeLimit,
        total: 0,
        totalPages: 0,
        editingRules: this.buildPadronEditingRules(event),
      };
    }

    const [rows, total] = await Promise.all([
      this.padronStagingEntryModel
        .find({ importJobId: importJob._id })
        .sort({ ciNorm: 1, _id: 1 })
        .skip(skip)
        .limit(safeLimit)
        .lean(),
      this.padronStagingEntryModel.countDocuments({ importJobId: importJob._id }),
    ]);

    const data = rows.map((row) => this.mapStagingEntry(row));
    const dids = await this.issuerService.getDidsByDnis(data.map((entry) => entry.ci));

    return {
      importJob: this.mapImportJob(importJob, total),
      data: data.map((entry) => ({
        ...entry,
        hasIdentity: dids.some((did) => did.dni === entry.ci),
      })),
      page: safePage,
      limit: safeLimit,
      total,
      totalPages: Math.ceil(total / safeLimit),
      editingRules: this.buildPadronEditingRules(event),
    };
  }

  async addPadronStagingEntry(
    eventId: string,
    dto: CreatePadronStagingEntryDto,
    requester: any,
    options: PadronStagingMutationOptions = {},
  ) {
    const { event, importJob } = await this.getEditableActiveImportJobContext(
      eventId,
      requester,
      'agregar entradas al staging del padrón',
    );

    const ciNorm = normalizeCarnet(dto.ci);
    if (!ciNorm) {
      throw new BadRequestException('CI inválido');
    }

    const existing = await this.padronStagingEntryModel.exists({
      importJobId: importJob._id,
      ciNorm,
    });
    if (existing) {
      throw new BadRequestException('Ya existe un empadronado con ese CI en el staging');
    }

    const created = await this.padronStagingEntryModel.create({
      importJobId: this.toObjectId(importJob._id),
      eventId: this.toObjectId(event._id),
      tenantId: this.toObjectId(event.tenantId),
      ciNorm,
      enabled: dto.enabled !== false,
      sourceKind: 'MANUAL',
      createdBy: requester?.sub ? new Types.ObjectId(requester.sub) : null,
      lastEditedBy: requester?.sub ? new Types.ObjectId(requester.sub) : null,
    });

    await this.refreshImportJobSummary(importJob._id);
    if (!options.deferMaterialization) {
      await this.materializeAndNotifyConvocationUpdateIfNeeded(eventId, requester, event);
    }

    return this.mapStagingEntry(created.toObject());
  }

  async updatePadronStagingEntry(
    eventId: string,
    entryId: string,
    dto: UpdatePadronStagingEntryDto,
    requester: any,
    options: PadronStagingMutationOptions = {},
  ) {
    const { event, importJob } = await this.getEditableActiveImportJobContext(
      eventId,
      requester,
      'editar entradas del staging del padrón',
    );

    if (!Types.ObjectId.isValid(entryId)) {
      throw new BadRequestException('entryId invalido');
    }

    const entry = await this.padronStagingEntryModel.findOne({
      _id: new Types.ObjectId(entryId),
      importJobId: importJob._id,
    });

    if (!entry) {
      throw new NotFoundException('Entrada de staging no encontrada');
    }

    if (dto.ci !== undefined) {
      const ciNorm = normalizeCarnet(dto.ci);
      if (!ciNorm) {
        throw new BadRequestException('CI inválido');
      }

      const duplicate = await this.padronStagingEntryModel.exists({
        importJobId: importJob._id,
        ciNorm,
        _id: { $ne: entry._id },
      });
      if (duplicate) {
        throw new BadRequestException('Ya existe un empadronado con ese CI en el staging');
      }

      entry.ciNorm = ciNorm;
    }

    if (dto.enabled !== undefined) {
      entry.enabled = dto.enabled;
    }

    if (requester?.sub) {
      entry.lastEditedBy = new Types.ObjectId(requester.sub);
    }

    await entry.save();
    await this.refreshImportJobSummary(importJob._id);
    if (!options.deferMaterialization) {
      await this.materializeAndNotifyConvocationUpdateIfNeeded(eventId, requester, event);
    }

    return this.mapStagingEntry(entry.toObject());
  }

  async deletePadronStagingEntry(
    eventId: string,
    entryId: string,
    requester: any,
    options: PadronStagingMutationOptions = {},
  ) {
    const { event, importJob } = await this.getEditableActiveImportJobContext(
      eventId,
      requester,
      'eliminar entradas del staging del padrón',
    );

    if (!Types.ObjectId.isValid(entryId)) {
      throw new BadRequestException('entryId invalido');
    }

    const deleted = await this.padronStagingEntryModel.findOneAndDelete({
      _id: new Types.ObjectId(entryId),
      importJobId: importJob._id,
    });

    if (!deleted) {
      throw new NotFoundException('Entrada de staging no encontrada');
    }

    await this.refreshImportJobSummary(importJob._id);
    if (!options.deferMaterialization) {
      await this.materializeAndNotifyConvocationUpdateIfNeeded(eventId, requester, event);
    }

    return {
      id: String(deleted._id),
      deleted: true,
    };
  }

  async bulkDeletePadronStagingEntries(
    eventId: string,
    dto: BulkDeletePadronStagingEntriesDto,
    requester: any,
  ) {
    const { event, importJob } = await this.getEditableActiveImportJobContext(
      eventId,
      requester,
      'eliminar registros del padrón',
    );

    const entryIds = Array.from(
      new Set(
        (dto.entryIds ?? [])
          .map((entryId) => String(entryId ?? '').trim())
          .filter((entryId) => entryId.length > 0),
      ),
    );

    if (!entryIds.length) {
      throw new BadRequestException('Selecciona al menos un registro para eliminar.');
    }

    if (entryIds.some((entryId) => !Types.ObjectId.isValid(entryId))) {
      throw new BadRequestException('No se pudieron validar todos los registros seleccionados.');
    }

    const objectIds = entryIds.map((entryId) => new Types.ObjectId(entryId));
    const [matchedEntries, totalBeforeDelete] = await Promise.all([
      this.padronStagingEntryModel
        .find(
          {
            _id: { $in: objectIds },
            importJobId: importJob._id,
          },
          { _id: 1 },
        )
        .lean(),
      this.padronStagingEntryModel.countDocuments({ importJobId: importJob._id }),
    ]);

    if (matchedEntries.length !== objectIds.length) {
      throw new BadRequestException('No se pudieron validar todos los registros seleccionados.');
    }

    if (totalBeforeDelete - objectIds.length <= 0) {
      throw new BadRequestException('No se puede eliminar todos los registros del padrón.');
    }

    const deleteResult = await this.padronStagingEntryModel.deleteMany({
      _id: { $in: objectIds },
      importJobId: importJob._id,
    });
    const deletedCount = Number(deleteResult?.deletedCount ?? 0);

    if (deletedCount !== objectIds.length) {
      throw new BadRequestException('No se pudieron eliminar todos los registros seleccionados.');
    }

    await this.refreshImportJobSummary(importJob._id);

    let materialized = false;
    if (event?.convocationNotifiedAt) {
      const synchronized = await this.materializeActiveDraftVersion(eventId, requester, {
        comparisonStatus: 'OK',
        deactivateDraft: false,
        markConfirmed: false,
        certificateMode: 'ON_CONFIRMATION',
      });
      materialized = Boolean(synchronized);
    }

    return {
      requestedCount: entryIds.length,
      deletedCount,
      materialized,
      convocationNotification: {
        newlyNotified: 0,
      },
    };
  }

  async removeUnregisteredStagingEntriesForOfficialPublication(
    eventId: string,
    requester: any,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);
    await this.assertStructuralEditableState(
      event,
      'preparar el padrón para la publicación oficial',
    );

    const importJob = await this.getActiveImportJob(event._id);
    if (!importJob) {
      return {
        removedCount: 0,
        remainingCount: 0,
      };
    }

    const entries = await this.padronStagingEntryModel
      .find({ importJobId: importJob._id }, { _id: 1, ciNorm: 1 })
      .lean();

    if (!entries.length) {
      throw new BadRequestException('No hay registros del padrón para publicar.');
    }

    const dids = await this.issuerService.getDidsByDnis(
      entries
        .map((entry) => String(entry.ciNorm ?? '').trim())
        .filter((ci) => ci.length > 0),
    );
    const registeredDniSet = new Set(
      dids
        .map((did) => String(did?.dni ?? '').trim())
        .filter((dni) => dni.length > 0),
    );
    const unregisteredEntries = entries.filter(
      (entry) => !registeredDniSet.has(String(entry.ciNorm ?? '').trim()),
    );

    if (!unregisteredEntries.length) {
      await this.refreshImportJobSummary(importJob._id);
      return {
        removedCount: 0,
        remainingCount: entries.length,
      };
    }

    if (entries.length - unregisteredEntries.length <= 0) {
      throw new BadRequestException(
        'No se puede publicar oficialmente porque todos los registros del padrón están no registrados. Debe quedar al menos un registro registrado en el padrón.',
      );
    }

    const objectIds = unregisteredEntries.map((entry) => entry._id);
    const deleteResult = await this.padronStagingEntryModel.deleteMany({
      _id: { $in: objectIds },
      importJobId: importJob._id,
    });
    const removedCount = Number(deleteResult?.deletedCount ?? 0);

    if (removedCount !== objectIds.length) {
      throw new BadRequestException(
        'No se pudieron eliminar los registros no registrados antes de publicar.',
      );
    }

    await this.refreshImportJobSummary(importJob._id);

    return {
      removedCount,
      remainingCount: entries.length - removedCount,
    };
  }

  async addCurrentPadronVoter(
    eventId: string,
    dto: AddCurrentPadronVoterDto,
    requester: any,
  ) {
    await this.getEventForVotingPadronChange(
      eventId,
      requester,
      'agregar nuevos habilitados al padrón en modo limitado',
    );

    void dto;

    throw new BadRequestException(
      'Después de la publicación oficial no se permite agregar nuevos votantes al padrón vigente',
    );
  }

  async enableCurrentPadronVoter(eventId: string, voterId: string, requester: any) {
    const event = await this.getEventForVotingPadronChange(
      eventId,
      requester,
      'habilitar deshabilitados del padrón en modo limitado',
    );

    if (!this.accessService.canEnableExistingPadronEntriesPostPublication(event)) {
      throw new BadRequestException(
        'La habilitación manual desde la tabla está desactivada para esta votación',
      );
    }

    if (!Types.ObjectId.isValid(voterId)) {
      throw new BadRequestException('voterId invalido');
    }

    const currentVersion = await this.resolveCurrentPadronVersionDoc(event._id as Types.ObjectId);
    const voter = await this.padronEntryModel.findOne({
      _id: new Types.ObjectId(voterId),
      padronVersionId: currentVersion._id,
    });

    if (!voter) {
      throw new NotFoundException('Votante no encontrado en el padrón vigente');
    }

    if (voter.enabled === true) {
      return {
        id: String(voter._id),
        padronVersionId: String(currentVersion._id),
        carnetNorm: voter.carnetNorm,
        enabled: true,
        mode: 'VOTING_LIMITED',
      };
    }

    const dids = await this.issuerService.getDidsByDnis([voter.carnetNorm]);
    if (dids.length !== 1 || dids[0].dni !== voter.carnetNorm) {
      throw new NotFoundException('No se encontró al usuario registrado en el servicio de identidad');
    }

    const nullifiers = await this.voteWritterService.addNewVoters(event._id.toString(), 1);

    const credentialData = await this.issuerService.issueCredential(
      dids,
      event._id.toString(),
      nullifiers,
    );

    await this.enabledSessionModel.insertOne({
      eventId: event._id,
      dni: voter.carnetNorm,
      sessionToken: credentialData[voter.carnetNorm].credentialData,
    });

    voter.enabled = true;
    await voter.save();
    await this.invalidateCurrentPadronCertificate(currentVersion._id);
    await this.notificationsService.notifyPadronAvailabilityEnabledForUser(
      event,
      voter.carnetNorm,
      'ENABLED_DURING_VOTING',
    );

    return {
      id: String(voter._id),
      padronVersionId: String(currentVersion._id),
      carnetNorm: voter.carnetNorm,
      enabled: true,
      mode: 'VOTING_LIMITED',
    };
  }

  async confirmPadronStaging(eventId: string, requester: any) {
    const event = await this.accessService.getEventOrThrow(eventId);
    const shouldNotifyIncremental = Boolean(event?.convocationNotifiedAt);
    const comparisonStatus = shouldNotifyIncremental ? 'OK' : 'PENDING';

    const synchronized = await this.materializeActiveDraftVersion(eventId, requester, {
      comparisonStatus,
      deactivateDraft: true,
      markConfirmed: true,
      certificateMode: 'ON_CONFIRMATION',
    });

    if (!synchronized) {
      throw new NotFoundException('No existe un staging activo de padrón para este evento');
    }

    if (shouldNotifyIncremental) {
      await this.notificationsService.notifyConvocationIfEligible(synchronized.event);
    }

    return {
      importJobId: String(synchronized.importJob._id),
      padronVersionId: String(synchronized.version._id),
      state: 'CONFIRMED',
      totals: synchronized.version.totals,
      comparisonStatus,
      sourceType: synchronized.version.sourceType ?? 'PDF_IMPORT',
      certificate: this.mapCertificateMetadata(synchronized.certificate),
    };
  }

  private async materializeAndNotifyConvocationUpdateIfNeeded(
    eventId: string,
    requester: any,
    event: any,
  ) {
    if (!event?.convocationNotifiedAt) {
      return;
    }

    const synchronized = await this.materializeActiveDraftVersion(eventId, requester, {
      comparisonStatus: 'OK',
      deactivateDraft: false,
      markConfirmed: false,
      certificateMode: 'ON_CONFIRMATION',
    });

    if (!synchronized) {
      return;
    }

    await this.notificationsService.notifyConvocationIfEligible(synchronized.event);
  }

  async materializeActiveDraftVersion(
    eventId: string,
    requester: any,
    options: {
      comparisonStatus?: 'PENDING' | 'OK' | 'FAILED';
      deactivateDraft?: boolean;
      markConfirmed?: boolean;
      certificateMode?: PadronCertificateGenerationMode;
    } = {},
  ) {
    return this.withMaterializationLock(eventId, () =>
      this.materializeActiveDraftVersionUnlocked(eventId, requester, options),
    );
  }

  private async materializeActiveDraftVersionUnlocked(
    eventId: string,
    requester: any,
    options: {
      comparisonStatus?: 'PENDING' | 'OK' | 'FAILED';
      deactivateDraft?: boolean;
      markConfirmed?: boolean;
      certificateMode?: PadronCertificateGenerationMode;
    } = {},
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    const importJob = await this.getActiveImportJob(event._id);
    if (!importJob) {
      return null;
    }

    if (importJob.status === 'PROCESSING') {
      throw new BadRequestException('El padrón todavía se está procesando');
    }

    if (importJob.status === 'FAILED') {
      throw new BadRequestException('El staging activo del padrón tiene errores y no puede materializarse');
    }

    if (!requester?.sub) {
      throw new ForbiddenException('Usuario no identificado');
    }

    await this.refreshImportJobSummary(importJob._id);

    const entries = await this.padronStagingEntryModel
      .find({ importJobId: importJob._id })
      .sort({ ciNorm: 1, _id: 1 })
      .lean();

    if (!entries.length) {
      throw new BadRequestException('No se puede materializar un staging vacío');
    }

    const digest = createHash('sha256')
      .update(entries.map((entry) => `${entry.ciNorm},${entry.enabled ? '1' : '0'}`).join('\n'))
      .digest('hex');
    const currentVersionBeforeMaterialize = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();

    const version = await this.createCurrentPadronVersion({
      eventId: this.toObjectId(event._id),
      tenantId: this.toObjectId(event.tenantId),
      createdBy: new Types.ObjectId(requester.sub),
      fileDigest: digest,
      entries: entries.map((entry) => ({
        ciNorm: entry.ciNorm,
        enabled: entry.enabled !== false,
      })),
      totals: {
        validCount: entries.length,
        duplicateCount: 0,
        invalidCount: 0,
      },
      comparisonStatus: options.comparisonStatus ?? 'OK',
      sourceType:
        importJob.sourceType === 'IMAGE'
          ? 'IMAGE_IMPORT'
          : importJob.sourceType === 'SYSTEM'
            ? currentVersionBeforeMaterialize?.sourceType ?? 'PDF_IMPORT'
            : 'PDF_IMPORT',
      importJobId: this.toObjectId(importJob._id),
      sourceFileName: importJob.originalFileName,
      sourceFileMimeType: importJob.originalFileMimeType,
      sourceFileSha256: importJob.originalFileSha256,
      parserProvider: importJob.parserProvider,
      parserModel: importJob.parserModel ?? null,
    });

    const importJobSet: Record<string, unknown> = {
      confirmedPadronVersionId: this.toObjectId(version._id),
    };

    if (options.markConfirmed) {
      importJobSet.status = 'CONFIRMED';
      importJobSet.confirmedAt = new Date();
    }

    if (options.deactivateDraft) {
      importJobSet.isActiveDraft = false;
    }

    await this.padronImportJobModel.updateOne(
      { _id: importJob._id },
      {
        $set: importJobSet,
      },
    );

    const certificate = await this.ensurePadronCertificateForVersion(
      event,
      version,
      requester,
      options.certificateMode ?? 'ON_CONFIRMATION',
    );

    return { event, importJob, version, certificate };
  }

  async getPadronSummary(eventId: string, requester: any) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    const currentVersion = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();
    const activeImportJob = await this.getOrCreateEditableDraftFromCurrentVersion(event, requester);

    const currentComparison = currentVersion
      ? await this.comparisonReportModel
          .findOne({ padronVersionId: currentVersion._id }, { status: 1 })
          .lean()
      : null;

    const currentCertificate = currentVersion
      ? await this.padronCertificateModel
          .findOne({ padronVersionId: currentVersion._id })
          .lean()
      : null;

    const stagingCount = activeImportJob
      ? await this.padronStagingEntryModel.countDocuments({ importJobId: activeImportJob._id })
      : 0;

    return {
      eventId: String(event._id),
      eventState: event.state,
      editingRules: this.buildPadronEditingRules(event),
      allowPostPublicationPadronEnable:
        event.allowPostPublicationPadronEnable !== false,
      currentVersion: currentVersion
        ? {
            padronVersionId: String(currentVersion._id),
            createdAt: currentVersion.createdAt ?? null,
            createdBy: String(currentVersion.createdBy),
            totals: currentVersion.totals,
            sourceType: currentVersion.sourceType ?? 'CSV_LEGACY',
            importJobId: currentVersion.importJobId ? String(currentVersion.importJobId) : null,
            comparisonStatus: currentComparison?.status ?? 'PENDING',
            certificate: currentCertificate
              ? this.mapCertificateMetadata(currentCertificate)
              : {
                  exists: false,
                  materializable: true,
                },
          }
        : null,
      activeDraft: activeImportJob
        ? this.mapImportJob(activeImportJob, stagingCount)
        : null,
    };
  }

  async importPadron(eventId: string, csvContent: string, requester: any) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);
    await this.assertStructuralEditableState(event, 'importar el padrón');

    if (!requester?.sub) {
      throw new ForbiddenException('Usuario no identificado');
    }

    const lines = String(csvContent)
      .replace(/\r/g, '')
      .split('\n')
      .map((line) => line.trim());

    if (lines.length === 0) {
      throw new BadRequestException('CSV vacio');
    }

    const headerColumns = lines[0].split(',').map((cell) => cell.trim().toLowerCase());
    const hasHeader = ['carnet', 'dni'].includes(headerColumns[0]);
    const hasEnabledColumn = headerColumns[1] === ENABLED_HEADER;
    const rows = hasHeader ? lines.slice(1) : lines;

    const seen = new Set<string>();
    const validEntries: { ciNorm: string; enabled: boolean }[] = [];
    let duplicates = 0;
    let invalid = 0;

    for (const raw of rows) {
      if (!raw) continue;
      const [rawCarnet = '', rawEnabled = ''] = raw.split(',');
      const normalized = normalizeCarnet(rawCarnet);
      if (!normalized) {
        invalid++;
        continue;
      }

      const enabled = this.parseEnabledValue(rawEnabled, hasEnabledColumn);
      if (enabled === null) {
        invalid++;
        continue;
      }

      if (seen.has(normalized)) {
        duplicates++;
        continue;
      }

      seen.add(normalized);
      validEntries.push({
        ciNorm: normalized,
        enabled,
      });
    }

    const digest = createHash('sha256').update(csvContent).digest('hex');
    const comparisonStatus =
      validEntries.length > 0 && duplicates === 0 && invalid === 0 ? 'OK' : 'PENDING';

    const version = await this.createCurrentPadronVersion({
      eventId: this.toObjectId(event._id),
      tenantId: this.toObjectId(event.tenantId),
      createdBy: new Types.ObjectId(requester.sub),
      fileDigest: digest,
      entries: validEntries,
      totals: {
        validCount: validEntries.length,
        duplicateCount: duplicates,
        invalidCount: invalid,
      },
      comparisonStatus,
      sourceType: 'CSV_LEGACY',
      sourceFileName: 'legacy-upload.csv',
      sourceFileMimeType: 'text/csv',
      sourceFileSha256: digest,
      parserProvider: 'legacy-csv',
      parserModel: null,
    });

    const certificate = await this.ensurePadronCertificateForVersion(
      event,
      version,
      requester,
      'ON_CONFIRMATION',
    );

    return {
      padronVersionId: String(version._id),
      fileDigest: version.fileDigest,
      createdAt: version.createdAt,
      createdBy: String(version.createdBy),
      tenantId: String(version.tenantId),
      totals: version.totals,
      isCurrent: version.isCurrent,
      sourceType: version.sourceType ?? 'CSV_LEGACY',
      certificate: this.mapCertificateMetadata(certificate),
    };
  }

  async getPadronCertificateMetadata(eventId: string, requester: any, padronVersionId?: string) {
    const { event, version } = await this.getCertificateVersionContext(eventId, requester, padronVersionId);

    if (!version) {
      return {
        exists: false,
        eventId: String(event._id),
        padronVersionId: null,
        materializable: false,
        reason: 'NO_CONFIRMED_PADRON_VERSION',
      };
    }

    const certificate = await this.padronCertificateModel
      .findOne({ padronVersionId: version._id })
      .lean();

    if (!certificate) {
      return {
        exists: false,
        eventId: String(event._id),
        padronVersionId: String(version._id),
        sourceType: version.sourceType ?? 'CSV_LEGACY',
        totals: version.totals,
        materializable: true,
        reason: 'PADRON_CERTIFICATE_NOT_MATERIALIZED',
      };
    }

    return this.mapCertificateMetadata(certificate);
  }

  async materializePadronCertificate(
    eventId: string,
    requester: any,
    padronVersionId?: string,
    forceRegenerate = false,
  ) {
    const { event, version } = await this.getCertificateVersionContext(eventId, requester, padronVersionId);
    if (!version) {
      throw new NotFoundException('No existe una versión confirmada de padrón para materializar constancia');
    }

    const certificate = await this.ensurePadronCertificateForVersion(
      event,
      version,
      requester,
      forceRegenerate ? 'REGENERATED' : 'ON_DEMAND',
      forceRegenerate,
    );

    return this.mapCertificateMetadata(certificate);
  }

  async downloadPadronCertificate(eventId: string, requester: any, padronVersionId?: string) {
    const { event, version } = await this.getCertificateVersionContext(eventId, requester, padronVersionId);
    if (!version) {
      throw new NotFoundException('No existe una versión confirmada de padrón para descargar constancia');
    }

    const certificate = await this.padronCertificateModel
      .findOne(
        { padronVersionId: version._id },
        {
          eventId: 1,
          tenantId: 1,
          padronVersionId: 1,
          generatedAt: 1,
          generationMode: 1,
          fileName: 1,
          mimeType: 1,
          fileSha256: 1,
          fileSize: 1,
          sourceType: 1,
          totalCount: 1,
          enabledCount: 1,
          disabledCount: 1,
          storageKind: 1,
          pdfContentBase64: 1,
        },
      )
      .lean();

    if (!certificate?.pdfContentBase64) {
      throw new NotFoundException('La constancia PDF del padrón aún no está materializada');
    }

    return {
      fileName: certificate.fileName,
      mimeType: certificate.mimeType,
      pdfBuffer: Buffer.from(certificate.pdfContentBase64, 'base64'),
      metadata: this.mapCertificateMetadata(certificate),
    };
  }

  async listPadronVersions(eventId: string, requester: any) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    const versions = await this.padronVersionModel
      .find({ eventId: new Types.ObjectId(eventId) })
      .sort({ createdAt: -1 })
      .lean();

    return {
      data: versions.map((version) => ({
        padronVersionId: String(version._id),
        fileDigest: version.fileDigest,
        createdAt: version.createdAt,
        createdBy: String(version.createdBy),
        totals: version.totals,
        isCurrent: version.isCurrent,
        sourceType: version.sourceType ?? 'CSV_LEGACY',
        importJobId: version.importJobId ? String(version.importJobId) : null,
      })),
      total: versions.length,
    };
  }

  async listCurrentPadronVoters(
    eventId: string,
    requester: any,
    page = 1,
    limit = 50,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    const safePage = Math.max(1, Number(page) || 1);
    const safeLimit = Math.min(500, Math.max(1, Number(limit) || 50));
    const skip = (safePage - 1) * safeLimit;

    const currentVersion = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();

    if (!currentVersion) {
      return {
        data: [],
        page: safePage,
        limit: safeLimit,
        total: 0,
        totalPages: 0,
        padronVersionId: null,
        editingRules: this.buildPadronEditingRules(event),
      };
    }

    const [rows, total] = await Promise.all([
      this.padronEntryModel
        .find(
          { padronVersionId: currentVersion._id },
          { _id: 1, carnetNorm: 1, enabled: 1, createdAt: 1 },
        )
        .sort({ carnetNorm: 1, _id: 1 })
        .skip(skip)
        .limit(safeLimit)
        .lean(),
      this.padronEntryModel.countDocuments({ padronVersionId: currentVersion._id }),
    ]);

    return {
      data: rows.map((row) => ({
        id: String(row._id),
        carnetNorm: row.carnetNorm,
        enabled: row.enabled !== false,
        createdAt: (row as any).createdAt ?? null,
      })),
      page: safePage,
      limit: safeLimit,
      total,
      totalPages: Math.ceil(total / safeLimit),
      padronVersionId: String(currentVersion._id),
      editingRules: this.buildPadronEditingRules(event),
    };
  }

  async getCurrentPadronSummary(
    eventId: string,
    requester: any,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    const currentVersion = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();

    if (!currentVersion) {
      return {
        total: 0,
        enabledToVote: 0,
        disabledToVote: 0,
        editingRules: this.buildPadronEditingRules(event),
      };
    }

    const [total, enabledToVote, disabledToVote] = await Promise.all([
      this.padronEntryModel.countDocuments({ padronVersionId: currentVersion._id }),
      this.padronEntryModel.countDocuments({ padronVersionId: currentVersion._id, enabled: true }),
      this.padronEntryModel.countDocuments({ padronVersionId: currentVersion._id, enabled: false }),
    ]);

    return {
      total,
      enabledToVote,
      disabledToVote,
      editingRules: this.buildPadronEditingRules(event),
    };
  }

  async downloadPadronCsv(eventId: string, requester: any, padronVersionId?: string) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);
    const eventObjectId = this.toObjectId(event._id);

    const version = await this.resolvePadronVersion(eventObjectId, padronVersionId);

    const rows = await this.padronEntryModel
      .find(
        { padronVersionId: version._id },
        { carnetNorm: 1, enabled: 1, _id: 0 },
      )
      .sort({ carnetNorm: 1 })
      .lean();

    const csvLines = [
      `carnet,${ENABLED_HEADER}`,
      ...rows.map((row) => `${row.carnetNorm},${row.enabled === false ? 'no' : 'si'}`),
    ];

    return {
      fileName: `padron-${String(version._id)}.csv`,
      csvContent: `\uFEFF${csvLines.join('\n')}`,
      padronVersionId: String(version._id),
      isCurrent: version.isCurrent === true,
    };
  }

  async downloadPadronPdf(eventId: string, requester: any, padronVersionId?: string) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    if (!this.accessService.isOfficialPublicationConfirmed(event)) {
      throw new BadRequestException(
        'El padrón en PDF solo está disponible después de la publicación oficial',
      );
    }

    const eventObjectId = this.toObjectId(event._id);
    const version = await this.resolvePadronVersion(eventObjectId, padronVersionId);

    const rows = await this.padronEntryModel
      .find(
        { padronVersionId: version._id },
        { carnetNorm: 1, enabled: 1, _id: 0 },
      )
      .sort({ carnetNorm: 1 })
      .lean();

    const totalCount = rows.length;
    const enabledCount = rows.filter((row) => row.enabled !== false).length;
    const disabledCount = totalCount - enabledCount;
    const pdfBuffer = this.padronCertificatePdfService.buildPadronListPdf({
      eventName: event.name,
      generatedAt: new Date(),
      padronVersionId: String(version._id),
      statusLabel: version.isCurrent === true ? 'Padrón vigente' : 'Versión histórica',
      totalCount,
      enabledCount,
      disabledCount,
      entries: rows.map((row) => ({
        ci: row.carnetNorm,
        enabled: row.enabled !== false,
      })),
    });

    return {
      fileName: `padron-${String(version._id)}.pdf`,
      pdfBuffer,
      padronVersionId: String(version._id),
      isCurrent: version.isCurrent === true,
    };
  }

  async checkEligibility(eventId: string, carnet: string) {
    const event = await this.accessService.getEventOrThrow(eventId);
    const carnetNorm = normalizeCarnet(carnet);

    if (!carnetNorm) {
      throw new BadRequestException('carnet invalido');
    }

    const currentVersion = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();

    if (!currentVersion) {
      return {
        status: 'NOT_ELIGIBLE',
        normalizedCarnet: carnetNorm,
        referenceVersion: null,
      };
    }

    const found = await this.padronEntryModel.findOne(
      {
        padronVersionId: currentVersion._id,
        carnetNorm,
      },
      { enabled: 1 },
    ).lean();

    return {
      status: found ? (found.enabled === false ? 'DISABLED' : 'ELIGIBLE') : 'NOT_ELIGIBLE',
      normalizedCarnet: carnetNorm,
      referenceVersion: String(currentVersion._id),
    };
  }

  async checkPublicEligibility(eventId: string, carnet: string) {
    const event = await this.accessService.getEventOrThrow(eventId);
    if (
      ['DRAFT', 'READY_FOR_REVIEW'].includes(event.state) &&
      this.accessService.hasPublicationWindowExpired(event)
    ) {
      event.state = 'PUBLICATION_EXPIRED';
      event.publicationExpiredAt = new Date();
      event.publicationConfirmed = false;
      await event.save();
    }

    if (
      ![
        'READY_FOR_REVIEW',
        'OFFICIALLY_PUBLISHED',
        'PUBLISHED',
        'CLOSED',
        'RESULTS_PUBLISHED',
      ].includes(event.state)
    ) {
      return {
        status: 'PUBLIC_CHECK_DISABLED',
        referenceVersion: null,
      };
    }
    if (!event.publicEligibilityEnabled) {
      return {
        status: 'PUBLIC_CHECK_DISABLED',
        referenceVersion: null,
      };
    }

    const carnetNorm = normalizeCarnet(carnet);

    const currentVersion = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();

    if (!currentVersion) {
      return {
        status: 'ROLL_IN_VALIDATION',
        referenceVersion: null,
      };
    }

    const reportOk = await this.comparisonReportModel.exists({
      padronVersionId: currentVersion._id,
      status: 'OK',
    });

    if (!reportOk) {
      return {
        status: 'ROLL_IN_VALIDATION',
        referenceVersion: String(currentVersion._id),
      };
    }

    const found = await this.padronEntryModel.findOne(
      {
        padronVersionId: currentVersion._id,
        carnetNorm,
      },
      { enabled: 1 },
    ).lean();

    return {
      status: found ? (found.enabled === false ? 'DISABLED' : 'ELIGIBLE') : 'NOT_ELIGIBLE',
      referenceVersion: String(currentVersion._id),
    };
  }

  async updateComparisonReportStatus(
    eventId: string,
    status: 'PENDING' | 'OK' | 'FAILED',
    requester: any,
    padronVersionId?: string,
  ) {
    this.accessService.assertGlobalAdminAccess(requester, 'aprobar o rechazar el padrón');
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.assertStructuralEditableState(event, 'actualizar la validación del padrón');
    const eventObjectId = this.toObjectId(event._id);
    const version = await this.resolvePadronVersion(eventObjectId, padronVersionId);

    await this.comparisonReportModel.updateOne(
      { padronVersionId: version._id },
      { $set: { status } },
      { upsert: true },
    );

    return { eventId, padronVersionId: String(version._id), status };
  }

  private async createCurrentPadronVersion(params: {
    eventId: Types.ObjectId;
    tenantId: Types.ObjectId;
    createdBy: Types.ObjectId;
    fileDigest: string;
    entries: { ciNorm: string; enabled: boolean }[];
    totals: {
      validCount: number;
      duplicateCount: number;
      invalidCount: number;
    };
    comparisonStatus: 'PENDING' | 'OK' | 'FAILED';
    sourceType: 'CSV_LEGACY' | 'PDF_IMPORT' | 'IMAGE_IMPORT';
    importJobId?: Types.ObjectId;
    sourceFileName?: string | null;
    sourceFileMimeType?: string | null;
    sourceFileSha256?: string | null;
    parserProvider?: string | null;
    parserModel?: string | null;
  }) {
    await this.padronVersionModel.updateMany(
      { eventId: params.eventId, isCurrent: true },
      { $set: { isCurrent: false } },
    );

    const version = await this.padronVersionModel.create({
      eventId: params.eventId,
      tenantId: params.tenantId,
      createdBy: params.createdBy,
      fileDigest: params.fileDigest,
      sourceType: params.sourceType,
      importJobId: params.importJobId ?? null,
      sourceFileName: params.sourceFileName ?? null,
      sourceFileMimeType: params.sourceFileMimeType ?? null,
      sourceFileSha256: params.sourceFileSha256 ?? null,
      parserProvider: params.parserProvider ?? null,
      parserModel: params.parserModel ?? null,
      totals: params.totals,
      isCurrent: true,
    });

    if (params.entries.length > 0) {
      await this.padronEntryModel.insertMany(
        params.entries.map((entry) => ({
          padronVersionId: version._id,
          eventId: params.eventId,
          carnetNorm: entry.ciNorm,
          enabled: entry.enabled,
        })),
        { ordered: false },
      );
    }

    await this.comparisonReportModel.updateOne(
      { padronVersionId: version._id },
      {
        $set: {
          eventId: params.eventId,
          padronVersionId: version._id,
          status: params.comparisonStatus,
        },
      },
      { upsert: true },
    );

    return version;
  }

  private normalizeImportedRows(rows: ParsedPadronRow[]) {
    const seen = new Set<string>();
    const entries: NormalizedImportEntry[] = [];
    const errors: PadronImportError[] = [];
    let duplicateCount = 0;
    let invalidCount = 0;

    for (const row of rows) {
      const ciNorm = normalizeCarnet(row.ci);
      if (!ciNorm) {
        invalidCount++;
        errors.push({
          code: 'INVALID_CI',
          message: 'No se pudo normalizar el CI',
          rowIndex: row.sourceRow ?? null,
          rawValue: row.ci,
        });
        continue;
      }

      if (seen.has(ciNorm)) {
        duplicateCount++;
        errors.push({
          code: 'DUPLICATE_CI',
          message: 'CI duplicado en el padrón importado',
          rowIndex: row.sourceRow ?? null,
          rawValue: row.ci,
        });
        continue;
      }

      seen.add(ciNorm);
      entries.push({
        ciNorm,
        enabled: row.enabled !== false,
        sourceRow: row.sourceRow ?? null,
      });
    }

    if (!entries.length) {
      errors.push({
        code: 'EMPTY_STAGING',
        message: 'El staging quedó vacío luego del procesamiento del PDF',
      });
    }

    return { entries, errors, duplicateCount, invalidCount };
  }

  private resolveImportJobStatus(validCount: number, errorCount: number) {
    if (validCount <= 0) return 'FAILED' as const;
    if (errorCount > 0) return 'PARSED_WITH_ERRORS' as const;
    return 'PARSED' as const;
  }

  private parseEnabledValue(value: string, hasEnabledColumn: boolean): boolean | null {
    if (!hasEnabledColumn) {
      return true;
    }

    const normalized = String(value ?? '').trim().toLowerCase();
    if (['1', 'true', 'si', 'sí', 'habilitado', 'activo'].includes(normalized)) {
      return true;
    }
    if (['0', 'false', 'no', 'deshabilitado', 'inhabilitado', 'inactivo'].includes(normalized)) {
      return false;
    }
    return null;
  }

  private async getEditableActiveImportJobContext(
    eventId: string,
    requester: any,
    action: string,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);
    await this.assertStructuralEditableState(event, action);

    const importJob = await this.getOrCreateEditableDraftFromCurrentVersion(event, requester);
    if (!importJob) {
      throw new NotFoundException('No existe un staging activo de padrón para este evento');
    }

    if (importJob.status === 'PROCESSING' || importJob.status === 'CONFIRMED') {
      throw new BadRequestException('El staging activo no admite edición en su estado actual');
    }

    return { event, importJob };
  }

  private async getActiveImportJob(eventId: Types.ObjectId) {
    return this.padronImportJobModel
      .findOne({ eventId, isActiveDraft: true })
      .sort({ createdAt: -1, _id: -1 })
      .lean();
  }

  private async getOrCreateEditableDraftFromCurrentVersion(event: any, requester?: any) {
    let importJob = await this.getActiveImportJob(event._id);

    if (!this.accessService.canFullyEditEvent(event)) {
      if (importJob) {
        await this.padronImportJobModel.updateOne(
          { _id: importJob._id },
          { $set: { isActiveDraft: false } },
        );
      }
      return null;
    }

    if (importJob) {
      return importJob;
    }

    const currentVersion = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();
    if (!currentVersion) {
      return null;
    }

    try {
      const createdBy =
        requester?.sub && Types.ObjectId.isValid(requester.sub)
          ? new Types.ObjectId(requester.sub)
          : currentVersion.createdBy;

      const createdImportJob = await this.padronImportJobModel.create({
        eventId: event._id,
        tenantId: event.tenantId,
        createdBy,
        sourceType: 'SYSTEM',
        status: 'PARSED',
        isActiveDraft: true,
        originalFileName: currentVersion.sourceFileName ?? `draft-from-${String(currentVersion._id)}.json`,
        originalFileMimeType: currentVersion.sourceFileMimeType ?? 'application/json',
        originalFileSize: 0,
        originalFileSha256: currentVersion.fileDigest,
        parserProvider: 'system-clone',
        parserModel: null,
        parserUsedFallback: true,
      summary: {
        parsedCount: currentVersion.totals?.validCount ?? 0,
        validCount: currentVersion.totals?.validCount ?? 0,
        duplicateCount: currentVersion.totals?.duplicateCount ?? 0,
        invalidCount: currentVersion.totals?.invalidCount ?? 0,
        stagingCount: currentVersion.totals?.validCount ?? 0,
        enabledCount: 0,
        disabledCount: 0,
        missingIdentityCount: 0,
      },
        processedAt: new Date(),
      });

      const entries = await this.padronEntryModel
        .find({ padronVersionId: currentVersion._id }, { carnetNorm: 1, enabled: 1 })
        .sort({ carnetNorm: 1, _id: 1 })
        .lean();

      if (entries.length) {
        await this.padronStagingEntryModel.insertMany(
          entries.map((entry) => ({
            importJobId: createdImportJob._id,
            eventId: event._id,
            tenantId: event.tenantId,
            ciNorm: entry.carnetNorm,
            enabled: entry.enabled !== false,
            sourceKind: 'CLONED',
            createdBy,
            lastEditedBy: createdBy,
          })),
          { ordered: false },
        );
      }

      await this.refreshImportJobSummary(createdImportJob._id);
    } catch (error: any) {
      if (error?.code !== 11000) {
        throw error;
      }
    }

    importJob = await this.getActiveImportJob(event._id);
    return importJob;
  }

  private async refreshImportJobSummary(importJobId: Types.ObjectId) {
    const [job, entries] = await Promise.all([
      this.padronImportJobModel.findById(importJobId).lean(),
      this.padronStagingEntryModel.find({ importJobId }, { enabled: 1, ciNorm: 1 }).lean(),
    ]);

    if (!job) {
      throw new NotFoundException('Importación de padrón no encontrada');
    }

    const stagingCount = entries.length;
    const currentErrorCount = Array.isArray(job.importErrors) ? job.importErrors.length : 0;
    const dids =
      stagingCount > 0
        ? await this.issuerService.getDidsByDnis(
            entries
              .map((entry) => String(entry.ciNorm ?? '').trim())
              .filter((ci) => ci.length > 0),
          )
        : [];
    const didSet = new Set(
      dids
        .map((did) => String(did?.dni ?? '').trim())
        .filter((dni) => dni.length > 0),
    );
    const missingIdentityEntries = entries.filter(
      (entry) => !didSet.has(String(entry.ciNorm ?? '').trim()),
    );
    const missingIdentityCount = missingIdentityEntries.length;
    const enabledMissingIdentityIds = missingIdentityEntries
      .filter((entry) => entry.enabled !== false)
      .map((entry) => entry._id)
      .filter(Boolean);
    if (enabledMissingIdentityIds.length > 0) {
      await this.padronStagingEntryModel.updateMany(
        { _id: { $in: enabledMissingIdentityIds }, importJobId },
        { $set: { enabled: false } },
      );
    }
    const normalizedEntries = entries.map((entry) => {
      const ciNorm = String(entry.ciNorm ?? '').trim();
      return {
        ...entry,
        enabled: didSet.has(ciNorm) && entry.enabled !== false,
      };
    });
    const enabledCount = normalizedEntries.filter((entry) => entry.enabled).length;
    const disabledCount = stagingCount - enabledCount;
    const recalculatedStatus = this.resolveImportJobStatus(stagingCount, currentErrorCount);

    await this.padronImportJobModel.updateOne(
      { _id: importJobId },
      {
        $set: {
          status: recalculatedStatus,
          summary: {
            parsedCount: stagingCount,
            validCount: stagingCount,
            duplicateCount: 0,
            invalidCount: 0,
            stagingCount,
            enabledCount,
            disabledCount,
            missingIdentityCount,
          },
        },
      },
    );
  }

  private mapImportJob(importJob: any, stagingCount?: number) {
    return {
      importJobId: String(importJob._id),
      eventId: String(importJob.eventId),
      tenantId: String(importJob.tenantId),
      sourceType: importJob.sourceType,
      status: importJob.status,
      isActiveDraft: importJob.isActiveDraft === true,
      originalFile: {
        fileName: importJob.originalFileName,
        mimeType: importJob.originalFileMimeType,
        size: importJob.originalFileSize,
        sha256: importJob.originalFileSha256,
      },
      parser: {
        provider: importJob.parserProvider ?? 'local-fallback',
        model: importJob.parserModel ?? null,
        usedFallback: importJob.parserUsedFallback !== false,
      },
      summary: {
        parsedCount: importJob.summary?.parsedCount ?? 0,
        validCount: importJob.summary?.validCount ?? 0,
        duplicateCount: importJob.summary?.duplicateCount ?? 0,
        invalidCount: importJob.summary?.invalidCount ?? 0,
        stagingCount: stagingCount ?? importJob.summary?.stagingCount ?? 0,
        enabledCount: importJob.summary?.enabledCount ?? 0,
        disabledCount: importJob.summary?.disabledCount ?? 0,
        missingIdentityCount: importJob.summary?.missingIdentityCount ?? 0,
      },
      errors: (importJob.importErrors ?? []).map((error: any) => ({
        code: error.code,
        message: error.message,
        rowIndex: error.rowIndex ?? null,
        rawValue: error.rawValue ?? null,
      })),
      processedAt: importJob.processedAt ?? null,
      confirmedAt: importJob.confirmedAt ?? null,
      confirmedPadronVersionId: importJob.confirmedPadronVersionId
        ? String(importJob.confirmedPadronVersionId)
        : null,
      createdAt: importJob.createdAt ?? null,
      updatedAt: importJob.updatedAt ?? null,
    };
  }

  private mapStagingEntry(entry: any) {
    return {
      id: String(entry._id),
      importJobId: String(entry.importJobId),
      ci: entry.ciNorm,
      enabled: entry.enabled !== false,
      sourceKind: entry.sourceKind,
      sourceRow: entry.sourceRow ?? null,
      createdAt: entry.createdAt ?? null,
      updatedAt: entry.updatedAt ?? null,
    };
  }

  private mapCertificateMetadata(certificate: any) {
    return {
      exists: true,
      certificateId: String(certificate._id),
      eventId: String(certificate.eventId),
      padronVersionId: String(certificate.padronVersionId),
      generatedAt: certificate.generatedAt ?? certificate.createdAt ?? null,
      generationMode: certificate.generationMode,
      fileName: certificate.fileName,
      mimeType: certificate.mimeType,
      fileSha256: certificate.fileSha256,
      fileSize: certificate.fileSize,
      sourceType: certificate.sourceType,
      totals: {
        totalCount: certificate.totalCount,
        enabledCount: certificate.enabledCount,
        disabledCount: certificate.disabledCount,
      },
      storageKind: certificate.storageKind,
      materializable: true,
    };
  }

  private async getCertificateVersionContext(
    eventId: string,
    requester: any,
    padronVersionId?: string,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    let version: any = null;
    if (padronVersionId) {
      if (!Types.ObjectId.isValid(padronVersionId)) {
        throw new BadRequestException('padronVersionId invalido');
      }
      version = await this.padronVersionModel
        .findOne({
          _id: new Types.ObjectId(padronVersionId),
          eventId: event._id,
        })
        .lean();
      if (!version) {
        throw new NotFoundException('No existe la version de padron solicitada');
      }
    } else {
      version = await this.padronVersionModel
        .findOne({ eventId: event._id, isCurrent: true })
        .lean();
    }

    return { event, version };
  }

  private async ensurePadronCertificateForVersion(
    event: any,
    version: any,
    requester: any,
    generationMode: PadronCertificateGenerationMode,
    forceRegenerate = false,
  ) {
    const existing = await this.padronCertificateModel.findOne({ padronVersionId: version._id });
    if (existing && !forceRegenerate) {
      return existing.toObject ? existing.toObject() : existing;
    }

    const entries = await this.padronEntryModel
      .find(
        { padronVersionId: version._id },
        { carnetNorm: 1, enabled: 1, _id: 0 },
      )
      .sort({ carnetNorm: 1, _id: 1 })
      .lean();

    if (!entries.length) {
      throw new BadRequestException('No se puede generar constancia PDF sin entradas confirmadas de padrón');
    }

    const enabledCount = entries.filter((entry) => entry.enabled !== false).length;
    const disabledCount = entries.length - enabledCount;
    const generatedAt = new Date();
    const pdfBuffer = this.padronCertificatePdfService.buildPdf({
      eventName: event.name,
      eventId: String(event._id),
      generatedAt,
      padronVersionId: String(version._id),
      sourceType: version.sourceType ?? 'CSV_LEGACY',
      totalCount: entries.length,
      enabledCount,
      disabledCount,
      entries: entries.map((entry) => ({
        ci: entry.carnetNorm,
        enabled: entry.enabled !== false,
      })),
    });
    const fileSha256 = createHash('sha256').update(pdfBuffer).digest('hex');
    const fileName = `padron-constancia-${String(version._id)}.pdf`;

    const payload = {
      eventId: event._id,
      tenantId: event.tenantId,
      padronVersionId: version._id,
      generatedBy: requester?.sub ? new Types.ObjectId(requester.sub) : null,
      generationMode,
      mimeType: 'application/pdf',
      fileName,
      fileSha256,
      fileSize: pdfBuffer.length,
      sourceType: version.sourceType ?? 'CSV_LEGACY',
      totalCount: entries.length,
      enabledCount,
      disabledCount,
      generatedAt,
      storageKind: 'INLINE_BASE64' as const,
      pdfContentBase64: pdfBuffer.toString('base64'),
    };

    if (existing) {
      await this.padronCertificateModel.updateOne(
        { _id: existing._id },
        { $set: payload },
      );
      const updated = await this.padronCertificateModel.findById(existing._id).lean();
      if (!updated) {
        throw new NotFoundException('No se pudo recuperar la constancia PDF regenerada');
      }
      return updated;
    }

    return this.padronCertificateModel.create(payload);
  }

  private async assertStructuralEditableState(event: any, action: string) {
    if (
      ['DRAFT', 'READY_FOR_REVIEW'].includes(event.state) &&
      this.accessService.hasPublicationWindowExpired(event)
    ) {
      event.state = 'PUBLICATION_EXPIRED';
      event.publicationExpiredAt = new Date();
      event.publicationConfirmed = false;
      await event.save();
    }

    if (!this.accessService.canFullyEditEvent(event)) {
      if (action === 'eliminar registros del padrón') {
        throw new BadRequestException(
          'No se pueden eliminar registros porque el padrón ya no está en una etapa editable.',
        );
      }

      throw new BadRequestException(
        `Solo se permite ${action} antes de la publicación oficial y mientras falten más de ${this.accessService.getOfficialPublicationLeadHours()} horas para el inicio de la votación`,
      );
    }
  }

  private buildPadronEditingRules(event: any) {
    const canEditEverything = this.accessService.canFullyEditEvent(event);
    const canEditDuringVoting = this.accessService.canModifyPadronDuringVoting(event);
    const canEditPadronInLimitedMode =
      this.accessService.canEnableExistingPadronEntriesPostPublication(event);

    return {
      canEditEverything,
      canEditDuringVoting,
      canEditPadronInLimitedMode,
      mode: canEditEverything ? 'FULL' : canEditDuringVoting ? 'VOTING_LIMITED' : 'READ_ONLY',
      fullEditDeadline: event.publishDeadline ?? null,
      dateValidationMinHours: this.accessService.getCreateLeadHours(),
      officialPublicationCutoffHours: this.accessService.getOfficialPublicationLeadHours(),
    };
  }

  private async getEventForVotingPadronChange(eventId: string, requester: any, action: string) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    if (!this.accessService.canModifyPadronDuringVoting(event)) {
      throw new BadRequestException(
        `Solo se permite ${action} después de la publicación oficial y hasta el cierre de la votación`,
      );
    }

    return event;
  }

  private async resolveCurrentPadronVersionDoc(eventId: Types.ObjectId) {
    const currentVersion = await this.padronVersionModel.findOne({
      eventId,
      isCurrent: true,
    });

    if (!currentVersion) {
      throw new NotFoundException('No existe padrón vigente');
    }

    return currentVersion;
  }

  private async invalidateCurrentPadronCertificate(padronVersionId: Types.ObjectId) {
    await this.padronCertificateModel.deleteMany({ padronVersionId });
  }

  private async resolvePadronVersion(eventObjectId: Types.ObjectId, padronVersionId?: string) {
    if (padronVersionId) {
      if (!Types.ObjectId.isValid(padronVersionId)) {
        throw new BadRequestException('padronVersionId invalido');
      }

      const version = await this.padronVersionModel.findOne({
        _id: new Types.ObjectId(padronVersionId),
        eventId: eventObjectId,
      });

      if (!version) {
        throw new NotFoundException('No existe la version de padron solicitada');
      }

      return version;
    }

    const currentVersion = await this.padronVersionModel.findOne({
      eventId: eventObjectId,
      isCurrent: true,
    });

    if (!currentVersion) {
      throw new NotFoundException('No existe padron vigente');
    }

    return currentVersion;
  }

  private toObjectId(value: Types.ObjectId | string): Types.ObjectId {
    return value instanceof Types.ObjectId ? value : new Types.ObjectId(String(value));
  }
}

import { ZkAuthService } from "@/modules/zk-auth/services/zk-auth.service";
import { AuthorizationResponseMessage } from "@iden3/js-iden3-auth/dist/types/types-sdk";
import { BadRequestException, Injectable, InternalServerErrorException, Logger, NotFoundException } from "@nestjs/common";
import { InjectModel } from "@nestjs/mongoose";
import { EnabledSession, EnabledSessionDocument } from "../../schemas/enabled-session.shcema";
import { Model, Types } from "mongoose";
import { VoteWritterService } from "../core/vote-writter.service";
import { VotingOption, VotingOptionDocument } from "../../schemas/voting-option.schema";

@Injectable()
export class EmitVoteService {
  constructor(
    @InjectModel(EnabledSession.name)
    private readonly enabledSessionModel: Model<EnabledSessionDocument>,
    @InjectModel(VotingOption.name)
    private readonly votingOptionModel: Model<VotingOptionDocument>,
    private readonly zkAuthService: ZkAuthService,
    private readonly voteWritterService: VoteWritterService,
  ) {}

  async getVoteVc(eventId: string, dni: string): Promise<{ vc: string }> {
    const eventObjectId = new Types.ObjectId(eventId);
    const session = await this.enabledSessionModel.findOne({
      eventId: eventObjectId,
      dni,
    }).exec();
    if (!session) {
      throw new NotFoundException('No enabled session found for this user and event');
    }
    return { vc: session.sessionToken };
  }

  async emitVote(
    optionId: string,
    zkProof: string,
  ): Promise<AuthorizationResponseMessage> {
    const response = await this.zkAuthService.zkRequestCallback('vote', zkProof);

    const eventId = response.body.scope.find((scope) => scope.id === 1)?.vp?.verifiableCredential.credentialSubject.eventId.toString();
    const nullifier = response.body.scope.find((scope) => scope.id === 2)?.vp?.verifiableCredential.credentialSubject.nullifier.toString();
    if (!eventId || !nullifier) {
      throw new BadRequestException('data not found in ZK proof');
    }

    try {
      if (optionId === 'blank') {
        await this.voteWritterService.castVote(eventId, 'BLANK', nullifier);
      } else {
        const option = await this.votingOptionModel.findById(optionId).exec();
        if (!option) {
          throw new NotFoundException('Voting option not found');
        }

        await this.voteWritterService.castVote(eventId, option.name, nullifier);
      }
    } catch (error: any) {
      if (error instanceof BadRequestException || error instanceof NotFoundException) {
        throw error;
      }
      if (error?.message?.includes('Nullifier already used')) {
        throw new BadRequestException('This vote has already been cast');
      } else {
        Logger.error('Error casting vote:', error);
        throw new InternalServerErrorException('An error occurred while casting the vote');
      }
    }

    return response;
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { CreateParticipationDto } from '../../dto/participation.dto';
import {
  ComparisonReport,
  ComparisonReportDocument,
} from '../../schemas/comparison-report.schema';
import { PadronEntry, PadronEntryDocument } from '../../schemas/padron-entry.schema';
import {
  PadronVersion,
  PadronVersionDocument,
} from '../../schemas/padron-version.schema';
import {
  Participation,
  ParticipationDocument,
} from '../../schemas/participation.schema';
import { normalizeCarnet } from '../../utils/carnet-normalizer';
import { InstitutionalVotingAccessService } from '../core/institutional-voting-access.service';

@Injectable()
export class ParticipationService {
  constructor(
    @InjectModel(PadronVersion.name)
    private readonly padronVersionModel: Model<PadronVersionDocument>,
    @InjectModel(PadronEntry.name)
    private readonly padronEntryModel: Model<PadronEntryDocument>,
    @InjectModel(ComparisonReport.name)
    private readonly comparisonReportModel: Model<ComparisonReportDocument>,
    @InjectModel(Participation.name)
    private readonly participationModel: Model<ParticipationDocument>,
    private readonly accessService: InstitutionalVotingAccessService,
  ) {}

  async createParticipation(
    eventId: string,
    dto: CreateParticipationDto,
    idempotencyKey?: string,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    const carnetNorm = normalizeCarnet(dto.carnet);
    if (!carnetNorm) {
      throw new BadRequestException('carnet inválido');
    }

    if (idempotencyKey) {
      const existingByKey = await this.participationModel
        .findOne({ eventId: event._id, carnetNorm, idempotencyKey })
        .lean();

      if (existingByKey) {
        return {
          statusCode: 200,
          body: {
            id: String(existingByKey._id),
            participated: true,
            participatedAt: existingByKey.participatedAt,
          },
        };
      }
    }

    const status = await this.resolveParticipationStatus(eventId, carnetNorm);
    if (status.status === 'ALREADY_VOTED') {
      throw new ConflictException('Ya participaste en este evento');
    }
    if (status.status !== 'CAN_VOTE') {
      throw new ForbiddenException({ error: status.status });
    }

    try {
      const created = await this.participationModel.create({
        eventId: event._id,
        carnetNorm,
        idempotencyKey,
        participatedAt: new Date(),
      });

      return {
        statusCode: 201,
        body: {
          id: String(created._id),
          participated: true,
          participatedAt: created.participatedAt,
        },
      };
    } catch (error: any) {
      if (error?.code === 11000 && idempotencyKey) {
        const existing = await this.participationModel
          .findOne({ eventId: event._id, carnetNorm, idempotencyKey })
          .lean();

        if (existing) {
          return {
            statusCode: 200,
            body: {
              id: String(existing._id),
              participated: true,
              participatedAt: existing.participatedAt,
            },
          };
        }
      }
      if (error?.code === 11000) {
        throw new ConflictException('Ya participaste en este evento');
      }
      throw error;
    }
  }

  async checkParticipationStatus(eventId: string, carnet: string) {
    const normalized = normalizeCarnet(carnet);
    if (!normalized) {
      throw new BadRequestException('carnet inválido');
    }

    return this.resolveParticipationStatus(eventId, normalized);
  }

  private async resolveParticipationStatus(eventId: string, carnetNorm: string) {
    const event = await this.accessService.getEventOrThrow(eventId);

    if (!['OFFICIALLY_PUBLISHED', 'PUBLISHED'].includes(event.state)) {
      return { status: 'EVENT_NOT_PUBLISHED', canVote: false, alreadyVoted: false };
    }

    const now = new Date();
    if (!event.votingStart || !event.votingEnd || now < event.votingStart || now > event.votingEnd) {
      return { status: 'OUTSIDE_VOTING_WINDOW', canVote: false, alreadyVoted: false };
    }

    const currentVersion = await this.padronVersionModel
      .findOne({ eventId: event._id, isCurrent: true })
      .lean();

    if (!currentVersion) {
      return { status: 'PADRON_NOT_AVAILABLE', canVote: false, alreadyVoted: false };
    }

    const reportOk = await this.comparisonReportModel.exists({
      padronVersionId: currentVersion._id,
      status: 'OK',
    });
    if (!reportOk) {
      return { status: 'ROLL_IN_VALIDATION', canVote: false, alreadyVoted: false };
    }

    const inPadron = await this.padronEntryModel.findOne({
      padronVersionId: currentVersion._id,
      carnetNorm,
    }, { enabled: 1 }).lean();
    if (!inPadron) {
      return { status: 'NOT_IN_ROLL', canVote: false, alreadyVoted: false };
    }

    if (inPadron.enabled === false) {
      return { status: 'VOTER_DISABLED', canVote: false, alreadyVoted: false };
    }

    const existing = await this.participationModel
      .findOne({ eventId: event._id, carnetNorm })
      .lean();

    if (existing) {
      return {
        status: 'ALREADY_VOTED',
        canVote: false,
        alreadyVoted: true,
        participatedAt: existing.participatedAt,
      };
    }

    return { status: 'CAN_VOTE', canVote: true, alreadyVoted: false };
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
  UnauthorizedException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Cron } from '@nestjs/schedule';
import { MessageEvent } from '@nestjs/common';
import { Model, Types } from 'mongoose';
import { createHash, randomBytes, timingSafeEqual } from 'crypto';
import { EMPTY, merge, Observable, of, Subject } from 'rxjs';
import { normalizeCarnet } from '../../utils/carnet-normalizer';
import {
  PresentialSession,
  PresentialSessionDocument,
} from '../../schemas/presential-session.schema';
import {
  VotingEvent,
  VotingEventDocument,
} from '../../schemas/voting-event.schema';
import {
  CreatePresentialSessionDto,
  ScanPresentialSessionDto,
} from '../../dto/presential-session.dto';
import { InstitutionalVotingAccessService } from '../core/institutional-voting-access.service';
import { ParticipationService } from '../participation/participation.service';

type PresentialTerminalReason = 'EXPIRED' | 'CANCELLED';

type PresentialCurrentState = {
  eventId: string;
  eventName: string;
  stationId: string;
  kioskEnabled: boolean;
  eventState: string;
  isEventActive: boolean;
  session: {
    id: string;
    eventId: string;
    stationId: string;
    status: string;
    rotationNumber: number;
    expiresAt: Date | null;
    claimedAt: Date | null;
    completedAt: Date | null;
    qrToken: string | null;
    qrValue: string | null;
  } | null;
};

@Injectable()
export class PresentialSessionsService {
  private readonly primaryStationId = 'kiosco-principal';
  private readonly readyTtlSecondsDefault: number;
  private readonly claimTtlSecondsDefault: number;
  private readonly streamChannels = new Map<string, Subject<MessageEvent>>();

  constructor(
    @InjectModel(PresentialSession.name)
    private readonly presentialSessionModel: Model<PresentialSessionDocument>,
    @InjectModel(VotingEvent.name)
    private readonly votingEventModel: Model<VotingEventDocument>,
    private readonly accessService: InstitutionalVotingAccessService,
    private readonly participationService: ParticipationService,
  ) {
    this.readyTtlSecondsDefault = 300;
    this.claimTtlSecondsDefault = 300;
  }

  async createOrRotateCurrentSession(
    eventId: string,
    dto: CreatePresentialSessionDto | undefined,
    requester: any,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);
    await this.accessService.assertTenantWriteAccess(event.tenantId, requester);

    const stationId = this.normalizeStationId(dto?.stationId);
    const shouldRotateKioskToken =
      dto?.regenerateKioskAccessToken === true ||
      !event.presentialKioskTokenHash;

    await this.expireStaleSessionsForEvent(event, stationId);

    const current = await this.getCurrentActiveSession(event._id, stationId);
    if (current?.status === 'CLAIMED') {
      throw new ConflictException(
        'No se puede rotar el QR mientras una sesión presencial está en curso',
      );
    }

    let kioskAccessToken: string | null = null;
    if (shouldRotateKioskToken) {
      kioskAccessToken = this.issueKioskAccessTokenValue();
      event.presentialKioskTokenHash = this.hashValue(kioskAccessToken);
      event.presentialKioskIssuedAt = new Date();
    }

    event.presentialKioskEnabled = true;
    await event.save();

    let cancelledSessionId: string | null = null;
    if (current?.status === 'READY') {
      const cancelled = await this.presentialSessionModel.findOneAndUpdate(
        {
          _id: current._id,
          status: 'READY',
        },
        {
          $set: {
            status: 'CANCELLED',
            expiresAt: new Date(),
          },
        },
        { returnDocument: 'after' },
      );
      if (cancelled) {
        cancelledSessionId = String(cancelled._id);
      }
    }

    const readyTtlSeconds = this.clampSeconds(
      dto?.readyTtlSeconds,
      30,
      900,
      this.readyTtlSecondsDefault,
    );
    const claimTtlSeconds = this.clampSeconds(
      dto?.claimTtlSeconds,
      30,
      1800,
      this.claimTtlSecondsDefault,
    );

    let nextSession: PresentialSessionDocument | null = null;
    if (this.isEventActive(event)) {
      nextSession = await this.createReadySession(event, stationId, requester, {
        readyTtlSeconds,
        claimTtlSeconds,
        rotatedFromSessionId: cancelledSessionId,
      });
    }

    return {
      eventId: String(event._id),
      stationId,
      kioskEnabled: true,
      kioskAccessToken,
      kioskBootstrap: {
        authHeader: 'x-kiosk-token',
        currentPath: `/api/v1/voting/events/${String(event._id)}/presential-sessions/current?stationId=${encodeURIComponent(stationId)}`,
        streamPath: `/api/v1/voting/events/${String(event._id)}/presential-sessions/stream?stationId=${encodeURIComponent(stationId)}`,
      },
      currentSession: nextSession
        ? this.buildSessionPayload(nextSession)
        : null,
      claimTtlSeconds,
      readyTtlSeconds,
    };
  }

  async getCurrentSessionState(
    eventId: string,
    stationIdRaw?: string,
    kioskToken?: string,
    requester?: any,
  ): Promise<PresentialCurrentState> {
    const event = await this.authorizeKioskAccess(
      eventId,
      kioskToken,
      requester,
    );
    const stationId = this.normalizeStationId(stationIdRaw);

    await this.expireStaleSessionsForEvent(event, stationId);
    if (!event.presentialKioskEnabled) {
      return this.buildCurrentStatePayload(event, stationId, null);
    }

    let current = await this.getCurrentActiveSession(event._id, stationId);
    if (!current && event.presentialKioskEnabled && this.isEventActive(event)) {
      current = await this.ensureCurrentReadySession(event, stationId);
    }

    return this.buildCurrentStatePayload(event, stationId, current);
  }

  async createAuthorizedStream(
    eventId: string,
    stationIdRaw?: string,
    kioskToken?: string,
    requester?: any,
  ): Promise<Observable<MessageEvent>> {
    const stationId = this.normalizeStationId(stationIdRaw);
    const currentState = await this.getCurrentSessionState(
      eventId,
      stationId,
      kioskToken,
      requester,
    );
    const initial$ = currentState.session
      ? of(
          this.buildMessageEvent(
            this.resolveCurrentEventName(currentState.session.status),
            currentState,
          ),
        )
      : EMPTY;

    return merge(
      initial$,
      this.getChannel(String(currentState.eventId), stationId).asObservable(),
    );
  }

  async scanAndClaim(dto: ScanPresentialSessionDto) {
    const token = String(dto.token || '').trim();
    if (!token) {
      throw new BadRequestException('token inválido');
    }

    const carnetNorm = normalizeCarnet(dto.carnet);
    if (!carnetNorm) {
      throw new BadRequestException('carnet inválido');
    }

    const parsed = this.parseSessionToken(token);
    if (!parsed) {
      throw new BadRequestException('token inválido');
    }

    const session = await this.presentialSessionModel.findById(
      parsed.sessionId,
    );
    if (!session) {
      throw new NotFoundException('Sesión presencial no encontrada');
    }

    if (
      session.tokenId !== parsed.tokenId ||
      !this.hashMatches(token, session.tokenHash)
    ) {
      throw new ForbiddenException({ error: 'INVALID_QR_TOKEN' });
    }

    const event = await this.votingEventModel.findById(session.eventId);
    if (!event) {
      throw new NotFoundException('Evento no encontrado');
    }

    await this.expireSessionIfStale(session);
    const freshSession =
      (await this.presentialSessionModel.findById(session._id)) ?? session;

    if (!event.presentialKioskEnabled) {
      throw new ForbiddenException({ error: 'KIOSK_DISABLED' });
    }
    if (!this.isEventActive(event)) {
      throw new ForbiddenException({ error: 'EVENT_NOT_ACTIVE' });
    }

    const status = await this.participationService.checkParticipationStatus(
      String(event._id),
      carnetNorm,
    );
    if (status.status === 'ALREADY_VOTED') {
      throw new ConflictException('Ya participaste en este evento');
    }
    if (status.status !== 'CAN_VOTE') {
      throw new ForbiddenException({ error: status.status });
    }

    if (
      freshSession.status === 'CLAIMED' &&
      freshSession.claimedByCarnetNorm === carnetNorm &&
      freshSession.expiresAt.getTime() > Date.now()
    ) {
      return {
        statusCode: 200,
        body: this.buildClaimResponse(freshSession),
      };
    }

    if (freshSession.status !== 'READY') {
      throw new ConflictException({
        error:
          freshSession.status === 'COMPLETED'
            ? 'QR_ALREADY_USED'
            : freshSession.status === 'EXPIRED'
              ? 'QR_EXPIRED'
              : freshSession.status === 'CANCELLED'
                ? 'QR_CANCELLED'
                : 'QR_ALREADY_CLAIMED',
      });
    }

    const now = new Date();
    const claimed = await this.presentialSessionModel.findOneAndUpdate(
      {
        _id: freshSession._id,
        status: 'READY',
        expiresAt: { $gt: now },
      },
      {
        $set: {
          status: 'CLAIMED',
          claimedAt: now,
          claimedByCarnetNorm: carnetNorm,
          expiresAt: this.computeFutureDate(
            this.clampSeconds(
              freshSession.claimTtlSeconds,
              30,
              1800,
              this.claimTtlSecondsDefault,
            ),
          ),
        },
      },
      { returnDocument: 'after' },
    );

    if (!claimed) {
      const latest = await this.presentialSessionModel.findById(
        freshSession._id,
      );
      if (
        latest?.status === 'CLAIMED' &&
        latest.claimedByCarnetNorm === carnetNorm &&
        latest.expiresAt.getTime() > Date.now()
      ) {
        return {
          statusCode: 200,
          body: this.buildClaimResponse(latest),
        };
      }

      throw new ConflictException({ error: 'QR_ALREADY_CLAIMED' });
    }

    this.publishStateEvent(
      'session.claimed',
      event,
      claimed.stationId,
      claimed,
    );

    return {
      statusCode: 201,
      body: this.buildClaimResponse(claimed),
    };
  }

  async assertSessionCanRegisterParticipation(
    eventId: string,
    presentialSessionId: string,
    carnet: string,
  ) {
    const carnetNorm = normalizeCarnet(carnet);
    if (!carnetNorm) {
      throw new BadRequestException('carnet inválido');
    }

    const session = await this.requireSessionForEvent(
      eventId,
      presentialSessionId,
    );
    const event = await this.votingEventModel.findById(session.eventId);
    if (!event) {
      throw new NotFoundException('Evento no encontrado');
    }
    if (!event.presentialKioskEnabled) {
      throw new ForbiddenException({ error: 'KIOSK_DISABLED' });
    }

    await this.expireSessionIfStale(session);
    const latest =
      (await this.presentialSessionModel.findById(session._id)) ?? session;

    if (
      latest.status === 'COMPLETED' &&
      latest.claimedByCarnetNorm === carnetNorm
    ) {
      return latest;
    }
    if (latest.status !== 'CLAIMED') {
      throw new ConflictException({ error: 'PRESENTIAL_SESSION_NOT_CLAIMED' });
    }
    if (latest.claimedByCarnetNorm !== carnetNorm) {
      throw new ForbiddenException({ error: 'PRESENTIAL_SESSION_NOT_OWNED' });
    }
    if (latest.expiresAt.getTime() <= Date.now()) {
      throw new ConflictException({ error: 'PRESENTIAL_SESSION_EXPIRED' });
    }

    return latest;
  }

  async completeSessionForParticipation(
    eventId: string,
    presentialSessionId: string,
    carnet: string,
  ) {
    const carnetNorm = normalizeCarnet(carnet);
    if (!carnetNorm) {
      throw new BadRequestException('carnet inválido');
    }

    const session = await this.requireSessionForEvent(
      eventId,
      presentialSessionId,
    );
    const event = await this.votingEventModel.findById(session.eventId);
    if (!event) {
      throw new NotFoundException('Evento no encontrado');
    }

    await this.expireSessionIfStale(session);
    const latest =
      (await this.presentialSessionModel.findById(session._id)) ?? session;

    if (
      latest.status === 'COMPLETED' &&
      latest.claimedByCarnetNorm === carnetNorm
    ) {
      return latest;
    }
    if (latest.status !== 'CLAIMED') {
      throw new ConflictException({ error: 'PRESENTIAL_SESSION_NOT_CLAIMED' });
    }
    if (latest.claimedByCarnetNorm !== carnetNorm) {
      throw new ForbiddenException({ error: 'PRESENTIAL_SESSION_NOT_OWNED' });
    }

    const completedAt = new Date();
    const completed = await this.presentialSessionModel.findOneAndUpdate(
      {
        _id: latest._id,
        status: 'CLAIMED',
        claimedByCarnetNorm: carnetNorm,
      },
      {
        $set: {
          status: 'COMPLETED',
          completedAt,
          expiresAt: completedAt,
        },
      },
      { returnDocument: 'after' },
    );

    if (!completed) {
      const refetched = await this.presentialSessionModel.findById(latest._id);
      if (
        refetched?.status === 'COMPLETED' &&
        refetched.claimedByCarnetNorm === carnetNorm
      ) {
        return refetched;
      }
      throw new ConflictException({
        error: 'PRESENTIAL_SESSION_COMPLETE_FAILED',
      });
    }

    this.publishStateEvent(
      'session.completed',
      event,
      completed.stationId,
      completed,
    );
    await this.ensureCurrentReadySession(event, completed.stationId, null, {
      rotatedFromSessionId: String(completed._id),
    });

    return completed;
  }

  async expireSessionNow(sessionId: string) {
    const session = await this.presentialSessionModel.findById(sessionId);
    if (!session) return null;
    return this.expireSession(session, 'EXPIRED');
  }

  @Cron('*/15 * * * * *')
  async expireTimedOutSessions() {
    const stale = await this.presentialSessionModel
      .find({
        status: { $in: ['READY', 'CLAIMED'] },
        expiresAt: { $lte: new Date() },
      })
      .sort({ expiresAt: 1, _id: 1 })
      .limit(100);

    for (const session of stale) {
      await this.expireSession(session, 'EXPIRED');
    }
  }

  private async authorizeKioskAccess(
    eventId: string,
    kioskToken?: string,
    requester?: any,
  ) {
    const event = await this.accessService.getEventOrThrow(eventId);

    if (requester?.sub) {
      await this.accessService.assertTenantWriteAccess(
        event.tenantId,
        requester,
      );
      return event;
    }

    const normalizedToken = String(kioskToken || '').trim();
    if (!normalizedToken) {
      throw new UnauthorizedException('Debe enviar x-kiosk-token');
    }
    if (!event.presentialKioskEnabled || !event.presentialKioskTokenHash) {
      throw new ForbiddenException('El kiosco presencial no está habilitado');
    }
    if (!this.hashMatches(normalizedToken, event.presentialKioskTokenHash)) {
      throw new UnauthorizedException('x-kiosk-token inválido');
    }

    event.presentialKioskLastUsedAt = new Date();
    await event.save();

    return event;
  }

  private normalizeStationId(value?: string) {
    const normalized = String(value || '').trim();
    return normalized || this.primaryStationId;
  }

  private clampSeconds(
    value: number | undefined,
    min: number,
    max: number,
    fallback: number,
  ) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return fallback;
    return Math.min(max, Math.max(min, Math.round(numeric)));
  }

  private issueKioskAccessTokenValue() {
    return `pkc_${randomBytes(24).toString('hex')}`;
  }

  private hashValue(value: string) {
    return createHash('sha256').update(value).digest('hex');
  }

  private hashMatches(rawValue: string, expectedHash?: string | null) {
    if (!expectedHash) return false;

    const actual = Buffer.from(this.hashValue(rawValue), 'hex');
    const expected = Buffer.from(expectedHash, 'hex');
    if (actual.length !== expected.length) return false;
    return timingSafeEqual(actual, expected);
  }

  private parseSessionToken(token: string) {
    const parts = token.split('.');
    if (parts.length !== 3 || parts[0] !== 'pqs') {
      return null;
    }

    const [, sessionId, tokenId] = parts;
    if (!Types.ObjectId.isValid(sessionId) || !tokenId) {
      return null;
    }

    return { sessionId, tokenId };
  }

  private buildSessionToken(session: {
    _id: Types.ObjectId | string;
    tokenId: string;
  }) {
    return `pqs.${String(session._id)}.${session.tokenId}`;
  }

  private computeFutureDate(seconds: number) {
    return new Date(Date.now() + seconds * 1000);
  }

  private isEventActive(
    event: VotingEventDocument | (VotingEvent & { _id: Types.ObjectId }),
  ) {
    const now = Date.now();
    const start = event.votingStart ? new Date(event.votingStart).getTime() : 0;
    const end = event.votingEnd ? new Date(event.votingEnd).getTime() : 0;
    return (
      ['OFFICIALLY_PUBLISHED', 'PUBLISHED'].includes(event.state) &&
      Boolean(start) &&
      Boolean(end) &&
      now >= start &&
      now <= end
    );
  }

  private async getCurrentActiveSession(
    eventId: Types.ObjectId,
    stationId: string,
  ): Promise<PresentialSessionDocument | null> {
    return this.presentialSessionModel
      .findOne({
        eventId,
        stationId,
        status: { $in: ['READY', 'CLAIMED'] },
        expiresAt: { $gt: new Date() },
      })
      .sort({ rotationNumber: -1, _id: -1 })
      .exec();
  }

  private buildSessionPayload(session: PresentialSessionDocument) {
    const qrToken =
      session.status === 'READY' ? this.buildSessionToken(session) : null;

    return {
      id: String(session._id),
      eventId: String(session.eventId),
      stationId: session.stationId,
      status: session.status,
      rotationNumber: session.rotationNumber,
      expiresAt: session.expiresAt ?? null,
      claimedAt: session.claimedAt ?? null,
      completedAt: session.completedAt ?? null,
      qrToken,
      qrValue: qrToken,
    };
  }

  private buildCurrentStatePayload(
    event: VotingEventDocument,
    stationId: string,
    session: PresentialSessionDocument | null,
  ): PresentialCurrentState {
    return {
      eventId: String(event._id),
      eventName: event.name,
      stationId,
      kioskEnabled: Boolean(event.presentialKioskEnabled),
      eventState: event.state,
      isEventActive: this.isEventActive(event),
      session: session ? this.buildSessionPayload(session) : null,
    };
  }

  private resolveCurrentEventName(status: string) {
    if (status === 'CLAIMED') return 'session.claimed';
    if (status === 'COMPLETED') return 'session.completed';
    if (status === 'EXPIRED') return 'session.expired';
    return 'session.ready';
  }

  private buildClaimResponse(session: PresentialSessionDocument) {
    return {
      presentialSessionId: String(session._id),
      eventId: String(session.eventId),
      stationId: session.stationId,
      status: session.status,
      claimedAt: session.claimedAt ?? null,
      expiresAt: session.expiresAt ?? null,
      nextAction: 'CONTINUE_VOTING',
    };
  }

  private getChannel(eventId: string, stationId: string) {
    const key = `${eventId}:${stationId}`;
    const existing = this.streamChannels.get(key);
    if (existing) {
      return existing;
    }

    const created = new Subject<MessageEvent>();
    this.streamChannels.set(key, created);
    return created;
  }

private buildMessageEvent(type: string, data: string | object): MessageEvent {
  return {
    type,
    data,
  };
}

  private publishStateEvent(
    type: string,
    event: VotingEventDocument,
    stationId: string,
    session: PresentialSessionDocument,
  ) {
    const payload = this.buildCurrentStatePayload(event, stationId, session);
    this.getChannel(String(event._id), stationId).next(
      this.buildMessageEvent(type, payload),
    );
  }

  private publishRotatedEvent(
    event: VotingEventDocument,
    stationId: string,
    previousSessionId: string,
    session: PresentialSessionDocument,
  ) {
    this.getChannel(String(event._id), stationId).next(
      this.buildMessageEvent('session.rotated', {
        eventId: String(event._id),
        eventName: event.name,
        stationId,
        previousSessionId,
        session: this.buildSessionPayload(session),
      }),
    );
  }

  private async ensureCurrentReadySession(
    event: VotingEventDocument,
    stationId: string,
    requester?: any,
    options?: {
      readyTtlSeconds?: number;
      claimTtlSeconds?: number;
      rotatedFromSessionId?: string | null;
    },
  ): Promise<PresentialSessionDocument | null> {
    const active = await this.getCurrentActiveSession(
      event._id as Types.ObjectId,
      stationId,
    );
    if (active) {
      return active;
    }
    if (!event.presentialKioskEnabled || !this.isEventActive(event)) {
      return null;
    }

    return this.createReadySession(event, stationId, requester, options);
  }

  private async createReadySession(
    event: VotingEventDocument,
    stationId: string,
    requester?: any,
    options?: {
      readyTtlSeconds?: number;
      claimTtlSeconds?: number;
      rotatedFromSessionId?: string | null;
    },
  ): Promise<PresentialSessionDocument> {
    const readyTtlSeconds = this.clampSeconds(
      options?.readyTtlSeconds,
      30,
      900,
      this.readyTtlSecondsDefault,
    );
    const sessionId = new Types.ObjectId();
    const tokenId = randomBytes(24).toString('hex');
    const token = this.buildSessionToken({ _id: sessionId, tokenId });
    const tokenHash = this.hashValue(token);

    const latest = await this.presentialSessionModel
      .findOne({ eventId: event._id, stationId })
      .sort({ rotationNumber: -1, _id: -1 })
      .lean();
    const rotationNumber = Number(latest?.rotationNumber || 0) + 1;

    let created: PresentialSessionDocument;
    try {
      created = await this.presentialSessionModel.create({
        _id: sessionId,
        eventId: event._id,
        stationId,
        tokenId,
        tokenHash,
        status: 'READY',
        expiresAt: this.computeFutureDate(readyTtlSeconds),
        claimedAt: null,
        completedAt: null,
        claimedByCarnetNorm: null,
        createdBy: this.toObjectIdOrNull(requester?.sub),
        rotationNumber,
        claimTtlSeconds: this.clampSeconds(
          options?.claimTtlSeconds,
          30,
          1800,
          this.claimTtlSecondsDefault,
        ),
      });
    } catch (error) {
      if (this.isDuplicateActiveSessionError(error)) {
        const current = await this.getCurrentActiveSession(
          event._id as Types.ObjectId,
          stationId,
        );
        if (current) {
          return current;
        }
      }
      throw error;
    }

    if (options?.rotatedFromSessionId) {
      this.publishRotatedEvent(
        event,
        stationId,
        options.rotatedFromSessionId,
        created,
      );
    }
    this.publishStateEvent('session.ready', event, stationId, created);
    return created;
  }

  private toObjectIdOrNull(value?: string | null) {
    if (!value || !Types.ObjectId.isValid(value)) {
      return null;
    }
    return new Types.ObjectId(value);
  }

  private isDuplicateActiveSessionError(error: unknown) {
    return (
      typeof error === 'object' &&
      error !== null &&
      'code' in error &&
      Number((error as { code?: unknown }).code) === 11000
    );
  }

  private async requireSessionForEvent(
    eventId: string,
    presentialSessionId: string,
  ) {
    if (!Types.ObjectId.isValid(presentialSessionId)) {
      throw new BadRequestException('presentialSessionId inválido');
    }

    const session =
      await this.presentialSessionModel.findById(presentialSessionId);
    if (!session || String(session.eventId) !== String(eventId)) {
      throw new NotFoundException('Sesión presencial no encontrada');
    }
    return session;
  }

  private async expireStaleSessionsForEvent(
    event: VotingEventDocument,
    stationId?: string,
  ) {
    const filter: Record<string, unknown> = {
      eventId: event._id,
      status: { $in: ['READY', 'CLAIMED'] },
      expiresAt: { $lte: new Date() },
    };
    if (stationId) {
      filter.stationId = stationId;
    }

    const stale = await this.presentialSessionModel
      .find(filter)
      .sort({ expiresAt: 1, _id: 1 })
      .limit(50);

    for (const session of stale) {
      await this.expireSession(session, 'EXPIRED');
    }
  }

  private async expireSessionIfStale(session: PresentialSessionDocument) {
    if (
      ['READY', 'CLAIMED'].includes(session.status) &&
      session.expiresAt.getTime() <= Date.now()
    ) {
      await this.expireSession(session, 'EXPIRED');
    }
  }

  private async expireSession(
    session: PresentialSessionDocument,
    targetStatus: PresentialTerminalReason,
  ) {
    const updated = await this.presentialSessionModel.findOneAndUpdate(
      {
        _id: session._id,
        status: { $in: ['READY', 'CLAIMED'] },
      },
      {
        $set: {
          status: targetStatus,
          expiresAt: new Date(),
        },
      },
      { returnDocument: 'after' },
    );

    if (!updated) {
      return null;
    }

    const event = await this.votingEventModel.findById(updated.eventId);
    if (!event) {
      return updated;
    }

    if (targetStatus === 'EXPIRED') {
      this.publishStateEvent(
        'session.expired',
        event,
        updated.stationId,
        updated,
      );
    }

    await this.ensureCurrentReadySession(event, updated.stationId, null, {
      rotatedFromSessionId: String(updated._id),
    });

    return updated;
  }
}

import { SendEmailCommand, SESClient } from '@aws-sdk/client-ses';
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { readFileSync } from 'fs';
import path from 'path';
import ejs from 'ejs';

@Injectable()
export class MailService {
  private readonly logger = new Logger(MailService.name);
  private readonly sesClient: SESClient;

  constructor(
    private config: ConfigService,
  ) {
    this.sesClient = new SESClient({
      region: this.config.get<string>('app.mail.smtp.region') ?? '',
      credentials: {
        accessKeyId: this.config.get<string>('app.mail.smtp.accessKeyId') ?? '',
        secretAccessKey: this.config.get<string>('app.mail.smtp.secretAccessKey') ?? '',
      }
    })
  }

  createEmail(toAddress: string, subject: string, template: string, templateData: ejs.Data): SendEmailCommand {
    const templateString = this.getTemplate(template);
    const emailBody = ejs.render(templateString, {
      ...templateData,
      logoUrl: this.config.get<string>('app.mail.logoUrl'),
    })

    return new SendEmailCommand({
      Destination: {
        ToAddresses: [toAddress],
      },
      Source: this.config.get('app.mail.smtp.from') ?? '',
      Message: {
        Subject: {
          Charset: 'UTF-8',
          Data: subject,
        },
        Body: {
          Html: {
            Charset: 'UTF-8',
            Data: emailBody,
          }
        }
      }
    })
  }

  async sendEmail(
    to: string,
    subject: string,
    template: string,
    data: any,
  ) {
    try {
      const emailsList: string[] = [to];

      if (!emailsList) {
        throw new Error(
          `No recipients found for sending email`,
        );
      }

      const email = this.createEmail(to, subject, template, data);

      await this.sesClient.send(email);
      this.logger.log(
        `Email sent successfully to recipients with the following parameters : ${JSON.stringify({
          to, template, data
        })}`,
      );
    } catch (error: any) {
      throw new Error(
        `Error while sending mail: ` + error.message,
      );
    }
  }

  getTemplate(templateName: string) {
    const file = path.resolve(path.join(__dirname, '../../../templates'), templateName + '.html');
    return readFileSync(file, 'utf8');
  }
}

