import { AnnounceCountDto } from '../dto/annunce.dto';

@ApiTags('Announcements')
@Controller('api/v1/announcements')
export class AnnouncementsController {
  constructor(
    private readonly topics: TopicMessagingService,
    private readonly locations: ElectoralLocationService,
    private readonly tables: ElectoralTableService,
  ) {}
  @Post('count')
  @HttpCode(HttpStatus.ACCEPTED)
  @ApiOperation({
    summary: 'Anunciar conteo al topic del recinto (loc_<locationId>)',
  })
  async announce(@Body() dto: AnnounceCountDto) {
    const location = await this.locations.resolveByIdOrCode({
      locationId: (dto.locationId ?? '').trim() || undefined,
      locationCode: (dto.locationCode ?? '').trim() || undefined,
    });

    let table: any = null;
    if (dto.tableId || dto.tableCode) {
      table = await this.tables.resolveByIdOrCode({
        tableId: dto.tableId,
        tableCode: dto.tableCode,
      });

      const tblLocId = String(
        table.electoralLocationId?._id ??
          table.electoralLocationId ??
          table.electoralLocation?._id,
      );
      if (tblLocId !== String(location._id)) {
        return { success: false, error: 'La mesa no pertenece al recinto' };
      }
    }

    const res = await this.topics.announceCountToLocation({
      locationId: String(location._id),
      locationName: location.name,
      locationAddress: location.address,
      tableId: table?._id ? String(table._id) : dto.tableId,
      tableNumber: table?.tableNumber ?? undefined,
      tableCode: table?.tableCode ?? dto.tableCode ?? undefined,
      title: dto.title,
      body: dto.body,
    });

    return { success: true, result: res };
  }
}

import {
  Body,
  Controller,
  Headers,
  HttpCode,
  HttpStatus,
  Post,
  UnauthorizedException,
} from '@nestjs/common';
import { ApiTags, ApiOperation } from '@nestjs/swagger';
import { DirectPushService } from '../services/direct-push.service';
import { DirectPushDto } from '../dto/direct-push.dto';
import { NotificationLog } from '../schemas/notification-log.schema';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { User } from '@/modules/users/schemas/user.schema';

@ApiTags('InternalPush')
@Controller('internal')
export class InternalPushController {
  constructor(
    private readonly direct: DirectPushService,
    @InjectModel(NotificationLog.name)
    private logModel: Model<NotificationLog>,
    @InjectModel(User.name)
    private userModel: Model<User>,
  ) {}

  @Post('push')
  @HttpCode(HttpStatus.ACCEPTED)
  @ApiOperation({
    summary: 'Recibe eventos de identidad y reenvía push a tokens FCM',
  })
  async push(
    @Headers('x-internal-secret') secret: string,
    @Body() dto: DirectPushDto,
  ) {
    // Mantener este contrato tal cual hasta validar a todos los emisores de
    // eventos internos que dependen de este header y de su semántica actual.
    if (secret !== process.env.INTERNAL_PUSH_SECRET) {
      throw new UnauthorizedException('bad secret');
    }

    await this.direct.sendToTokens(dto.tokens, dto.notification, dto.data);

    try {
      let topic = 'generic';

      // Preferimos userId si viene en data (recomendado)
      if (dto.data && dto.data['userId']) {
        const userId = dto.data['userId'];
        topic = `user_${userId}`;
      } else if (dto.data && dto.data['dni']) {
        // Fallback: buscar el usuario por DNI
        const dni = dto.data['dni'];
        const user = await this.userModel.findOne({ dni }, { _id: 1 }).lean();
        if (user?._id) {
          topic = `user_${user._id.toString()}`;
        } else {
          topic = `identity_${dni}`;
        }
      }

      await this.logModel.create({
        type: 'generic',
        topic,
        title: dto.notification.title,
        body: dto.notification.body,
        data: dto.data,
        status: 'SENT',
      });
    } catch (e) {
      // No romper si falla el log
    }

    return { success: true };
  }
}

import { Controller, Get, Query } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { NotificationLog } from '../schemas/notification-log.schema';
import { ApiTags, ApiQuery, ApiOperation } from '@nestjs/swagger';

@ApiTags('Notification Logs')
@Controller('api/v1/notifications/logs')
export class NotificationLogsController {
  constructor(@InjectModel(NotificationLog.name) private logModel: Model<NotificationLog>) {}

  @Get()
  @ApiOperation({ summary: 'Historial de notificaciones' })
  @ApiQuery({ name: 'locationId', required: false })
  @ApiQuery({ name: 'topic', required: false })
  @ApiQuery({ name: 'type', required: false, enum: ['announce_count', 'generic'] })
  @ApiQuery({ name: 'page', required: false, example: 1 })
  @ApiQuery({ name: 'limit', required: false, example: 20 })
  async list(
    @Query('locationId') locationId?: string,
    @Query('topic') topic?: string,
    @Query('type') type?: string,
    @Query('page') page = 1,
    @Query('limit') limit = 50,
  ) {
    const filter: any = {};
    if (locationId) filter.locationId = locationId;
    if (topic) filter.topic = topic;
    if (type) filter.type = type;

    const skip = (Number(page) - 1) * Number(limit);
    const [data, total] = await Promise.all([
      this.logModel.find(filter).sort({ createdAt: -1 }).skip(skip).limit(Number(limit)).lean(),
      this.logModel.countDocuments(filter),
    ]);

    return {
      data,
      total,
      page: Number(page),
      limit: Number(limit),
      totalPages: Math.ceil(total / Number(limit)),
    };
  }
}

import { Controller, Get, Param, Query } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { ApiTags, ApiOperation, ApiQuery, ApiParam } from '@nestjs/swagger';
import { User } from '@/modules/users/schemas/user.schema';
import { UserNotification } from '../schemas/user-notification.schema';

@ApiTags('User Notifications')
@Controller('api/v1/users/:dni/user-notifications')
export class UserNotificationsController {
  
  constructor(
    @InjectModel(User.name) private userModel: Model<User>,
    @InjectModel(UserNotification.name) private userNotifModel: Model<UserNotification>,
  ) {}

  @Get()
  @ApiOperation({ summary: 'Historial de notificaciones del usuario por DNI' })
  @ApiParam({ name: 'dni' })
  @ApiQuery({ name: 'status', required: false, enum: ['NEW', 'READ', 'HIDDEN'] })
  @ApiQuery({ name: 'page', required: false, example: 1 })
  @ApiQuery({ name: 'limit', required: false, example: 20 })
  async list(
    @Param('dni') dni: string,
    @Query('status') status?: string,
    @Query('page') page = 1,
    @Query('limit') limit = 50,
  ) {
    const user = await this.userModel.findOne({ dni }, { _id: 1 }).lean();
    if (!user) {
      return { data: [], total: 0, page: Number(page), limit: Number(limit), totalPages: 0 };
    }

    const filter: any = { userId: user._id };
    if (status) filter.status = status;

    const skip = (Number(page) - 1) * Number(limit);
    const [data, total] = await Promise.all([
      this.userNotifModel.find(filter).sort({ createdAt: -1 }).skip(skip).limit(Number(limit)).lean(),
      this.userNotifModel.countDocuments(filter),
    ]);

    return {
      data,
      total,
      page: Number(page),
      limit: Number(limit),
      totalPages: Math.ceil(total / Number(limit)),
    };
  }
}

import { IsArray, IsString, IsObject, ArrayNotEmpty } from 'class-validator';

export class DirectPushDto {
  @IsArray()
  @ArrayNotEmpty()
  tokens!: string[]; // tokens FCM específicos de esta app

  @IsObject()
  notification!: { title: string; body: string };

  @IsObject()
  data!: Record<string, string>;
}

import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Types } from 'mongoose';

export type NotificationLogDocument = NotificationLog & Document;

@Schema({ timestamps: true, collection: 'notification_logs' })
export class NotificationLog {
  @Prop({ required: true, enum: ['announce_count', 'generic'] })
  type: 'announce_count' | 'generic';

  @Prop({ required: true })
  topic: string;

  @Prop() locationId?: string;
  @Prop() tableId?: string;

  @Prop() title?: string;
  @Prop() body?: string;

  @Prop({ type: Object }) data?: Record<string, any>;

  @Prop({ required: true, enum: ['SENT', 'FAILED'] })
  status: 'SENT' | 'FAILED';

  @Prop() messageId?: string;
  @Prop() error?: string;
}

export const NotificationLogSchema =
  SchemaFactory.createForClass(NotificationLog);
NotificationLogSchema.index({ locationId: 1, createdAt: -1 });
NotificationLogSchema.index({ topic: 1, createdAt: -1 });
NotificationLogSchema.index({ topic: 1, createdAt: -1, _id: -1 });

import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import { NotificationLog } from '../schemas/notification-log.schema';
import { Inject, Injectable } from '@nestjs/common';
import * as admin from 'firebase-admin';
import { User } from '@/modules/users/schemas/user.schema';
import { UserNotification } from '../schemas/user-notification.schema';

@Injectable()
export class TopicMessagingService {
  constructor(
    @Inject('FIREBASE_ADMIN') private readonly fb: typeof admin,
    @InjectModel(NotificationLog.name) private logModel: Model<NotificationLog>,
    @InjectModel(User.name) private userModel: Model<User>,
    @InjectModel(UserNotification.name)
    private userNotifModel: Model<UserNotification>,
  ) {}

  private makeTopic(locationId: string) {
    const clean = String(locationId || '').replace(/[^A-Za-z0-9_-]/g, '');
    return `loc_${clean}`;
  }

  async announceCountToLocation(params: {
    locationId: string;
    locationName?: string;
    locationAddress?: string;
    tableId?: string;
    tableNumber?: number | string;
    tableCode?: string;
    title?: string;
    body?: string;
  }) {
    const topic = this.makeTopic(params.locationId);
    const data: Record<string, string> = {
      type: 'announce_count',
      locationId: params.locationId,
      locationName: params.locationName ?? '',
      locationAddress: params.locationAddress ?? '',
      screen: 'CountTableDetail',
      tableId: params.tableId ?? '',
      ...(params.tableCode ? { tableCode: String(params.tableCode) } : {}),
      ...(params.tableNumber != null
        ? { tableNumber: String(params.tableNumber) }
        : {}),
    };
    const message: admin.messaging.Message = {
      topic,
      notification: {
        title: params.title ?? 'Inicio de conteo',
        body:
          params.body ??
          `Se anunció conteo en ${params.locationName ?? 'el recinto'}`,
      },
      data,
      android: { priority: 'high' },
      apns: { headers: { 'apns-priority': '10' } },
    };

    try {
      const res = await this.fb.messaging().send(message);

      await this.logModel.create({
        type: 'announce_count',
        topic,
        locationId: params.locationId,
        tableId: params.tableId,
        title: message.notification?.title,
        body: message.notification?.body,
        data,
        status: 'SENT',
        messageId: res,
      });

      const locObjId = new Types.ObjectId(params.locationId);
      const users = await this.userModel
        .find({ votingLocationId: locObjId }, { _id: 1, dni: 1 })
        .lean();

        

      if (users.length) {
        const batch = users.map((u) => ({
          userId: u._id as any,
          dni: u.dni,
          topic,
          locationId: params.locationId,
          tableId: params.tableId,
          title: message.notification?.title,
          body: message.notification?.body,
          data: message.data,
          status: 'NEW',
        }));
        await this.userNotifModel.insertMany(batch, { ordered: false });
      }

      return res;
    } catch (e: any) {
      await this.logModel.create({
        type: 'announce_count',
        topic,
        locationId: params.locationId,
        tableId: params.tableId,
        title: message.notification?.title,
        body: message.notification?.body,
        data,
        status: 'FAILED',
        error: e?.message || String(e),
      });
      throw e;
    }
  }
}

