import {
  Controller,
  Get,
  Param,
  Post,
  Body,
  HttpCode,
  HttpStatus,
  Patch,
  Query,
  UseGuards,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiParam,
  ApiBody,
} from '@nestjs/swagger';
import { UsersService } from '../services/users.service';
import { RegisterUserByDniDto, UserResponseDto } from '../dto/users.dto';
import {
  UpdateVotePlaceDto,
  VotePlaceResponseDto,
} from '../dto/update-vote-place.dto';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { NotificationLog } from '@/modules/notifications/schemas/notification-log.schema';
import {
  AttestParticipationDto,
  AttestParticipationResponseDto,
  ParticipationCertificateDto,
} from '../dto/attest-participation.dto';
import { Public } from '@/core/decorators/public.decorator';
import { ZkAuthGuard } from '@/core/guards/zk-auth.guard';

@ApiTags('Users')
@Controller('api/v1/users')
export class UsersController {
  constructor(
    private readonly usersService: UsersService,
    @InjectModel(NotificationLog.name)
    private logModel: Model<NotificationLog>,
  ) {}

  @Post('register')
  @HttpCode(HttpStatus.CREATED)
  @ApiOperation({ summary: 'Registrar un usuario por DNI' })
  @ApiBody({
    schema: {
      properties: { dni: { type: 'string', example: '12345678' } },
      required: ['dni'],
    },
  })
  @ApiResponse({
    status: 201,
    description: 'Usuario creado o existente',
    type: UserResponseDto,
  })
  async register(@Body() body: RegisterUserByDniDto) {
    const user = await this.usersService.findOrCreateByDni(body.dni);
    return {
      _id: user._id.toString(),
      dni: user.dni,
      active: user.active,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    };
  }

  @Get(':dni')
  @Public()
  @UseGuards(ZkAuthGuard)
  @ApiOperation({ summary: 'Obtener usuario por DNI' })
  @ApiParam({ name: 'dni' })
  @ApiResponse({ status: 200, type: UserResponseDto })
  async getByDni(@Param('dni') dni: string) {
    const user = await this.usersService.findByDni(dni);
    return {
      _id: user._id.toString(),
      dni: user.dni,
      active: user.active,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    };
  }

  @Patch(':dni/vote-place')
  @Public()
  @UseGuards(ZkAuthGuard)
  @ApiOperation({
    summary: 'Guardar/editar recinto y/o mesa de votación para un DNI',
    description:
      'Permite editar parcialmente: solo locationId, solo tableId/tableCode o ambos. Si cambias de recinto y la mesa anterior no pertenece al nuevo recinto, la mesa se borra.',
  })
  @ApiParam({ name: 'dni' })
  @ApiBody({ type: UpdateVotePlaceDto })
  @ApiResponse({ status: 200, type: VotePlaceResponseDto })
  updateVotePlace(
    @Param('dni') dni: string,
    @Body() dto: UpdateVotePlaceDto,
  ): Promise<VotePlaceResponseDto> {
    return this.usersService.updateVotePlaceByDni(dni, dto);
  }

  @Get(':dni/vote-place')
  @Public()
  @ApiOperation({
    summary: 'Obtener recinto/mesa de votación del usuario por DNI',
  })
  @ApiParam({ name: 'dni' })
  @ApiResponse({ status: 200, type: VotePlaceResponseDto })
  getVotePlace(@Param('dni') dni: string): Promise<VotePlaceResponseDto> {
    return this.usersService.getVotePlaceByDni(dni);
  }

  @Get(':dni/notifications')
  @Public()
  @UseGuards(ZkAuthGuard)
  @ApiOperation({
    summary:
      'Notificaciones del usuario por DNI (topic del recinto y fallback por usuario)',
  })
  @ApiParam({ name: 'dni' })
  @ApiResponse({ status: 200, description: 'Lista paginada' })
  async listNotificationsByDni(
    @Param('dni') dni: string,
    @Query('page') page = 1,
    @Query('limit') limit = 50,
  ) {
    const user = await this.usersService.findOrCreateByDni(dni);
    const locId = (user as any)?.votingLocationId?.toString();

    const topics: string[] = [];
    if (locId) {
      const safeLoc = String(locId).replace(/[^A-Za-z0-9_-]/g, '');
      topics.push(`loc_${safeLoc}`);
    }
    topics.push(`user_${user._id.toString()}`);

    const skip = (Number(page) - 1) * Number(limit);

    const [data, total] = await Promise.all([
      this.logModel
        .find({ topic: { $in: topics } })
        .sort({ createdAt: -1, _id: -1 }) // _id como respaldo
        .skip(skip)
        .limit(Number(limit))
        .lean(),
      this.logModel.countDocuments({ topic: { $in: topics } }),
    ]);

    return {
      data,
      total,
      page: Number(page),
      limit: Number(limit),
      totalPages: Math.ceil(total / Number(limit)),
    };
  }

  @Post(':dni/participation-nft')
  @Public()
  @UseGuards(ZkAuthGuard)
  @ApiOperation({
    summary:
      'Emitir NFT de participación para un usuario (attest) y registrar el certificado',
    description:
      'Recibe DNI (path), account e imageUrl (body). Hace safeMint y guarda el certificado (sin address) asociado al usuario.',
  })
  @ApiParam({ name: 'dni' })
  @ApiBody({ type: AttestParticipationDto })
  @ApiResponse({ status: 201, type: AttestParticipationResponseDto })
  async attestParticipationNft(
    @Param('dni') dni: string,
    @Body() dto: AttestParticipationDto,
  ): Promise<AttestParticipationResponseDto> {
    const result = await this.usersService.attestParticipationNft(dni, dto);

    try {
      const user = await this.usersService.findOrCreateByDni(dni);
      // Notificación personal: evitar duplicados en la bandeja por topic de ubicación.
      const topics: string[] = [`user_${user._id.toString()}`];

      const routeParamsPayload: Record<string, unknown> = {
        certificateData: {
          imageUrl: result.imageUrl,
        },
        nftData: {
          nftUrl: result.imageUrl,
        },
      };
      if (result.ipfsUri || result.actaImageUrl) {
        routeParamsPayload.ipfsData = {
          jsonUrl: result.ipfsUri || undefined,
          imageUrl: result.actaImageUrl || undefined,
          ipfsUri: result.ipfsUri || undefined,
        };
      }

      const notificationType =
        dto.notificationType === 'participation_certificate'
          ? 'participation_certificate'
          : 'acta_published';
      const mesaLabel = String(dto.tableNumber || dto.tableCode || '').trim();
      const isParticipation = notificationType === 'participation_certificate';

      const payload = {
        title: isParticipation
          ? 'Atestiguamiento exitoso'
          : 'Acta subida exitosamente',
        body: isParticipation
          ? mesaLabel
            ? `Atestiguamiento exitoso.`
            : 'Tu atestiguamiento se registró correctamente.'
          : mesaLabel
            ? `Tu acta de la mesa ${mesaLabel} fue publicada correctamente.`
            : 'Tu acta fue publicada correctamente.',
        data: {
          type: notificationType,
          dni: user.dni,
          userId: user._id.toString(),
          electionId: result.electionId ?? '',
          imageUrl: result.imageUrl,
          ipfsUri: result.ipfsUri ?? '',
          actaImageUrl: result.actaImageUrl ?? '',
          tableCode: dto.tableCode ?? '',
          tableNumber: dto.tableNumber ?? '',
          txHash: result.txHash,
          chainId: result.chainId,
          contractAddress: result.contractAddress,
          screen: 'SuccessScreen',
          routeParams: JSON.stringify(routeParamsPayload),
        },
      };

      await Promise.all(
        topics.map((topic) =>
          this.logModel.create({
            type: 'generic',
            topic,
            title: payload.title,
            body: payload.body,
            data: payload.data,
            status: 'SENT', 
          }),
        ),
      );
    } catch (e) {
      // no romper el flujo si falla el log
    }

    return result;
  }

  @Get(':dni/participation-certificates')
  @ApiOperation({
    summary: 'Listar certificados de participación (NFTs) por DNI',
  })
  @ApiParam({ name: 'dni' })
  @ApiResponse({
    status: 200,
    schema: {
      properties: {
        userId: { type: 'string' },
        dni: { type: 'string' },
        certificates: {
          type: 'array',
          items: { $ref: '#/components/schemas/ParticipationCertificateDto' },
        },
      },
    },
  })
  async listParticipationCertificates(@Param('dni') dni: string): Promise<{
    userId: string;
    dni: string;
    certificates: ParticipationCertificateDto[];
  }> {
    return this.usersService.listParticipationCertificatesByDni(dni) as any;
  }
}

import {
  BadRequestException,
  Injectable,
  NotFoundException,
  InternalServerErrorException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { ConfigService } from '@nestjs/config';
import { Model, Types } from 'mongoose';
import { User, UserDocument } from '../schemas/user.schema';
import { ElectoralTable } from '@/modules/geographic/schemas/electoral-table.schema';
import { ElectoralLocation } from '@/modules/geographic/schemas/electoral-location.schema';
import {
  UpdateVotePlaceDto,
  VotePlaceResponseDto,
} from '../dto/update-vote-place.dto';
import {
  AttestParticipationDto,
  AttestParticipationResponseDto,
} from '../dto/attest-participation.dto';

import { encodeFunctionData } from 'viem';
import participationAbi from '@/abi/participation.json';
import { availableNetworks } from '@/api/params';
import { executeOperation } from '@/api/account';
import { normalizeCarnet } from '@/modules/institutional-voting/utils/carnet-normalizer';

@Injectable()
export class UsersService {
  constructor(
    @InjectModel(User.name) private userModel: Model<UserDocument>,
    @InjectModel(ElectoralTable.name)
    private electoralTableModel: Model<ElectoralTable>,
    @InjectModel(ElectoralLocation.name)
    private electoralLocationModel: Model<ElectoralLocation>,
    private readonly configService: ConfigService,
  ) {}

  async findByDni(dni: string): Promise<UserDocument> {
    const normalizedDni = this.normalizeDni(dni);
    const user = await this.userModel.findOne({ dni: normalizedDni }).exec();
    if (!user) {
      throw new NotFoundException(`Usuario con DNI ${normalizedDni} no encontrado`);
    }
    return user;
  }

  async findOrCreateByDni(dni: string): Promise<UserDocument> {
    const normalizedDni = this.normalizeDni(dni);
    try {
      const user = await this.userModel
        .findOneAndUpdate(
          { dni: normalizedDni },
          { $setOnInsert: { dni: normalizedDni, active: true } },
          { upsert: true, returnDocument: 'after', setDefaultsOnInsert: true },
        )
        .orFail()
        .exec();

      return user as UserDocument;
    } catch (e: any) {
      if (e?.code === 11000) {
        return this.userModel.findOne({ dni: normalizedDni }).orFail().exec();
      }
      throw e;
    }
  }

  private normalizeDni(dni: string): string {
    const normalized = normalizeCarnet(dni);
    if (normalized) {
      return normalized;
    }

    const fallback = String(dni ?? '').trim();
    if (!fallback) {
      throw new BadRequestException('DNI inválido');
    }

    return fallback;
  }

  async updateVotePlaceByDni(
    dni: string,
    dto: UpdateVotePlaceDto,
  ): Promise<VotePlaceResponseDto> {
    if (!dni) throw new BadRequestException('DNI requerido');

    const user = await this.findOrCreateByDni(dni);

    const update: Partial<UserDocument> = {};
    let locationId: Types.ObjectId | null | undefined = undefined;
    let tableId: Types.ObjectId | null | undefined = undefined;

    if (dto.locationId) {
      const locId = new Types.ObjectId(dto.locationId);
      const exists = await this.electoralLocationModel.exists({ _id: locId });
      if (!exists) throw new NotFoundException('Recinto no encontrado');
      locationId = locId;
    }

    if (dto.tableId || dto.tableCode) {
      const table = await (dto.tableId
        ? this.electoralTableModel.findById(dto.tableId).lean()
        : this.electoralTableModel
            .findOne({ tableCode: dto.tableCode })
            .lean());

      if (!table) throw new NotFoundException('Mesa no encontrada');

      if (locationId) {
        const tLoc: any =
          (table as any).locationId || (table as any).electoralLocationId;
        if (tLoc && !new Types.ObjectId(tLoc).equals(locationId)) {
          throw new BadRequestException(
            'La mesa seleccionada no pertenece al recinto indicado',
          );
        }
      }

      tableId = table._id as Types.ObjectId;

      if (!locationId) {
        const inferredLoc: any =
          (table as any).locationId || (table as any).electoralLocationId;
        if (inferredLoc) locationId = new Types.ObjectId(inferredLoc);
      }
    }

    if (typeof locationId !== 'undefined' && !tableId && user.votingTableId) {
      try {
        const prev = await this.electoralTableModel
          .findById(user.votingTableId)
          .lean();
        const prevLoc: any =
          prev &&
          ((prev as any).locationId || (prev as any).electoralLocationId);
        if (prevLoc && !new Types.ObjectId(prevLoc).equals(locationId)) {
          update.votingTableId = null;
        }
      } catch {}
    }

    if (typeof locationId !== 'undefined') update.votingLocationId = locationId;
    if (typeof tableId !== 'undefined') update.votingTableId = tableId;

    await this.userModel.updateOne({ _id: user._id }, { $set: update });

    const fresh = await this.userModel
      .findById(user._id)
      .populate('votingLocationId', 'name address code')
      .populate('votingTableId', 'tableCode tableNumber')
      .lean();

    return {
      userId: user._id.toString(),
      dni: user.dni,
      location: fresh?.votingLocationId
        ? {
            _id: (fresh.votingLocationId as any)._id.toString(),
            name: (fresh.votingLocationId as any).name,
            address: (fresh.votingLocationId as any).address,
            code: (fresh.votingLocationId as any).code,
          }
        : null,
      table: fresh?.votingTableId
        ? {
            _id: (fresh.votingTableId as any)._id.toString(),
            tableCode: (fresh.votingTableId as any).tableCode,
            tableNumber: (fresh.votingTableId as any).tableNumber,
          }
        : null,
    };
  }

  async getVotePlaceByDni(dni: string): Promise<VotePlaceResponseDto> {
    if (!dni) throw new BadRequestException('DNI requerido');

    const user = await this.findOrCreateByDni(dni);
    const fresh = await this.userModel
      .findById(user._id)
      .populate('votingLocationId', 'name address code')
      .populate('votingTableId', 'tableCode tableNumber')
      .lean();

    return {
      userId: user._id.toString(),
      dni: user.dni,
      location: fresh?.votingLocationId
        ? {
            _id: (fresh.votingLocationId as any)._id.toString(),
            name: (fresh.votingLocationId as any).name,
            address: (fresh.votingLocationId as any).address,
            code: (fresh.votingLocationId as any).code,
          }
        : null,
      table: fresh?.votingTableId
        ? {
            _id: (fresh.votingTableId as any)._id.toString(),
            tableCode: (fresh.votingTableId as any).tableCode,
            tableNumber: (fresh.votingTableId as any).tableNumber,
          }
        : null,
    };
  }

  async attestParticipationNft(
    dni: string,
    dto: AttestParticipationDto,
  ): Promise<AttestParticipationResponseDto> {
    if (!dni) throw new BadRequestException('DNI requerido');

    const user = await this.findOrCreateByDni(dni);

    const { txHash, chainId, contractAddress } =
      await this.executeParticipationOperation(dto.account, dto.imageUrl);

    await this.userModel.updateOne(
      { _id: user._id },
      {
        $push: {
          participationCertificates: {
            imageUrl: dto.imageUrl,
            txHash,
            chainId,
            contractAddress,
            electionId: dto.electionId ?? null,
            createdAt: new Date(),
          },
        },
      },
    );

    return {
      userId: user._id.toString(),
      dni: user.dni,
      imageUrl: dto.imageUrl,
      txHash,
      chainId,
      contractAddress,
      electionId: dto.electionId ?? null,
      ipfsUri: dto.ipfsUri ?? null,
      actaImageUrl: dto.actaImageUrl ?? null,
    };
  }

  async listParticipationCertificatesByDni(dni: string) {
    if (!dni) throw new BadRequestException('DNI requerido');

    const user = await this.findOrCreateByDni(dni);

    return {
      userId: user._id.toString(),
      dni: user.dni,
      certificates: user.participationCertificates ?? [],
    };
  }

  private async executeParticipationOperation(
    accountAddress: string,
    imageUrl: string,
  ): Promise<{
    txHash: string;
    chainId: number;
    contractAddress: string;
  }> {
    const privateKey = this.configService.get<string>(
      'app.blockchain.participationPrivateKey',
    );
    const chainKey = this.configService.get<string>(
      'app.blockchain.operationChainKey',
    );

    if (!privateKey) {
      throw new InternalServerErrorException(
        'NFT_PARTICIPATION_PRIVATE_KEY no configurado',
      );
    }

    const network = (availableNetworks as any)[chainKey ?? ''];
    if (!network || !network.participationNft) {
      throw new InternalServerErrorException(
        `Red o participationNft no configurados para ${chainKey}`,
      );
    }

    const callData = {
      to: network.participationNft as `0x${string}`,
      value: BigInt(0),
      data: encodeFunctionData({
        abi: participationAbi as any,
        functionName: 'safeMint',
        args: [accountAddress as `0x${string}`, imageUrl],
      }),
    };

    const { receipt } = await executeOperation(
      privateKey,
      undefined,
      chainKey,
      callData,
    );

    return {
      txHash: receipt.transactionHash as string,
      chainId: network.chain.id,
      contractAddress: network.participationNft,
    };
  }
}

import {
  Body,
  Controller,
  Get,
  Param,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import {
  ApiBody,
  ApiOperation,
  ApiParam,
  ApiQuery,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';
import { Public } from '@/core/decorators/public.decorator';
import { ZkAuthGuard } from '@/core/guards/zk-auth.guard';
import { VotingPeriodGuard } from '@/modules/elections/guards/voting-period.guard';
import {
  CompareWorksheetDto,
  CompareWorksheetResponseDto,
  CreateWorksheetFromIpfsDto,
  RetryWorksheetFromIpfsDto,
  WorksheetDetailResponseDto,
  WorksheetStatusResponseDto,
} from '../dto/worksheet.dto';
import { WorksheetService } from '../services/worksheet.service';

@ApiTags('Worksheets')
@Controller('api/v1/worksheets')
export class WorksheetController {
  constructor(private readonly worksheetService: WorksheetService) {}

  @Post('from-ipfs')
  @Public()
  @UseGuards(VotingPeriodGuard, ZkAuthGuard)
  @ApiOperation({
    summary: 'Registrar hoja de trabajo privada desde IPFS',
  })
  @ApiBody({ type: CreateWorksheetFromIpfsDto })
  @ApiResponse({
    status: 201,
    description: 'Hoja de trabajo registrada',
    type: WorksheetStatusResponseDto,
  })
  createFromIpfs(@Body() dto: CreateWorksheetFromIpfsDto) {
    return this.worksheetService.createFromIpfs(dto);
  }

  @Post('retry')
  @Public()
  @UseGuards(VotingPeriodGuard, ZkAuthGuard)
  @ApiOperation({
    summary: 'Reintentar subida de hoja de trabajo fallida',
  })
  @ApiBody({ type: RetryWorksheetFromIpfsDto })
  @ApiResponse({
    status: 200,
    description: 'Reintento procesado',
    type: WorksheetStatusResponseDto,
  })
  retryFromIpfs(@Body() dto: RetryWorksheetFromIpfsDto) {
    return this.worksheetService.retryFailedFromIpfs(dto);
  }

  @Get(':dni/by-table/:tableCode')
  @Public()
  @UseGuards(ZkAuthGuard)
  @ApiOperation({
    summary: 'Consultar estado de hoja de trabajo por usuario/mesa/elección',
  })
  @ApiParam({ name: 'dni' })
  @ApiParam({ name: 'tableCode' })
  @ApiQuery({ name: 'electionId', required: true })
  @ApiResponse({
    status: 200,
    description: 'Estado de hoja encontrado o NOT_FOUND',
    type: WorksheetStatusResponseDto,
  })
  async getStatusByTable(
    @Param('dni') dni: string,
    @Param('tableCode') tableCode: string,
    @Query('electionId') electionId: string,
  ): Promise<any> {
    const worksheet = await this.worksheetService.getStatusByTable(
      dni,
      electionId,
      tableCode,
    );

    if (!worksheet) {
      return {
        status: 'NOT_FOUND',
      };
    }

    return {
      id: String((worksheet as any)._id),
      status: worksheet.status,
      tableCode: worksheet.tableCode,
      tableNumber: worksheet.tableNumber,
      ipfsUri: worksheet.ipfsUri,
      nftLink: worksheet.nftLink,
      errorMessage: worksheet.errorMessage,
    };
  }

  @Get(':dni/by-table/:tableCode/detail')
  @Public()
  @UseGuards(ZkAuthGuard)
  @ApiOperation({
    summary:
      'Consultar detalle de hoja de trabajo (incluye imagen y votos) por usuario/mesa/elección',
  })
  @ApiParam({ name: 'dni' })
  @ApiParam({ name: 'tableCode' })
  @ApiQuery({ name: 'electionId', required: true })
  @ApiResponse({
    status: 200,
    description: 'Detalle de hoja encontrado o NOT_FOUND',
    type: WorksheetDetailResponseDto,
  })
  async getDetailByTable(
    @Param('dni') dni: string,
    @Param('tableCode') tableCode: string,
    @Query('electionId') electionId: string,
  ): Promise<any> {
    const worksheet = await this.worksheetService.getStatusByTable(
      dni,
      electionId,
      tableCode,
    );

    if (!worksheet) {
      return {
        status: 'NOT_FOUND',
      };
    }

    return {
      id: String((worksheet as any)._id),
      status: worksheet.status,
      tableCode: worksheet.tableCode,
      tableNumber: worksheet.tableNumber,
      ipfsUri: worksheet.ipfsUri,
      nftLink: worksheet.nftLink,
      errorMessage: worksheet.errorMessage,
      image: worksheet.image,
      votes: worksheet.votes,
    };
  }

  @Post('compare')
  @Public()
  @UseGuards(ZkAuthGuard)
  @ApiOperation({
    summary:
      'Comparar resultados del acta oficial contra hoja de trabajo privada del usuario',
  })
  @ApiBody({ type: CompareWorksheetDto })
  @ApiResponse({
    status: 200,
    description:
      'Devuelve MATCH/MISMATCH/NOT_AVAILABLE/NOT_FOUND sin bloquear el flujo',
    type: CompareWorksheetResponseDto,
  })
  compare(@Body() dto: CompareWorksheetDto) {
    return this.worksheetService.compareAgainstWorksheet(dto);
  }
}

import {
  BadRequestException,
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model, Types } from 'mongoose';
import { UsersService } from '@/modules/users/services/users.service';
import { ElectionConfigService } from '@/modules/elections/services/election-config.service';
import { TableCodeValidationService } from '@/modules/table-code-validation/services/table-code-validation.service';
import { ElectoralTableService } from '@/modules/geographic/services/electoral-table.service';
import {
  CompareWorksheetDto,
  CompareWorksheetResponseDto,
  CreateWorksheetFromIpfsDto,
  RetryWorksheetFromIpfsDto,
  WorksheetCompareStatus,
  WorksheetVotesDto,
} from '../dto/worksheet.dto';
import {
  Worksheet,
  WorksheetDocument,
  WorksheetStatus,
} from '../schemas/worksheet.schema';
import { NotificationLog } from '@/modules/notifications/schemas/notification-log.schema';

interface OpenSeaMetadata {
  image?: string;
  data?: {
    tableCode?: string;
    tableNumber?: string;
    locationId?: string;
    image?: string;
    votes?: WorksheetVotesDto;
  };
}

interface WorksheetExtractedData {
  tableCode?: string;
  tableNumber?: string;
  locationId?: string;
  image?: string;
  votes?: WorksheetVotesDto;
}

interface VoteDifference {
  field: string;
  worksheetValue: number | null;
  ballotValue: number | null;
}

@Injectable()
export class WorksheetService {
  constructor(
    @InjectModel(Worksheet.name)
    private readonly worksheetModel: Model<WorksheetDocument>,
    @InjectModel(NotificationLog.name)
    private readonly notificationLogModel: Model<NotificationLog>,
    private readonly usersService: UsersService,
    private readonly electionConfigService: ElectionConfigService,
    private readonly tableCodeValidationService: TableCodeValidationService,
    private readonly electoralTableService: ElectoralTableService,
  ) {}

  async createFromIpfs(dto: CreateWorksheetFromIpfsDto): Promise<Worksheet> {
    return this.processFromIpfs(dto, false);
  }

  async retryFailedFromIpfs(dto: RetryWorksheetFromIpfsDto): Promise<Worksheet> {
    return this.processFromIpfs(dto, true);
  }

  async getStatusByTable(
    dni: string,
    electionId: string,
    tableCode: string,
  ): Promise<Worksheet | null> {
    const normalizedDni = this.normalizeDni(dni);
    const normalizedTableCode = this.normalizeTableCode(tableCode);
    const electionObjectId = await this.resolveElectionId(electionId);

    return this.worksheetModel
      .findOne({
        dni: normalizedDni,
        electionId: electionObjectId,
        tableCode: normalizedTableCode,
      })
      .lean();
  }

  async compareAgainstWorksheet(
    dto: CompareWorksheetDto,
  ): Promise<CompareWorksheetResponseDto> {
    const normalizedDni = this.normalizeDni(dto.dni);
    const normalizedTableCode = this.normalizeTableCode(dto.tableCode);
    const electionObjectId = await this.resolveElectionId(dto.electionId);

    const worksheet = await this.worksheetModel.findOne({
      dni: normalizedDni,
      electionId: electionObjectId,
      tableCode: normalizedTableCode,
    });

    if (!worksheet) {
      return {
        status: WorksheetCompareStatus.NOT_FOUND,
        differences: [],
      };
    }

    if (worksheet.status !== WorksheetStatus.UPLOADED || !worksheet.votes) {
      return {
        status: WorksheetCompareStatus.NOT_AVAILABLE,
        worksheetStatus: worksheet.status,
        differences: [],
      };
    }

    const differences = this.compareVotes(worksheet.votes as any, dto.votes);

    return {
      status:
        differences.length > 0
          ? WorksheetCompareStatus.MISMATCH
          : WorksheetCompareStatus.MATCH,
      worksheetStatus: worksheet.status,
      differences,
    };
  }

  private async processFromIpfs(
    dto: CreateWorksheetFromIpfsDto,
    retryOnlyFailed: boolean,
  ): Promise<Worksheet> {
    const normalizedDni = this.normalizeDni(dto.dni);
    const electionObjectId = await this.resolveElectionId(dto.electionId);
    const normalizedTableCodeFallback = this.normalizeTableCode(dto.tableCode);

    let existing: WorksheetDocument | null = null;
    if (normalizedTableCodeFallback) {
      existing = await this.worksheetModel.findOne({
        dni: normalizedDni,
        electionId: electionObjectId,
        tableCode: normalizedTableCodeFallback,
      });
    }

    if (retryOnlyFailed) {
      if (!normalizedTableCodeFallback) {
        throw new BadRequestException('tableCode es requerido para reintentar');
      }
      if (!existing) {
        throw new NotFoundException(
          'No existe hoja de trabajo fallida para reintentar',
        );
      }
      if (existing.status !== WorksheetStatus.FAILED) {
        throw new BadRequestException(
          `Solo se puede reintentar una hoja en estado ${WorksheetStatus.FAILED}`,
        );
      }
    }

    try {
      const ipfsMetadata = await this.fetchFromIpfs(dto.ipfsUri);
      const extractedData = this.extractWorksheetData(ipfsMetadata);
      const mergedData = this.mergeWorksheetData(extractedData, dto);

      const normalizedTableCode = this.normalizeTableCode(mergedData.tableCode);
      if (!normalizedTableCode) {
        throw new BadRequestException(
          'No se pudo determinar el tableCode de la hoja de trabajo',
        );
      }

      const user = await this.usersService.findOrCreateByDni(normalizedDni);

      existing =
        existing ??
        (await this.worksheetModel.findOne({
          dni: normalizedDni,
          electionId: electionObjectId,
          tableCode: normalizedTableCode,
        }));

      if (existing && !retryOnlyFailed) {
        if (existing.status === WorksheetStatus.UPLOADED) {
          throw new ConflictException(
            'La hoja de trabajo ya fue subida para esta mesa y elección',
          );
        }
        if (existing.status === WorksheetStatus.PENDING) {
          throw new ConflictException(
            'La hoja de trabajo ya está pendiente de subida',
          );
        }
      }

      if (retryOnlyFailed && (!existing || existing.status !== WorksheetStatus.FAILED)) {
        throw new BadRequestException(
          'La hoja de trabajo no está en estado fallido para reintento',
        );
      }

      await this.validateWorksheetData(mergedData, electionObjectId);

      const now = new Date();
      const payload: Partial<Worksheet> = {
        userId: user._id,
        dni: normalizedDni,
        electionId: electionObjectId,
        tableCode: normalizedTableCode,
        tableNumber: mergedData.tableNumber,
        electoralLocationId: this.asObjectId(mergedData.locationId),
        votes: mergedData.votes as any,
        image: mergedData.image,
        ipfsUri: dto.ipfsUri,
        ipfsCid: this.extractCidFromUri(dto.ipfsUri),
        recordId: dto.recordId,
        tableIdIpfs: dto.tableIdIpfs,
        nftLink: dto.nftLink,
        status: WorksheetStatus.UPLOADED,
        errorMessage: undefined,
        lastAttemptAt: now,
        uploadedAt: now,
      };

      if (existing) {
        existing.userId = payload.userId as Types.ObjectId;
        existing.dni = payload.dni as string;
        existing.electionId = payload.electionId as Types.ObjectId;
        existing.tableCode = payload.tableCode as string;
        existing.tableNumber = payload.tableNumber;
        existing.electoralLocationId = payload.electoralLocationId;
        existing.votes = payload.votes as any;
        existing.image = payload.image;
        existing.ipfsUri = payload.ipfsUri as string;
        existing.ipfsCid = payload.ipfsCid;
        existing.recordId = payload.recordId;
        existing.tableIdIpfs = payload.tableIdIpfs;
        existing.nftLink = payload.nftLink;
        existing.status = WorksheetStatus.UPLOADED;
        existing.errorMessage = undefined;
        existing.lastAttemptAt = now;
        existing.uploadedAt = now;
        if (retryOnlyFailed || existing.retryCount > 0) {
          existing.retryCount = (existing.retryCount ?? 0) + 1;
        }
        const saved = await existing.save();

        // Registrar tableCode en electoral_tables para filtros
        await this.ensureTableCodeInElectoralTables(
          payload.tableCode as string,
          payload.electoralLocationId ?? mergedData.locationId,
        );

        await this.tableCodeValidationService.ensurePending(
          electionObjectId,
          payload.tableCode as string,
        );
        await this.notifyWorksheetUploaded({
          userId: String(user._id),
          dni: normalizedDni,
          electionId: electionObjectId.toString(),
          tableCode: payload.tableCode as string,
          tableNumber: String(payload.tableNumber || ''),
          locationId: this.normalizeOptionalString(
            String(payload.electoralLocationId ?? mergedData.locationId ?? ''),
          ),
          ipfsUri: dto.ipfsUri,
          imageUrl: this.normalizeOptionalString(payload.image),
          nftLink: this.normalizeOptionalString(dto.nftLink),
        });
        return saved;
      }

      const created = new this.worksheetModel({
        ...payload,
        retryCount: 0,
      });
      const saved = await created.save();

      // Registrar tableCode en electoral_tables para filtros
      await this.ensureTableCodeInElectoralTables(
        payload.tableCode as string,
        payload.electoralLocationId ?? mergedData.locationId,
      );

      await this.tableCodeValidationService.ensurePending(
        electionObjectId,
        payload.tableCode as string,
      );
      await this.notifyWorksheetUploaded({
        userId: String(user._id),
        dni: normalizedDni,
        electionId: electionObjectId.toString(),
        tableCode: payload.tableCode as string,
        tableNumber: String(payload.tableNumber || ''),
        locationId: this.normalizeOptionalString(
          String(payload.electoralLocationId ?? mergedData.locationId ?? ''),
        ),
        ipfsUri: dto.ipfsUri,
        imageUrl: this.normalizeOptionalString(payload.image),
        nftLink: this.normalizeOptionalString(dto.nftLink),
      });
      return saved;
    } catch (error) {
      if (
        error instanceof ConflictException ||
        error instanceof NotFoundException
      ) {
        throw error;
      }

      await this.saveFailedAttempt(
        dto,
        normalizedDni,
        electionObjectId,
        existing,
        this.parseErrorMessage(error),
      );
      throw error;
    }
  }

  private async saveFailedAttempt(
    dto: CreateWorksheetFromIpfsDto,
    dni: string,
    electionId: Types.ObjectId,
    existing: WorksheetDocument | null,
    errorMessage: string,
  ): Promise<void> {
    const normalizedTableCode = this.normalizeTableCode(
      existing?.tableCode ?? dto.tableCode,
    );
    if (!normalizedTableCode) return;

    const user = await this.usersService.findOrCreateByDni(dni);
    const now = new Date();

    if (existing && existing.status === WorksheetStatus.UPLOADED) {
      return;
    }

    const payload: Partial<Worksheet> = {
      userId: user._id,
      dni,
      electionId,
      tableCode: normalizedTableCode,
      tableNumber: dto.tableNumber ?? existing?.tableNumber,
      electoralLocationId:
        this.asObjectId(dto.locationId) ?? existing?.electoralLocationId,
      votes: (dto.votes as any) ?? existing?.votes,
      image: dto.image ?? existing?.image,
      ipfsUri: dto.ipfsUri ?? existing?.ipfsUri,
      ipfsCid: dto.ipfsUri ? this.tryExtractCid(dto.ipfsUri) : existing?.ipfsCid,
      recordId: dto.recordId ?? existing?.recordId,
      tableIdIpfs: dto.tableIdIpfs ?? existing?.tableIdIpfs,
      nftLink: dto.nftLink ?? existing?.nftLink,
      status: WorksheetStatus.FAILED,
      errorMessage,
      lastAttemptAt: now,
      uploadedAt: existing?.uploadedAt,
    };

    if (existing) {
      existing.userId = payload.userId as Types.ObjectId;
      existing.dni = payload.dni as string;
      existing.electionId = payload.electionId as Types.ObjectId;
      existing.tableCode = payload.tableCode as string;
      existing.tableNumber = payload.tableNumber;
      existing.electoralLocationId = payload.electoralLocationId;
      existing.votes = payload.votes as any;
      existing.image = payload.image;
      existing.ipfsUri = payload.ipfsUri as string;
      existing.ipfsCid = payload.ipfsCid;
      existing.recordId = payload.recordId;
      existing.tableIdIpfs = payload.tableIdIpfs;
      existing.nftLink = payload.nftLink;
      existing.status = WorksheetStatus.FAILED;
      existing.errorMessage = errorMessage;
      existing.lastAttemptAt = now;
      existing.retryCount = (existing.retryCount ?? 0) + 1;
      await existing.save();
      return;
    }

    try {
      await this.worksheetModel.create({
        ...payload,
        retryCount: 0,
      });
    } catch (createError: any) {
      if (createError?.code === 11000) {
        await this.worksheetModel.updateOne(
          { dni, electionId, tableCode: normalizedTableCode },
          {
            $set: {
              status: WorksheetStatus.FAILED,
              errorMessage,
              lastAttemptAt: now,
              ipfsUri: payload.ipfsUri,
            },
            $inc: { retryCount: 1 },
          },
        );
      } else {
        throw createError;
      }
    }
  }

  private async fetchFromIpfs(ipfsUri: string): Promise<OpenSeaMetadata> {
    try {
      let response = await fetch(ipfsUri, {
        headers: { accept: 'application/json' },
      } as any);
      let text = await response.text();

      const isJson = text.trim().startsWith('{') || text.trim().startsWith('[');
      if (!isJson) {
        const cid = this.extractCidFromUri(ipfsUri);
        const gateways = [
          `https://ipfs.io/ipfs/${cid}`,
          `https://cloudflare-ipfs.com/ipfs/${cid}`,
          `https://gateway.pinata.cloud/ipfs/${cid}`,
        ];

        for (const url of gateways) {
          try {
            response = await fetch(url, {
              headers: { accept: 'application/json' },
            } as any);
            text = await response.text();
            if (text.trim().startsWith('{') || text.trim().startsWith('[')) {
              break;
            }
          } catch {}
        }
      }

      if (!(text.trim().startsWith('{') || text.trim().startsWith('['))) {
        throw new Error('Respuesta no JSON desde IPFS');
      }

      return JSON.parse(text) as OpenSeaMetadata;
    } catch {
      throw new BadRequestException('Error al obtener datos de IPFS');
    }
  }

  private extractWorksheetData(metadata: OpenSeaMetadata): WorksheetExtractedData {
    if (!metadata.data) {
      throw new BadRequestException(
        'Formato de metadata inválido: no se encontró el campo data',
      );
    }

    return {
      tableCode: metadata.data.tableCode,
      tableNumber: metadata.data.tableNumber ?? metadata.data.tableCode,
      locationId: metadata.data.locationId,
      image: metadata.image ?? metadata.data.image,
      votes: metadata.data.votes,
    };
  }

  private mergeWorksheetData(
    extracted: WorksheetExtractedData,
    dto: CreateWorksheetFromIpfsDto,
  ): WorksheetExtractedData {
    return {
      tableCode: extracted.tableCode ?? dto.tableCode,
      tableNumber:
        extracted.tableNumber ??
        dto.tableNumber ??
        extracted.tableCode ??
        dto.tableCode,
      locationId: extracted.locationId ?? dto.locationId,
      image: extracted.image ?? dto.image,
      votes: extracted.votes ?? dto.votes,
    };
  }

  private async validateWorksheetData(
    data: WorksheetExtractedData,
    electionId: Types.ObjectId,
  ): Promise<void> {
    const errors: string[] = [];

    if (!data.tableCode) {
      errors.push('tableCode es requerido');
    }
    if (!data.votes || (!data.votes.parties && !data.votes.deputies)) {
      errors.push('Debe incluir al menos una categoría de votos');
    }

    if (data.votes?.parties) {
      errors.push(...this.validateVotingCategory(data.votes.parties, 'parties'));
    }
    if (data.votes?.deputies) {
      errors.push(...this.validateVotingCategory(data.votes.deputies, 'deputies'));
    }

    try {
      await this.electionConfigService.findOne(electionId.toString());
    } catch {
      errors.push('La elección indicada no existe');
    }

    if (errors.length > 0) {
      throw new BadRequestException(`Errores de validación: ${errors.join(', ')}`);
    }
  }

  private validateVotingCategory(
    category: {
      validVotes: number;
      nullVotes: number;
      blankVotes: number;
      partyVotes: Array<{ partyId: string; votes: number }>;
    },
    categoryName: string,
  ): string[] {
    const errors: string[] = [];

    if (typeof category.validVotes !== 'number' || category.validVotes < 0) {
      errors.push(`validVotes inválido en ${categoryName}`);
    }
    if (typeof category.nullVotes !== 'number' || category.nullVotes < 0) {
      errors.push(`nullVotes inválido en ${categoryName}`);
    }
    if (typeof category.blankVotes !== 'number' || category.blankVotes < 0) {
      errors.push(`blankVotes inválido en ${categoryName}`);
    }

    if (!Array.isArray(category.partyVotes)) {
      errors.push(`partyVotes inválido en ${categoryName}`);
      return errors;
    }

    let partyVotesTotal = 0;
    category.partyVotes.forEach((item, idx) => {
      if (!item.partyId || typeof item.partyId !== 'string') {
        errors.push(`partyId inválido en ${categoryName}, posición ${idx}`);
      }
      if (typeof item.votes !== 'number' || item.votes < 0) {
        errors.push(`votes inválido en ${categoryName}, posición ${idx}`);
      }
      partyVotesTotal += Number(item.votes || 0);
    });

    if (partyVotesTotal !== category.validVotes) {
      errors.push(
        `Suma de partyVotes (${partyVotesTotal}) no coincide con validVotes (${category.validVotes}) en ${categoryName}`,
      );
    }

    return errors;
  }

  private compareVotes(
    worksheetVotes: WorksheetVotesDto,
    ballotVotes: WorksheetVotesDto,
  ): VoteDifference[] {
    const differences: VoteDifference[] = [];
    const categories: Array<'parties' | 'deputies'> = ['parties', 'deputies'];
    const summaryFields: Array<'validVotes' | 'nullVotes' | 'blankVotes' | 'totalVotes'> = [
      'validVotes',
      'nullVotes',
      'blankVotes',
      'totalVotes',
    ];

    for (const category of categories) {
      const worksheetCategory = worksheetVotes?.[category];
      const ballotCategory = ballotVotes?.[category];

      if (!worksheetCategory && !ballotCategory) continue;

      if (!worksheetCategory || !ballotCategory) {
        differences.push({
          field: category,
          worksheetValue: worksheetCategory ? 1 : null,
          ballotValue: ballotCategory ? 1 : null,
        });
        continue;
      }

      for (const field of summaryFields) {
        const worksheetValue = this.toComparableNumber(
          (worksheetCategory as any)[field],
        );
        const ballotValue = this.toComparableNumber((ballotCategory as any)[field]);

        if (field === 'totalVotes' && worksheetValue === null && ballotValue === null) {
          continue;
        }

        if (worksheetValue !== ballotValue) {
          differences.push({
            field: `${category}.${field}`,
            worksheetValue,
            ballotValue,
          });
        }
      }

      const worksheetByParty = new Map<string, number>();
      const ballotByParty = new Map<string, number>();

      for (const item of worksheetCategory.partyVotes ?? []) {
        const key = String(item.partyId).trim();
        worksheetByParty.set(key, Number(item.votes ?? 0));
      }

      for (const item of ballotCategory.partyVotes ?? []) {
        const key = String(item.partyId).trim();
        ballotByParty.set(key, Number(item.votes ?? 0));
      }

      const allPartyIds = new Set<string>([
        ...worksheetByParty.keys(),
        ...ballotByParty.keys(),
      ]);

      for (const partyId of allPartyIds) {
        const worksheetValue = worksheetByParty.get(partyId) ?? 0;
        const ballotValue = ballotByParty.get(partyId) ?? 0;

        if (worksheetValue !== ballotValue) {
          differences.push({
            field: `${category}.partyVotes.${partyId}`,
            worksheetValue,
            ballotValue,
          });
        }
      }
    }

    return differences;
  }

  private async resolveElectionId(electionId: string): Promise<Types.ObjectId> {
    if (!Types.ObjectId.isValid(electionId)) {
      throw new BadRequestException('electionId inválido');
    }

    await this.electionConfigService.findOne(electionId);
    return new Types.ObjectId(electionId);
  }

  private normalizeDni(dni: string): string {
    return String(dni ?? '').trim();
  }

  private normalizeTableCode(tableCode?: string): string {
    const value = String(tableCode ?? '').trim();
    return value || '';
  }

  private asObjectId(value?: string): Types.ObjectId | undefined {
    if (!value) return undefined;
    return Types.ObjectId.isValid(value) ? new Types.ObjectId(value) : undefined;
  }

  private parseErrorMessage(error: any): string {
    if (typeof error?.message === 'string' && error.message.length > 0) {
      return error.message;
    }
    return 'Error no controlado al procesar la hoja de trabajo';
  }

  private toComparableNumber(value: any): number | null {
    if (value === null || value === undefined || value === '') return null;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }

  private tryExtractCid(uri: string): string | undefined {
    try {
      return this.extractCidFromUri(uri);
    } catch {
      return undefined;
    }
  }

  private extractCidFromUri(uri: string): string {
    const patterns = [
      /ipfs\.io\/ipfs\/([a-zA-Z0-9]+)/,
      /gateway\.pinata\.cloud\/ipfs\/([a-zA-Z0-9]+)/,
      /([Qm][a-zA-Z0-9]{44,})/,
      /([a-z0-9]{46,})/i,
    ];

    for (const pattern of patterns) {
      const match = uri.match(pattern);
      if (match) return match[1];
    }

    throw new BadRequestException('No se pudo extraer CID de la URI');
  }

  private normalizeOptionalString(value: any): string | undefined {
    const normalized = String(value ?? '').trim();
    return normalized.length ? normalized : undefined;
  }

  private async notifyWorksheetUploaded(params: {
    userId: string;
    dni: string;
    electionId: string;
    tableCode: string;
    tableNumber?: string;
    locationId?: string;
    ipfsUri: string;
    imageUrl?: string;
    nftLink?: string;
  }): Promise<void> {
    try {
      const routeParams = {
        notificationType: 'worksheet_uploaded',
        ipfsData: {
          jsonUrl: params.ipfsUri,
          ipfsUri: params.ipfsUri,
          imageUrl: params.imageUrl,
          url: params.nftLink || params.ipfsUri,
        },
        tableData: {
          tableCode: params.tableCode,
          tableNumber: params.tableNumber,
          idRecinto: params.locationId,
          locationId: params.locationId,
        },
        worksheetData: {
          electionId: params.electionId,
          tableCode: params.tableCode,
          tableNumber: params.tableNumber,
          ipfsUri: params.ipfsUri,
          nftLink: params.nftLink,
        },
      };

      await this.notificationLogModel.create({
        type: 'generic',
        topic: `user_${params.userId}`,
        locationId: params.locationId,
        title: 'Hoja de trabajo subida',
        body: `Mesa ${params.tableNumber || params.tableCode}: tu hoja ya esta disponible para comparacion.`,
        data: {
          type: 'worksheet_uploaded',
          dni: params.dni,
          userId: params.userId,
          electionId: params.electionId,
          tableCode: params.tableCode,
          tableNumber: params.tableNumber || '',
          locationId: params.locationId || '',
          ipfsUri: params.ipfsUri,
          imageUrl: params.imageUrl || '',
          nftLink: params.nftLink || '',
          screen: 'SuccessScreen',
          routeParams: JSON.stringify(routeParams),
        },
        status: 'SENT',
      });
    } catch {
      // No romper la subida por fallo de notificación.
    }
  }

  /**
   * Registra el tableCode en electoral_tables para que aparezca en filtros.
   */
  private async ensureTableCodeInElectoralTables(
    tableCode: string | undefined,
    locationId: string | Types.ObjectId | undefined,
  ): Promise<void> {
    const normalizedCode = String(tableCode || '').trim();
    if (!normalizedCode || !locationId) {
      return;
    }

    try {
      const locationObjectId =
        typeof locationId === 'string'
          ? new Types.ObjectId(locationId)
          : locationId;

      // Usar el servicio para hacer upsert de la mesa
      await this.electoralTableService.ensureByCodeOrPrecinctAndNumber(
        locationObjectId,
        {
          code: normalizedCode,
          number: parseInt(normalizedCode, 10) || 1,
          habilitados: 0,
          inhabilitados: 0,
        },
      );
    } catch {
      // No bloquear la subida del worksheet por este error
    }
  }
}

